local config = {
  ui_story_5084_50840100_1_dialog_content = "Isto é... uma tumba?",
  ui_story_5084_50840100_2_dialog_content = "\"Varaki, seu destino foi revelado, e ainda assim seu coração ainda abriga dúvidas.\"",
  ui_story_5084_50840100_3_dialog_content = "É porque eu entendo o preço a ser pago. Obter poder é tornar-se seu prisioneiro e renunciar a qualquer sensação de paz pelo resto da vida.",
  ui_story_5084_50840100_4_dialog_content = "Eu não desejo ser como meus pais e sofrer por causa da minha força. Eles só encontraram descanso quando a última gota de Varaki desapareceu de seus corpos.",
  ui_story_5084_50840100_5_dialog_content = "\"Você não é um discípulo dos Varaki. Como eu, você adora apenas o Senhor da Verdade.\"",
  ui_story_5084_50840100_6_dialog_content = "\"Como um discípulo da Verdade, você viajou por este mundo e descobriu um grande poder.\"",
  ui_story_5084_50840100_7_dialog_content = "\"Se o seu coração realmente anseia pela chegada do Senhor da Verdade, então você não tem motivos para temer qualquer sacrifício.\"",
  ui_story_5084_50840100_8_dialog_content = "O que você gostaria que eu fizesse?",
  ui_story_5084_50840100_9_dialog_content = "\"Ajude-me a recuperar meu poder e minha forma física. Em troca, extrairei o poder do seu corpo e concederei a você o descanso eterno.\"",
  ui_story_5084_50840100_10_dialog_content = "\"Acho o sabor do perigo muito emocionante.\"",
  ui_story_5084_50840100_11_dialog_content = "\"Pois me permite saborear A Verdade por mim mesmo.\"",
  ui_story_5084_50840100_12_dialog_content = "O que você viu, Senhora Victoria?",
  ui_story_5084_50840100_13_dialog_content = "O momento em que formei um pacto com a Bíblia Sangrenta. Na época, não revelou o futuro deste anel para mim.",
  ui_story_5084_50840100_14_dialog_content = "Mas agora está em minhas mãos mais uma vez... Mesmo antes de colocar os olhos nele, senti um poder antigo me chamando.",
  ui_story_5084_50840100_15_dialog_content = "Uma sensação familiar de formigamento me assombra sempre que o seguro....",
  ui_story_5084_50840100_16_dialog_content = "Você compartilha uma conexão com este anel?",
  ui_story_5084_50840100_17_dialog_content = "Sim. É uma relíquia do antigo Varaki, passada de geração em geração pelos líderes da Verdadeira Ordem.",
  ui_story_5084_50840100_18_dialog_content = "Para que ele retorne ao seu dono original é motivo de celebração.",
  ui_story_5084_50840100_19_dialog_content = "O que mais importa não é o anel em si, mas o momento por trás de sua aparição.",
  ui_story_5084_50840100_20_dialog_content = "À medida que o Advento da Verdade se aproxima, encontro este anel até então perdido em minha posse novamente.",
  ui_story_5084_50840100_21_dialog_content = "...!",
  ui_story_5084_50840100_22_dialog_content = "Senhora Victoria!",
  ui_story_5084_50840100_23_dialog_content = "Hahahaha... Varaki...",
  ui_story_5084_50840100_24_dialog_content = "Você! Agh... Argh!",
  ui_story_5084_50840100_25_dialog_content = "Ahhhhhhhhh—!!!",
  ui_story_5084_50840100_26_dialog_content = "Senhora Victoria!",
  ui_story_5084_50840100_27_dialog_content = "O que eu vi agora há pouco...",
  ui_story_5084_50840100_28_dialog_content = "Parecia uma profecia... E ainda assim, parecia ter acontecido no passado...",
  ui_story_5084_50840100_29_dialog_content = "<color=#e8d9bb>Fwoosh—!</color>",
  ui_story_5084_50840100_30_dialog_content = "\"O catalisador foi invocado.\"",
  ui_story_5084_50840100_31_dialog_content = "\"A tumba aguarda sua chegada.\"",
  ui_story_5084_50840100_32_dialog_content = "\"O conhecimento da Verdade deve ser testado e verificado.\"",
  ui_story_5084_50840100_33_dialog_content = "\"Uma grande cerimônia realizada sob a velha lua.\"",
  ui_story_5084_50840100_34_dialog_content = "\"A hora chegou.\"",
  ui_story_5084_50840100_35_dialog_content = "...",
  ui_story_5084_50840100_36_dialog_content = "Esta revelação parece um tanto obscura, Senhora Victoria.",
  ui_story_5084_50840100_37_dialog_content = "Quando combinada com suas previsões passadas, a revelação do anel é realmente bastante clara.",
  ui_story_5084_50840100_38_dialog_content = "\"Finalmente chegou a hora. Um encontro inesperado ocorrerá durante o Advento da Verdade.\"",
  ui_story_5084_50840100_39_dialog_content = "\"Para confirmar nosso entendimento da Verdade, devemos buscar o guardião da Cripta Estrelada.\"",
  ui_story_5084_50840100_40_dialog_content = "\"Para essa empreitada, precisamos da ajuda do celestita.\"",
  ui_story_5084_50840100_41_dialog_content = "Esta é a primeira vez que a Bíblia Sangrenta tentou obscurecer uma de suas profecias.",
  ui_story_5084_50840100_42_dialog_content = "Parece que as revelações oferecidas por este anel há muito perdido conectarão dias e eventos que nunca foram testemunhados.",
  ui_story_5084_50840100_43_dialog_content = "Acredito que entendi agora.",
  ui_story_5084_50840100_44_dialog_content = "Deixo com você a tarefa de recrutar nosso amigo de sangue fresco.",
  ui_story_5084_50840100_45_dialog_content = "Sim, Senhora Victoria.",
  ui_story_5084_50840100_46_dialog_content = "Eu sei que você já explicou tudo, mas ainda não faz sentido para mim. Por que eu tenho que participar da celebração da Verdadeira Ordem?",
  ui_story_5084_50840100_47_dialog_content = "Perdoe-me, mas estou simplesmente atendendo aos desejos da Senhora Victoria e do Senhor da Verdade.",
  ui_story_5084_50840100_48_dialog_content = "Suspiro, vocês são tão vagos como sempre, vejo...",
  ui_story_5084_50840100_49_dialog_content = "Estamos bem longe de Umbraton agora. Para onde exatamente você está me levando?",
  ui_story_5084_50840100_50_dialog_content = "Uau—",
  ui_story_5084_50840100_51_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5084_50840100_52_dialog_content = "O que é essa coisa de aparência escura... E por que está se movendo?!",
  ui_story_5084_50840100_53_dialog_content = "Ah, então você é quem perturbou meu sono, Bola de Neve.",
  ui_story_5084_50840100_54_dialog_content = "... Sikare?",
  ui_story_5084_50840100_55_dialog_content = "Eu tropecei nas suas videiras agora mesmo?",
  ui_story_5084_50840100_56_dialog_content = "Não é educado continuar fazendo perguntas depois de pisar em alguém. Você realmente deveria pedir desculpas, sabe?",
  ui_story_5084_50840100_57_dialog_content = "S-Desculpe por isso... Então o que você está fazendo aqui, afinal?",
  ui_story_5084_50840100_58_dialog_content = "Eu poderia te perguntar a mesma coisa. O que te trás aqui hoje?",
  ui_story_5084_50840100_59_dialog_content = "É tudo minha culpa. Eu sabia que ia cometer um erro imperdoável hoje.",
  ui_story_5084_50840100_60_dialog_content = "Se não se importa, Senhorita Sikare, gostaria de me arrepender dos meus pecados aqui e agora...",
  ui_story_5084_50840100_61_dialog_content = "Parece que todos estão presentes agora, Senhora Victoria.",
  ui_story_5084_50840100_62_dialog_content = "Senhorita Victoria...",
  ui_story_5084_50840100_63_dialog_content = "Você uma vez me disse que ainda não era a hora, e que os segredos dentro da Cripta Estrelada ainda estavam além do meu entendimento.",
  ui_story_5084_50840100_64_dialog_content = "A Bíblia Sangrenta me guiou até aqui hoje.",
  ui_story_5084_50840100_65_dialog_content = "May Eu pergunto que tipo de artefato você encontrou desta vez?",
  ui_story_5084_50840100_66_dialog_content = "Esse.",
  ui_story_5084_50840100_67_dialog_content = "Se o que você diz é verdade, então você agora tem o privilégio de entrar na Cripta Estrelada.",
  ui_story_5084_50840100_68_dialog_content = "Que tipo de lugar é esse, afinal?",
  ui_story_5084_50840100_69_dialog_content = "Em termos leigos, é um lugar onde os mortos são enterrados.",
  ui_story_5084_50840100_70_dialog_content = "O quê?! Mas... Mas Faust disse que isso era para a próxima celebração da Verdadeira Ordem!",
  ui_story_5084_50840100_71_dialog_content = "Em certo sentido, sim. Pelo bem do que está por vir, devemos primeiro vir para este lugar.",
  ui_story_5084_50840100_72_dialog_content = "Não tenha medo. O que está dentro da Cripta Estrelada é mais valioso do que toda a riqueza de Lumópolis combinada.",
  ui_story_5084_50840100_73_dialog_content = "Inúmeras pessoas vieram em busca dos segredos da cripta, apenas para se encontrarem enterradas aqui. Considerem-se sortudos.",
  ui_story_5084_50840100_74_dialog_content = "M-Mesmo que seja um tesouro, eu... eu mereço algum tempo para pensar sobre isso! Certo...?",
  ui_story_5084_50840100_75_dialog_content = "Antes de entrar na Cripta Estrelada, tenho apenas três avisos para compartilhar.",
  ui_story_5084_50840100_76_dialog_content = "Primeiro, o sangue é a única maneira que Faria reconhece aqueles que desejam entrar na cripta, e apenas aqueles que formaram um pacto de sangue com ela podem fazê-lo.",
  ui_story_5084_50840100_77_dialog_content = "A outra porta aberta por Faria acatará a vontade do vinculado.",
  ui_story_5084_50840100_78_dialog_content = "Esta é a Faria.",
  ui_story_5084_50840100_79_dialog_content = "Em segundo lugar, os objetos que você carrega consigo possuem uma presença orientadora. Como eles pertencem ao tempo, eles naturalmente seguirão o tempo para os lugares onde pertencem.",
  ui_story_5084_50840100_80_dialog_content = "Terceiro, o destino já foi determinado há muito tempo. Não há como questioná-lo, ressentir-se dele ou mudá-lo.",
  ui_story_5084_50840100_81_dialog_content = "Embora pareça que você ainda tem muitas perguntas, Bola de Neve.",
  ui_story_5084_50840100_82_option_content = "Um \"pacto de sangue\"?",
  ui_story_5084_50840100_83_dialog_content = "Isso significa que temos que sangrar?",
  ui_story_5084_50840100_84_dialog_content = "Ó todo-poderoso Senhor da Verdade, tome até a última gota do meu sangue contaminado se for o seu desejo...",
  ui_story_5084_50840100_85_option_content = "Um destino \"inquestionável\"?",
  ui_story_5084_50840100_86_dialog_content = "Parece uma daquelas histórias sobre ser enviado para um mundo diferente.",
  ui_story_5084_50840100_87_dialog_content = "Você parece muito mais animado de repente.",
  ui_story_5084_50840100_88_dialog_content = "Comece os preparativos, Faria.",
  ui_story_5084_50840100_89_dialog_content = "E-Espera! Meu sangue... O sangue de um celestita até funcionará para esse tipo de coisa?",
  ui_story_5084_50840100_90_dialog_content = "Cutucada—!",
  ui_story_5084_50840100_91_dialog_content = "<size=45>Ai!!!</size>",
  ui_story_5084_50840100_92_dialog_content = "Você não ouviu? Sikare disse para Faria se preparar, então vamos nos mover!",
  ui_story_5084_50840100_93_dialog_content = "Você tem que levar o Beybe e eu com você, Senhora Victoria! Prometo que nos comportaremos da melhor maneira!",
  ui_story_5084_50840100_94_dialog_content = "Lenore está ciente de você estar aqui, May?",
  ui_story_5084_50840100_95_dialog_content = "Ela está, e ela me disse para me divertir muito também!",
  ui_story_5084_50840100_96_dialog_content = "Beybe guardou muita linha, o que significa que eu posso costurar tantas feridas quanto você precisar!",
  ui_story_5084_50840100_97_dialog_content = "Vou cuidar bem de você PlayerName, então não se afaste muito de mim!",
  ui_story_5084_50840100_98_dialog_content = "Miau!",
  ui_story_5084_50840100_99_dialog_content = "Acho que é melhor eu manter minha distância por enquanto...",
  ui_story_5084_50840100_100_dialog_content = "Se todos estão prontos agora, Faria pode começar.",
  ui_story_5084_50840100_101_dialog_content = "Senhor da Verdade, guie-me à resposta que procuro.",
  ui_story_5084_50840100_102_dialog_content = "Senhor da Verdade, abençoe nossa jornada com segurança e rapidez.",
  ui_story_5084_50840100_103_dialog_content = "Senhor da Verdade, castigue-me pelos meus pecados.",
  ui_story_5084_50840100_104_dialog_content = "Senhor da Verdade, leve-me a um lugar divertido!",
  ui_story_5084_50840100_105_dialog_content = "Você pode puxar minhas roupas o quanto quiser... Eu ainda não vou...",
  ui_story_5084_50840100_106_dialog_content = "Aff...!",
  ui_story_5084_50840100_107_dialog_content = "S... Sikare...",
  ui_story_5084_50840100_108_dialog_content = "Me salve...",
  ui_story_5084_50840100_109_dialog_content = "Você parece estar em tanta dor com os olhos fechados assim, Bola de Neve.",
  ui_story_5084_50840100_110_dialog_content = "Abra-os e dê uma olhada ao redor. Não há perigo aqui.",
  ui_story_5084_50840100_111_dialog_content = "M-Mas aquelas videiras grossas agora... Elas eram tão coçantes e assustadoras...",
  ui_story_5084_50840100_112_dialog_content = "Você não quer saber mais sobre a Verdade? Ah, espere, acabei de lembrar que você ainda não se juntou à True Order.",
  ui_story_5084_50840100_113_dialog_content = "... Você realmente não presta atenção em muitas coisas, não é, Sikare?",
  ui_story_5084_50840100_114_dialog_content = "De qualquer forma, não consigo acreditar que eles desapareceram assim!",
  ui_story_5084_50840100_115_dialog_content = "O verdadeiro problema é que você também não desapareceu.",
  ui_story_5084_50840100_116_dialog_content = "Preciso ouvir você dizer algo como \"Desejo me aproximar da Verdade\", ou \"Desejo entregar meus pensamentos e deixar meus sentidos explorarem o mundo ao meu redor.\"",
  ui_story_5084_50840100_117_dialog_content = "Você é um celestita, então deve ser bastante bom em algo assim.",
  ui_story_5084_50840100_118_dialog_content = "Você pode me dizer quem você é, ou por que está aqui, ou para onde quer ir...",
  ui_story_5084_50840100_119_dialog_content = "Tão obscuro... Eu só vim porque Faust me convidou para uma celebração \"única na vida\".",
  ui_story_5084_50840100_120_dialog_content = "Então, apenas pense em uma celebração. Se ainda estiver com medo, apenas sinta seu caminho entre as videiras e procure um castiçal.",
  ui_story_5084_50840100_121_dialog_content = "Um castiçal...",
  ui_story_5084_50840100_122_dialog_content = "O-Ah, olha, eu realmente encontrei um...",
  ui_story_5084_50840100_123_dialog_content = "Servirá como seu guia, mas não se deixe levar; lembre-se de voltar antes que a vela se apague.",
  ui_story_5084_50840100_124_dialog_content = "Mas... Como eu faço isso? E para onde devo voltar?",
  ui_story_5084_50840100_125_dialog_content = "... Sikare?",
  ui_story_5084_50840100_126_dialog_content = "Sikare!",
  ui_story_5084_50840201_1_dialog_content = "(Graças a Deus eu consegui este castiçal de Sikare, senão estaria muito escuro aqui...)",
  ui_story_5084_50840201_2_dialog_content = "(Mesmo que eu ainda não tenha ideia de onde encontrar os outros...)",
  ui_story_5084_50840201_3_dialog_content = "Espere, isso é...?",
  ui_story_5084_50840201_4_dialog_content = "<color=#e8d9bb>Enquanto os sinos antigos tocam, inúmeras torres de relógio surgem repentinamente e se estendem em direção à lua vermelha-sangue no céu noturno.</color>",
  ui_story_5084_50840201_5_dialog_content = "<color=#e8d9bb>Sua luz carmesim brilha sobre os caminhos dos fiéis e as paredes e portas intrincadamente esculpidas da cidade.</color>",
  ui_story_5084_50840201_6_dialog_content = "<color=#e8d9bb>Ele ouve as confissões dentro do Templo da Verdade, e fala da glória e dos segredos da família de sangue...</color>",
  ui_story_5084_50840201_7_dialog_content = "<color=#e8d9bb>Pulo, pulo—!</color>",
  ui_story_5084_50840201_8_dialog_content = "O chão aqui é real... E essas paredes também!",
  ui_story_5084_50840201_9_dialog_content = "Não é como a Mansão da Verdade, é? Um lugar onde ninguém está ciente do que está acontecendo a menos que estejam realmente aqui...",
  ui_story_5084_50840201_10_dialog_content = "Ah sim, a lua de sangue apareceu. Agora, o Advento da Verdade, que só acontece uma vez a cada três anos, finalmente pode começar.",
  ui_story_5084_50840201_11_dialog_content = "Minhas orações estão prontas, e as recitarei ao Senhor da Verdade com todo o meu coração durante a procissão.",
  ui_story_5084_50840201_12_dialog_content = "Suas orações não serão ouvidas a menos que você seja escolhido como um \"Iniciado\". Somente sacrificando-se o Senhor da Verdade responderá às suas súplicas.",
  ui_story_5084_50840201_13_dialog_content = "Cidade Varaki... É aqui que a Verdadeira Ordem está realizando sua \"celebração\"? O Advento da Verdade... desfile...",
  ui_story_5084_50840201_14_dialog_content = "Como eu vim parar aqui? E para onde foram todos os outros...?",
  ui_story_5084_50840201_15_dialog_content = "Primeiro, você precisa ler, aprender e interagir com os outros. Os irmãos e irmãs da Verdadeira Ordem podem ensinar-lhe muitas coisas que você nunca aprenderia sozinho.",
  ui_story_5084_50840201_16_dialog_content = "Em segundo lugar, você precisa comer, congregar e louvar o Senhor da Verdade.",
  ui_story_5084_50840201_17_dialog_content = "Ao comer na companhia dos fiéis todos os dias, a Verdade eventualmente se revelará a você.",
  ui_story_5084_50840201_18_dialog_content = "Em terceiro lugar, você tem que cavar e explorar. Se você tiver algum talento, encontrará tesouros para todos admirarem e se divertirem.",
  ui_story_5084_50840201_19_dialog_content = "Se você ama explorar como eu costumava fazer, então não há melhor família para você do que a True Order.",
  ui_story_5084_50840201_20_dialog_content = "Até o Sr. Beau parou de soltar tanto pelo depois que nos juntamos!",
  ui_story_5084_50840201_21_dialog_content = "Também consegui ganhar o respeito da Senhora Victoria bastante rapidamente, razão pela qual ela frequentemente confia em mim para lidar com seu trabalho importante sozinho.",
  ui_story_5084_50840201_22_dialog_content = "Bem? Isso não te faz querer se juntar à Verdadeira Ordem?",
  ui_story_5084_50840201_23_dialog_content = "Miau!",
  ui_story_5084_50840201_24_dialog_content = "Ela parece bastante confiante em si mesma...",
  ui_story_5084_50840201_25_dialog_content = "Antes de nos pregar, talvez você devesse se vestir de maneira mais agradável.",
  ui_story_5084_50840201_26_dialog_content = "A Senhora Victoria é uma nobre da Família Varaki. Como ela poderia confiar em uma garotinha como você para cuidar de seus assuntos...?",
  ui_story_5084_50840201_27_dialog_content = "Além disso, estou certo em presumir que esta é a sua primeira vez na Cidade Varaki?",
  ui_story_5084_50840201_28_dialog_content = "Se for assim, permita-me esclarecer sobre as origens e ensinamentos da True Order, bem como os segredos escondidos dentro da cripta...",
  ui_story_5084_50840201_29_dialog_content = "E-Espere, vocês são os veteranos da Verdadeira Ordem...? Mas vocês são tão diferentes das pessoas que eu conheço...",
  ui_story_5084_50840201_30_dialog_content = "May...!",
  ui_story_5084_50840201_31_dialog_content = "PlayerName? Por que você me arrastou?! Esses dois estavam prestes a se juntar a nós!",
  ui_story_5084_50840201_32_dialog_content = "Deixando de lado o fato de que eles claramente não tinham intenção de \"se juntar\" a você...",
  ui_story_5084_50840201_33_dialog_content = "Você não tem ouvido as pessoas na rua? Eles têm falado sobre o Advento da Verdade e algum tipo de procissão... Não tenho certeza de como, mas acabamos na cidade de Varaki! A cidade natal da Senhora Victoria!",
  ui_story_5084_50840201_34_dialog_content = "A cidade natal da Senhora Victoria... Sim, acho que já ouvi falar sobre isso antes. Então qual é o problema?",
  ui_story_5084_50840201_35_dialog_content = "Quer dizer que você não está surpreso com nada disso? Não está curioso sobre para onde o resto do nosso grupo foi?",
  ui_story_5084_50840201_36_dialog_content = "Hahaha, agora entendi! Todo mundo está se vestindo para a celebração agora mesmo!",
  ui_story_5084_50840201_37_dialog_content = "Vamos perguntar onde eles compraram suas roupas e comprar algumas para nós mesmos!",
  ui_story_5084_50840201_38_dialog_content = "Hã? Por que você está tão animado? Este lugar parece mais uma alfaiataria assombrada do que qualquer tipo de loja...",
  ui_story_5084_50840201_39_dialog_content = "Ah... May?",
  ui_story_5084_50840201_40_dialog_content = "Ouça! A procissão está vindo para cá! Segure minha mão e não solte!",
  ui_story_5084_50840201_41_dialog_content = "Ouço dizer que a pessoa dentro daquele caixão é um ancestral Varaki, e que eles foram escolhidos pelo Senhor da Verdade!",
  ui_story_5084_50840201_42_dialog_content = "<color=#e8d9bb>Com a lua de sangue como testemunha, um grupo de pessoas em trajes elegantes marcha lentamente pela rua, carregando nos ombros o caixão ornamentado e de aparência antiga.</color>",
  ui_story_5084_50840201_43_dialog_content = "<color=#e8d9bb>Dentro do caixão jaz o chamado \"ancestral\" dos Varaki, segurando um texto sagrado e exalando A Verdade junto com a luz da lua de sangue.</color>",
  ui_story_5084_50840201_44_dialog_content = "<color=#e8d9bb>Os discípulos da Verdade seguem em reverência, sem ousar tirar os olhos do caixão.</color>",
  ui_story_5084_50840201_45_dialog_content = "<color=#e8d9bb>Lentamente e solenemente, eles passam por todas as ruas da cidade antes de chegar aos portões do Templo da Verdade.</color>",
  ui_story_5084_50840201_46_dialog_content = "<color=#e8d9bb>Crec... Thud—</color>",
  ui_story_5084_50840201_47_dialog_content = "A procissão terminou e A Verdade chegou.",
  ui_story_5084_50840201_48_dialog_content = "Os fiéis se aproximaram do nosso senhor e fizeram suas oferendas a ele.",
  ui_story_5084_50840201_49_dialog_content = "Louve o Senhor da Verdade!",
  ui_story_5084_50840201_50_dialog_content = "Dedico minha vida ao Senhor da Verdade!",
  ui_story_5084_50840201_51_dialog_content = "Agora...",
  ui_story_5084_50840201_52_dialog_content = "Um de vocês será escolhido pelo divino e permitido entrar neste caixão de revelações infinitas, para ouvir e receber A Verdade.",
  ui_story_5084_50840201_53_dialog_content = "Com sua profunda percepção, você verá até mesmo os segredos mais escuros da história. ",
  ui_story_5084_50840201_54_dialog_content = "Dessa forma, você transcenderá sua individualidade e se tornará a personificação da Verdadeira Ordem e sua sabedoria coletiva. ",
  ui_story_5084_50840201_55_dialog_content = "Tudo o que você experimenta deve guiar nossa sagrada ordem para um futuro cada vez maior. ",
  ui_story_5084_50840201_56_dialog_content = "Uma vez imerso no fluxo ilimitado do nada, as fronteiras do tempo e espaço se dissolverão ao seu redor.",
  ui_story_5084_50840201_57_dialog_content = "Apenas quando o Senhor da Verdade aparecer e purificar você do seu ego é que você alcançará sua forma mais pura.",
  ui_story_5084_50840201_58_dialog_content = "Ouça a Verdade, desperte sua mente e ascenda a um plano superior.",
  ui_story_5084_50840201_59_dialog_content = "Quando chegar a hora, você alcançará a unidade com o divino.",
  ui_story_5084_50840201_60_dialog_content = "Escolha-me, Senhor Wilhelm!",
  ui_story_5084_50840201_61_dialog_content = "Desejo ouvir A Verdade...!",
  ui_story_5084_50840201_62_dialog_content = "Eu também quero ouvir a Verdade!",
  ui_story_5084_50840201_63_dialog_content = "Shhh! Acalme-se, May!",
  ui_story_5084_50840201_64_dialog_content = "Foi difícil o suficiente para nós nos misturarmos com a multidão...",
  ui_story_5084_50840201_65_dialog_content = "Mas se eu quiser ser um membro importante da True Order, tenho que aprender mais sobre a Verdade! Esta é uma oportunidade perfeita para isso, agora vá, Beybe!",
  ui_story_5084_50840201_66_dialog_content = "\"O destino já foi determinado há muito tempo. Não há como questioná-lo, ressentir-se dele ou mudá-lo.\"",
  ui_story_5084_50840201_67_dialog_content = "Miau...?",
  ui_story_5084_50840201_68_dialog_content = "Você já esqueceu o aviso que Sikare nos deu, May?",
  ui_story_5084_50840201_69_dialog_content = "L... Senhora Victoria?!",
  ui_story_5084_50840201_70_dialog_content = "Huh? Que roupa é essa?",
  ui_story_5084_50840201_71_dialog_content = "Eu poderia perguntar o mesmo. Você conseguiu eles para entrar neste lugar?",
  ui_story_5084_50840201_72_dialog_content = "Foi ideia de May. Depois disso, apenas seguimos a multidão todo o caminho até aqui.",
  ui_story_5084_50840201_73_dialog_content = "Então você sabe onde estamos agora?",
  ui_story_5084_50840201_74_dialog_content = "Acho que sim. De acordo com esses adoradores, estamos na Cidade Varaki... Seu lar. Realmente parece que fomos para outro mundo, sabe...",
  ui_story_5084_50840201_75_dialog_content = "Isso está tudo no passado.",
  ui_story_5084_50840201_76_dialog_content = "O passado?",
  ui_story_5084_50840201_77_dialog_content = "Naquela época, eu ainda não havia me juntado à True Order. Eu estava viajando pelo mundo em busca da Verdade para mim mesmo.",
  ui_story_5084_50840201_78_dialog_content = "Estamos no ano de 1915. Após este Advento da Verdade, o líder da True Order desaparece.",
  ui_story_5084_50840201_79_dialog_content = "... Para onde ele vai?",
  ui_story_5084_50840201_80_dialog_content = "O Senhor da Verdade me guiou até aqui através desse anel. É exatamente como Sikare disse: como um objeto pertencente ao tempo, ele me guiou ao seu lugar de direito na história.",
  ui_story_5084_50840201_81_dialog_content = "A Bíblia Sangrenta está em posse do meu antepassado, mas o anel ainda está nas mãos do líder da True Order.",
  ui_story_5084_50840201_82_dialog_content = "Não importa quantos anos passem, a maldição da linhagem Varaki nunca pode ser desfeita.",
  ui_story_5084_50840201_83_dialog_content = "No fluxo infinito do tempo, a verdadeira iluminação é necessária para responder às perguntas que você abriga.",
  ui_story_5084_50840201_84_dialog_content = "A Verdade deve permear seu ser para obter uma maior compreensão do mundo.",
  ui_story_5084_50840201_85_dialog_content = "Eu, Wilhelm Varaki, líder da Verdadeira Ordem, sob a orientação do Senhor da Verdade, anuncio aqui o Iniciado deste Advento da Verdade—",
  ui_story_5084_50840201_86_dialog_content = "Victoria Varaki.",
  ui_story_5084_50840201_87_dialog_content = "O quê...?",
  ui_story_5084_50840201_88_dialog_content = "Victoria Varaki? Por que ela está aqui...?",
  ui_story_5084_50840201_89_dialog_content = "Hehehe. Interessante.",
  ui_story_5084_50840201_90_dialog_content = "...",
  ui_story_5084_50840201_91_dialog_content = "Senhora Victoria? É ela! Ela realmente está aqui!",
  ui_story_5084_50840201_92_dialog_content = "Mas ela é a única filha dos Varaki...",
  ui_story_5084_50840201_93_dialog_content = "Sim, mas ouvi dizer que o chefe da família não a reconhece como parte deles...",
  ui_story_5084_50840201_94_dialog_content = "...",
  ui_story_5084_50840301_1_dialog_content = "<size=30>... É a Senhora Victoria!</size>",
  ui_story_5084_50840301_2_dialog_content = "Por que você parece tão feliz?! Ela foi vista pelas pessoas do passado!",
  ui_story_5084_50840301_3_dialog_content = "Isso não vai contra as regras de estarmos aqui?!",
  ui_story_5084_50840301_4_dialog_content = "Siga a orientação do seu coração, e as revelações da Verdade não o levarão ao erro.",
  ui_story_5084_50840301_5_dialog_content = "Até a próxima lua de sangue, fiéis discípulos. O Senhor da Verdade vigia todos nós, aguardando pacientemente que nos aproximemos dele.",
  ui_story_5084_50840301_6_dialog_content = "Que a Verdade abençoe você.",
  ui_story_5084_50840301_7_dialog_content = "Que a Verdade abençoe você.",
  ui_story_5084_50840301_8_dialog_content = "Devemos ir com eles?",
  ui_story_5084_50840301_9_dialog_content = "Se me permite, meu coração me diz para ficar de lado e observar em silêncio.",
  ui_story_5084_50840301_10_dialog_content = "Dê sua opinião, Victoria.",
  ui_story_5084_50840301_11_dialog_content = "Não sou membro da True Order. A honra de ouvir A Verdade é desperdiçada em mim.",
  ui_story_5084_50840301_12_dialog_content = "E ainda assim, não ouvi objeções quando te escolhi no Templo da Verdade.",
  ui_story_5084_50840301_13_dialog_content = "Buscando a Verdade e formando alianças; isso não seria simplesmente sua maneira de se preparar para se juntar à True Order no futuro?",
  ui_story_5084_50840301_14_dialog_content = "Meus negócios não são da sua conta.",
  ui_story_5084_50840301_15_dialog_content = "Você ainda não me respondeu. Diga-me, o que exatamente é a Verdade?",
  ui_story_5084_50840301_16_dialog_content = "...",
  ui_story_5084_50840301_17_dialog_content = "<color=#e8d9bb>Crrrrachadura-!</color>",
  ui_story_5084_50840301_18_dialog_content = "A honra de ouvir a Verdade... Eu realmente desejo ouvir os pensamentos de alguém tão precoce quanto você, Victoria Varaki. O que, na sua definição, é a Verdade?",
  ui_story_5084_50840301_19_dialog_content = "A Verdade... é conhecimento.",
  ui_story_5084_50840301_20_dialog_content = "Humph, Victoria Varaki... Embora compartilhemos a mesma linhagem, em termos de força, sabedoria, capacidade e até beleza... Eu estou muito acima de você.",
  ui_story_5084_50840301_21_dialog_content = "Então, o que faz você pensar que este anel é legitimamente seu?",
  ui_story_5084_50840301_22_dialog_content = "Eu sou um verdadeiro Varaki, e o líder da True Order!",
  ui_story_5084_50840301_23_dialog_content = "Quanto a você... Você deve primeiro demonstrar que é digno do nosso nome de família. Não me decepcione.",
  ui_story_5084_50840301_24_dialog_content = "...",
  ui_story_5084_50840301_25_dialog_content = "<color=#e8d9bb>Crrrrack—!</color>",
  ui_story_5084_50840301_26_dialog_content = "Escolha palavras e frases de livros que você não consegue compreender e busque iluminação nas imagens que elas evocam em sua mente...",
  ui_story_5084_50840301_27_dialog_content = "Não é esse o seu jeito de procurar respostas?",
  ui_story_5084_50840301_28_dialog_content = "O que você viu agora há pouco? O que veio à mente?",
  ui_story_5084_50840301_29_dialog_content = "Dúvida? Medo? Negação? O poder dos Varaki não pode ser escolhido, pois o próprio poder escolhe aqueles que são dignos dele.",
  ui_story_5084_50840301_30_dialog_content = "...",
  ui_story_5084_50840301_31_dialog_content = "(Ele está usando o anel da família de Victoria...)",
  ui_story_5084_50840301_32_dialog_content = "Wilhelm... Achei que você disse que Victoria tinha partido da cidade Varaki?",
  ui_story_5084_50840301_33_dialog_content = "Heheh, que ela tinha.",
  ui_story_5084_50840301_34_dialog_content = "Como você pode ser tão duro com uma mocinha tão brilhante e promissora, Varaki?",
  ui_story_5084_50840301_35_dialog_content = "Já faz bastante tempo, Senhora Victoria.",
  ui_story_5084_50840301_36_dialog_content = "Tem.",
  ui_story_5084_50840301_37_dialog_content = "O Senhor da Verdade me guiou para escolhê-la, Porfírio. Os Varaki e eu somos impotentes para mudar a sua vontade.",
  ui_story_5084_50840301_38_dialog_content = "Heheheh, não te culpo por isso, Wilhelm. Eu simplesmente lamento a acentuada desigualdade entre os ramos da nossa família de sangue.",
  ui_story_5084_50840301_39_dialog_content = "O Senhor da Verdade ainda aparecerá diante de nós? Seu escolhido está faltando em fé ou dignidade?",
  ui_story_5084_50840301_40_dialog_content = "Essa decisão cabe aos chefes das doze famílias de ramo, não apenas ao líder Varaki.",
  ui_story_5084_50840301_41_dialog_content = "Hahaha, mais uma refutação elegante e mordaz, Porfírio.",
  ui_story_5084_50840301_42_dialog_content = "Em qualquer caso, a vontade da Verdade não deve ser ignorada. Vamos ver... Que conhecimento o Senhor da Verdade transmitirá a ela...",
  ui_story_5084_50840301_43_dialog_content = "Chefes de famílias!",
  ui_story_5084_50840301_44_dialog_content = "Há alguma objeção ao Iniciado escolhido para este Advento da Verdade?",
  ui_story_5084_50840301_45_dialog_content = "...",
  ui_story_5084_50840301_46_dialog_content = "Sem objeções...",
  ui_story_5084_50840301_47_dialog_content = "Uma objeção mudaria algo neste ponto?",
  ui_story_5084_50840301_48_dialog_content = "Hunf.",
  ui_story_5084_50840301_49_dialog_content = "Continue. O Senhor da Verdade não pode esperar mais.",
  ui_story_5084_50840301_50_dialog_content = "Não tenha medo, Victoria Varaki.",
  ui_story_5084_50840301_51_dialog_content = "Eu pessoalmente vou te escoltar até o templo e te colocar naquele caixão sagrado.",
  ui_story_5084_50840301_52_dialog_content = "Estabilize-se em coração e mente, e prepare-se para compartilhar seu conhecimento da Verdade com nosso senhor.",
  ui_story_5084_50840301_53_dialog_content = "...",
  ui_story_5084_50840301_54_dialog_content = "(Ouvi alguém na rua dizendo que o Iniciado tinha que se \"sacrificar\"... O que exatamente é essa cerimônia...?)",
  ui_story_5084_50840301_55_dialog_content = "(Sinto um perigo sério vindo desses chefes de família...)",
  ui_story_5084_50840301_56_dialog_content = "(O que acontecerá se Victoria realmente for sacrificado?!)",
  ui_story_5084_50840301_57_dialog_content = "(De jeito nenhum, eu tenho que fazer algo antes que Victoria entre naquele caixão...)",
  ui_story_5084_50840301_58_option_content = "Ligação Telepática",
  ui_story_5084_50840301_59_dialog_content = "Você finalmente alcançou.",
  ui_story_5084_50840301_60_dialog_content = "Algo não parece certo aqui, Victoria... Você realmente vai deixar esse cara te colocar no caixão e te sacrificar?!",
  ui_story_5084_50840301_61_dialog_content = "Sim.",
  ui_story_5084_50840301_62_dialog_content = "E-Então... O que May e eu devemos fazer?!",
  ui_story_5084_50840301_63_dialog_content = "Você se lembra das palavras de Sikare?",
  ui_story_5084_50840301_64_dialog_content = "Claro que sim! \"O destino já foi determinado há muito tempo. Não há como questioná-lo, ressentir-se dele ou mudá-lo.\"",
  ui_story_5084_50840301_65_dialog_content = "Sem questionar...",
  ui_story_5084_50840301_66_dialog_content = "Parece que você entende agora.",
  ui_story_5084_50840301_67_dialog_content = "Parece que você foi separado de todos os outros, Celestita.",
  ui_story_5084_50840301_68_dialog_content = "E apesar do aviso de Sikare, sua mente está cheia de perguntas e dúvidas.",
  ui_story_5084_50840301_69_dialog_content = "Acho que é bastante normal questionar a situação atual...",
  ui_story_5084_50840301_70_dialog_content = "Apenas siga sua intuição e testemunhe o passado se desdobrar comigo.",
  ui_story_5084_50840301_71_dialog_content = "Victoria!",
  ui_story_5084_50840301_72_dialog_content = "Agora...",
  ui_story_5084_50840301_73_dialog_content = "<color=#e8d9bb>Vushhh—Vushhh—!!</color>",
  ui_story_5084_50840301_74_dialog_content = "Entre no caixão!",
  ui_story_5084_50840301_75_dialog_content = "...",
  ui_story_5084_50840301_76_dialog_content = "Vento...? A Senhora Victoria realmente vai se deitar aí?",
  ui_story_5084_50840301_77_option_content = "Ligação Telepática",
  ui_story_5084_50840301_78_dialog_content = "(Parece que algo está me bloqueando...)",
  ui_story_5084_50840301_79_dialog_content = "Haha...",
  ui_story_5084_50840301_80_dialog_content = "Haha... Hahahaha...",
  ui_story_5084_50840301_81_dialog_content = "Hahahaha... Hahahahaha...",
  ui_story_5084_50840301_82_dialog_content = "(Essas são algumas risadas assustadoras... O que diabos eles estão tramando?)",
  ui_story_5084_50840301_83_dialog_content = "Hahahahahahaha...",
  ui_story_5084_50840301_84_dialog_content = "(Mesmo aquele Wilhelm está se juntando...)",
  ui_story_5084_50840301_85_dialog_content = "<color=#e8d9bb>Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_86_dialog_content = "PlayerName?",
  ui_story_5084_50840301_87_dialog_content = "Não se preocupe, May! Estou bem aqui!",
  ui_story_5084_50840301_88_dialog_content = "Mas que...?!",
  ui_story_5084_50840301_89_dialog_content = "Parece que aquele vento negro de agora há pouco apagou minha vela... Não consigo ver nada aqui dentro!",
  ui_story_5084_50840301_90_dialog_content = "A maneira como aquelas pessoas estavam rindo era tão perturbadora... Será que todos estavam em conluio uns com os outros?",
  ui_story_5084_50840301_91_dialog_content = "Sem mencionar todas as coisas que aquele cara Wilhelm disse sobre Victoria...",
  ui_story_5084_50840301_92_dialog_content = "Ela não está em perigo, está? Não... Eu preciso saber do que eles estavam rindo!",
  ui_story_5084_50840301_93_option_content = "Aumento de Força—",
  ui_story_5084_50840301_94_dialog_content = "(Eu... Eu mal consigo entender qualquer coisa... O que está acontecendo aqui...?)",
  ui_story_5084_50840301_95_dialog_content = "A liderança da Verdadeira Ordem cobrou seu preço após todos esses anos, Wilhelm Varaki?",
  ui_story_5084_50840301_96_dialog_content = "Você sabe exatamente o que significa para uma pessoa entrar naquele caixão. Certamente você tem um motivo oculto para escolher a filha de <color=#FFB400>Osten Varaki</color>?",
  ui_story_5084_50840301_97_dialog_content = "Ele era o líder anterior da True Order e meu irmão mais velho. Naturalmente, cuidar de sua preciosa filha é minha responsabilidade.",
  ui_story_5084_50840301_98_dialog_content = "(Espera, então Wilhelm... É o tio de Victoria?)",
  ui_story_5084_50840301_99_dialog_content = "Estou cansado de suas palavras vangloriosas, Varaki.",
  ui_story_5084_50840301_100_dialog_content = "Estou bem ciente de que você ainda não encontrou uma solução.",
  ui_story_5084_50840301_101_dialog_content = "Se você realmente tem o melhor interesse dela em mente, por que não se juntar a ela lá...?",
  ui_story_5084_50840301_102_dialog_content = "Espere aí—",
  ui_story_5084_50840301_103_dialog_content = "O que você pensa que está fazendo, Wilhelm? Isso não é nada como você disse que seria.",
  ui_story_5084_50840301_104_dialog_content = "De fato não é, Clavis. No entanto, você já tomou sua decisão.",
  ui_story_5084_50840301_105_dialog_content = "...",
  ui_story_5084_50840301_106_dialog_content = "<color=#e8d9bb>Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_107_dialog_content = "(Oh não... Parece que este vento negro foi destinado a esconder tudo desde o início...)",
  ui_story_5084_50840301_108_dialog_content = "(Clavis, Wilhelm e Victoria... O que eles estão planejando?)",
  ui_story_5084_50840301_109_dialog_content = "Urgh, pare de me agarrar tão forte, PlayerName! Você vai quebrar meu braço ao meio...",
  ui_story_5084_50840301_110_dialog_content = "O-Ah, desculpe...",
  ui_story_5084_50840301_111_dialog_content = "Lá, isso é bem melhor!",
  ui_story_5084_50840301_112_dialog_content = "Tenho que pensar em algo... Mas o que eu realmente posso fazer...?",
  ui_story_5084_50840301_113_dialog_content = "E o que está acontecendo entre Victoria e seu tio? Por que ele sacrificaria sua própria sobrinha...?",
  ui_story_5084_50840301_114_dialog_content = "Você está tentando criar um plano, PlayerName? A chama da vela está tremulando... Olha, a cena está começando a mudar.",
  ui_story_5084_50840401_1_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat...</color>",
  ui_story_5084_50840401_2_dialog_content = "Aquele som...!",
  ui_story_5084_50840401_3_dialog_content = "Miau?",
  ui_story_5084_50840401_4_dialog_content = "Não tenha medo, Sr. Beau! Eu estou bem aqui!",
  ui_story_5084_50840401_5_dialog_content = "Graças a Deus vocês dois ainda estão aí. Por um segundo pensei que estava sozinho novamente.",
  ui_story_5084_50840401_6_dialog_content = "Parece que acabamos em um novo lugar. Algo cheira bem, também. Será o cheiro de roupas limpas...?",
  ui_story_5084_50840401_7_dialog_content = "Hã?",
  ui_story_5084_50840401_8_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5084_50840401_9_dialog_content = "S-Alguém está aqui!",
  ui_story_5084_50840401_10_dialog_content = "Mmph... Ei, não cubra minha... Mmph!",
  ui_story_5084_50840401_11_dialog_content = "... Hmph. Eu usei essas roupas ontem, o que as torna história antiga agora.",
  ui_story_5084_50840401_12_dialog_content = "E este tecido parece lixa na minha pele! Eu sou um artista, não um simples carpinteiro...",
  ui_story_5084_50840401_13_dialog_content = "Quanto a este... A cor é tão lamentavelmente sem imaginação... Um verdadeiro artista nunca poderia se resignar a usar cores tão sem brilho.",
  ui_story_5084_50840401_14_dialog_content = "Bah! Esses foram feitos em uma loja de roupas infantis?! Eu sou mais do que velho o suficiente para usar roupas de adulto!",
  ui_story_5084_50840401_15_dialog_content = "Maldição—! Eu nunca deveria ter levado as palavras do Pai a sério!",
  ui_story_5084_50840401_16_dialog_content = "Essa dupla obtusa nunca poderia criar um traje formal para o grande Charon!",
  ui_story_5084_50840401_17_dialog_content = "<color=#828282>Bater!</color>",
  ui_story_5084_50840401_18_dialog_content = "...?",
  ui_story_5084_50840401_19_dialog_content = "Ch-Charon?!?",
  ui_story_5084_50840401_20_dialog_content = "Espere... ele não pode nos ver?",
  ui_story_5084_50840401_21_dialog_content = "Huff, huff... F-Finalmente, você me soltou! Você conhece essa criança, PlayerName?",
  ui_story_5084_50840401_22_dialog_content = "Sim... Esse cabelo e essas expressões... Não há como confundir \"o grande Charon\" com mais ninguém!",
  ui_story_5084_50840401_23_dialog_content = "Ele estava bem na nossa frente agora mesmo, não estava?",
  ui_story_5084_50840401_24_dialog_content = "Sim, e parece que ele estava escolhendo uma roupa. Hum... Essas roupas cheirosas realmente são algo mais! Eu nunca poderia montar algo tão bom quanto isso...",
  ui_story_5084_50840401_25_dialog_content = "Então estamos no armário de Charon... Mas pela aparência das coisas, ele mal tem mais de dez anos...",
  ui_story_5084_50840401_26_dialog_content = "De novo... Nunca consegui adivinhar a idade daquele cara. Acho que não importa realmente, já que estamos no passado agora.",
  ui_story_5084_50840401_27_dialog_content = "Espere... De volta ao Advento da Verdade, Victoria disse que estamos no ano de 1915, o que significa...",
  ui_story_5084_50840401_28_dialog_content = "E o que há com essa vela de qualquer maneira? Ela me leva para um lugar diferente sempre que começa a cintilar, e desta vez te trouxe junto também, May!",
  ui_story_5084_50840401_29_dialog_content = "Você é tão bobo, PlayerName! Obviamente, isso só aconteceu porque você está segurando aquela vela em uma mão e o Beybe na outra!",
  ui_story_5084_50840401_30_dialog_content = "Sikare tem à sua disposição todo tipo de objetos mágicos e poderosos. Mas se você não acredita em magia, então não há muito mais a dizer.",
  ui_story_5084_50840401_31_dialog_content = "...? Você não está preocupado ou mesmo curioso sobre tudo o que acabamos de ver?",
  ui_story_5084_50840401_32_dialog_content = "Você quer dizer o tipo de curiosidade feliz, ou o tipo assustado?",
  ui_story_5084_50840401_33_dialog_content = "Ah, que importa? Eu gosto dos dois! Hahaha!",
  ui_story_5084_50840401_34_dialog_content = "Então, essa vela é a razão pela qual Charon não conseguiu nos ver ou ouvir...?",
  ui_story_5084_50840401_35_dialog_content = "A mesma coisa aconteceu de volta no Templo da Verdade... Apenas o Victoria do presente conseguiu nos ver.",
  ui_story_5084_50840401_36_dialog_content = "É como um item daquelas histórias! O tipo que pode conceder invisibilidade!",
  ui_story_5084_50840401_37_dialog_content = "Hahaha, sem brincadeira!",
  ui_story_5084_50840401_38_dialog_content = "Não sabemos o que aconteceu com Victoria depois que ela entrou naquele caixão, ou onde Nails e Faust estão agora...",
  ui_story_5084_50840401_39_dialog_content = "Realmente viemos aqui seguindo a orientação de nossos corações...?",
  ui_story_5084_50840401_40_dialog_content = "No que você estava pensando mais cedo?",
  ui_story_5084_50840401_41_dialog_content = "Você quer dizer quando a luz da vela começou a piscar? Foi algo como...",
  ui_story_5084_50840401_42_dialog_content = "\"Clavis, Wilhelm e Victoria... O que eles estão planejando?\"",
  ui_story_5084_50840401_43_dialog_content = "Se o pai de Charon e aquele \"duo obtuso\" são os três deles...",
  ui_story_5084_50840401_44_dialog_content = "Talvez isso seja o que Sikare quis dizer quando ela disse que a vela seria meu guia!",
  ui_story_5084_50840401_45_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5084_50840401_46_dialog_content = "Faço isso apenas para preservar a natureza imparcial da minha arte. Essas meias são meus maiores tesouros, mas eu vou relutantemente trocá-las por causa delas.",
  ui_story_5084_50840401_47_dialog_content = "(Charon é tão sério quando se trata de trocar de roupa...)",
  ui_story_5084_50840401_48_dialog_content = "\"Oh Senhor Charon, onde você encontra para comprar meias tão magnificamente hipnotizantes?\"",
  ui_story_5084_50840401_49_dialog_content = "\"Ninguém tem um gosto que possa igualar ao seu, Senhor Charon...\"",
  ui_story_5084_50840401_50_dialog_content = "Hmpf, então é isso que é ser famoso? Uma existência tão problemática...",
  ui_story_5084_50840401_51_dialog_content = "<color=#828282>Bater!</color>",
  ui_story_5084_50840401_52_dialog_content = "...",
  ui_story_5084_50840401_53_dialog_content = "Ele tem sido diferente de todos desde que era criança, hein...",
  ui_story_5084_50840401_54_dialog_content = "Vamos dar uma olhada ao redor, May. No entanto, não se afaste muito de mim!",
  ui_story_5084_50840401_55_dialog_content = "Eu sei, eu sei!",
  ui_story_5084_50840401_56_dialog_content = "Há quanto tempo, Clavis.",
  ui_story_5084_50840401_57_dialog_content = "Olá, Tio Clavis.",
  ui_story_5084_50840401_58_dialog_content = "É a Senhora Victoria! Ei—",
  ui_story_5084_50840401_59_dialog_content = "Acalme-se, May! Mesmo que ela não esteja respondendo, tenho certeza de que ela já nos notou a essa distância. Esta deve ser outra versão de seu passado, certo?",
  ui_story_5084_50840401_60_dialog_content = "Embora ela não pareça muito diferente do Victoria que conhecemos no presente...",
  ui_story_5084_50840401_61_dialog_content = "Isso porque ela é uma nobre membro da família de sangue! Uma vez que ela despertou seu poder, o processo de envelhecimento parou para ela.",
  ui_story_5084_50840401_62_dialog_content = "E por que você ainda está se escondendo se as pessoas do passado não podem nos ver, PlayerName?",
  ui_story_5084_50840401_63_dialog_content = "Hã?! Ah sim... Talvez seja porque tudo e todos por aqui parecem um pouco assustadores?",
  ui_story_5084_50840401_64_dialog_content = "Haha... Ver vocês dois aqui ao mesmo tempo é uma visão bastante rara.",
  ui_story_5084_50840401_65_dialog_content = "Hunf...",
  ui_story_5084_50840401_66_dialog_content = "Onde está o jovem Charon?!?",
  ui_story_5084_50840401_67_dialog_content = "Ah, você conhece aquele garoto. Assim que ele sabe que estamos esperando visitas, ele passa horas se arrumando...",
  ui_story_5084_50840401_68_dialog_content = "...",
  ui_story_5084_50840401_69_dialog_content = "Ei, Senhor Charon. Belas meias que você tem aí.",
  ui_story_5084_50840401_70_dialog_content = "D-Diga o que quiser, eu ainda não vou...",
  ui_story_5084_50840401_71_dialog_content = "Cuide das suas maneiras, Charon.",
  ui_story_5084_50840401_72_dialog_content = "... Olá, Tio Wilhelm.",
  ui_story_5084_50840401_73_dialog_content = "Não está esquecendo de alguém? Esta é Victoria, a sobrinha do seu Tio Wilhelm.",
  ui_story_5084_50840401_74_dialog_content = "Olá, primo.",
  ui_story_5084_50840401_75_dialog_content = "... Olá, primo.",
  ui_story_5084_50840401_76_dialog_content = "Charon, por que você não leva Victoria para o outro quarto e toma um chá e algumas sobremesas?",
  ui_story_5084_50840401_77_dialog_content = "... Sim, Pai.",
  ui_story_5084_50840401_78_dialog_content = "Estou surpreso que você tenha tempo para nos visitar aqui na Cidade Velha. Os assuntos em Varaki Town estão mais ou menos resolvidos?",
  ui_story_5084_50840401_79_dialog_content = "Vir até aqui não foi nada fácil, mas você sabe que eu viajaria qualquer distância para te ver, Clavis.",
  ui_story_5084_50840401_80_dialog_content = "...",
  ui_story_5084_50840401_81_dialog_content = "...",
  ui_story_5084_50840401_82_dialog_content = "Por quanto tempo você vai continuar me encarando?",
  ui_story_5084_50840401_83_dialog_content = "Você está em liga com o resto dessas pessoas miseráveis?",
  ui_story_5084_50840401_84_dialog_content = "Quais pessoas miseráveis, exatamente?",
  ui_story_5084_50840401_85_dialog_content = "Sabe, aqueles cultistas que são exatamente como Wilhelm Varaki.",
  ui_story_5084_50840401_86_dialog_content = "Se você está se referindo à True Order, então não, eu não sou um deles. Também é bastante impróprio se referir ao líder deles pelo nome completo, você não acha?",
  ui_story_5084_50840401_87_dialog_content = "Chame isso de intuição de artista, mas ninguém que se associa a ele está tramando algo bom. Foi apenas a pedido do meu pai que eu apareci diante de você hoje.",
  ui_story_5084_50840401_88_dialog_content = "Você diz que não suporta o associado do seu pai, e ainda assim se esforçou tanto para se apresentar bem.",
  ui_story_5084_50840401_89_dialog_content = "...! É-Está tudo por causa da arte!",
  ui_story_5084_50840401_90_dialog_content = "Oh? Então o que exatamente é arte?",
  ui_story_5084_50840401_91_dialog_content = "Você está ciente de que todos nós devemos morrer um dia, sim? No entanto, há uma coisa neste mundo que nunca pode morrer; você sabe o que é isso?",
  ui_story_5084_50840401_92_dialog_content = "É arte!",
  ui_story_5084_50840401_93_dialog_content = "A arte é uma flor proibida que pode florescer nas profundezas do inferno! Um trem imparável que surge das águas do rio Styx.",
  ui_story_5084_50840401_94_dialog_content = "E eu me tornarei seu condutor, um barqueiro de almas e uma obra de arte eterna.",
  ui_story_5084_50840401_95_dialog_content = "Uma obra de arte eterna, você diz... Heheh, parece que estou destinado a me tornar seu passageiro algum dia.",
  ui_story_5084_50840401_96_dialog_content = "Mas é claro! Não, espera... Desde que aqueles malditos tolos zombaram da minha arte...",
  ui_story_5084_50840401_97_dialog_content = "Uma criança dessa idade não deveria estar tão obcecada com mictórios...",
  ui_story_5084_50840401_98_dialog_content = "... Como um homem que está muito embriagado, sua frivolidade descuidada é quase divertida.",
  ui_story_5084_50840401_99_dialog_content = "Desde aquele dia, decidi que apenas aqueles que apreciam minha arte podem embarcar no meu trem...",
  ui_story_5084_50840401_100_dialog_content = "Recuso-me a aceitar qualquer pessoa que tenha vivido demais, se comporte de maneira muito rude ou não tenha gosto pela arte.",
  ui_story_5084_50840401_101_dialog_content = "Você é bastante confiante em si mesmo, Charon.",
  ui_story_5084_50840401_102_dialog_content = "Isso é natural, já que ninguém mais na Cidade Velha tem gostos que rivalizam com os meus.",
  ui_story_5084_50840401_103_dialog_content = "E algum dia, eu vou estabelecer minha própria trupe de teatro, bem como grupos para apreciar coisas como música, arte e trens modelo...",
  ui_story_5084_50840401_104_dialog_content = "Não me importo em te dizer, já que há muito tempo descobri a tal \"verdade\" que esses tolos estão sempre tagarelando. É arte, pura e simples.",
  ui_story_5084_50840401_105_dialog_content = "Bem? Já que você não encontrou uma organização para se juntar, você é corajoso o suficiente para enfrentar meu processo de admissão?",
  ui_story_5084_50840401_106_dialog_content = "Heheh, interessante. E o que exatamente é esse \"processo de admissão\" seu?",
  ui_story_5084_50840401_107_dialog_content = "É bem simples. Quando você ver meu trem passar, mobilize todos os seus sentidos e entre no meu mundo da arte! Depois, você terá que demonstrar seu entendimento sobre arte também.",
  ui_story_5084_50840401_108_dialog_content = "Muito bem, eu aceito.",
  ui_story_5084_50840401_109_dialog_content = "Então apenas espere aí. Pai não aprova que eu mostre essas coisas para outras pessoas.",
  ui_story_5084_50840401_110_dialog_content = "Agora deleite seus olhos com a performance de um maestro e testemunhe o verdadeiro significado da arte!",
  ui_story_5084_50840401_111_dialog_content = "<color=#e8d9bb>Momentos depois...</color>",
  ui_story_5084_50840401_112_dialog_content = "Ouça atentamente! Os trilhos do trem ecoam com os gritos do apocalipse!",
  ui_story_5084_50840401_113_dialog_content = "Testemunhe o último trem partindo de um mundo moribundo e indo para a eternidade! ",
  ui_story_5084_50840401_114_dialog_content = "Apenas artistas que aspiram à imortalidade podem embarcar e viajar além dos gloriosos céus! ",
  ui_story_5084_50840401_115_dialog_content = "Liberado das correntes que aprisionavam seu corpo, suas rodas desamarradas giram infinitamente enquanto ele persiste para sempre!",
  ui_story_5084_50840401_116_dialog_content = "O motor aponta para o céu e eu, o grande Charon, sou seu condutor! Juntos, escaparemos deste abismo amaldiçoado!",
  ui_story_5084_50840401_117_dialog_content = "Eu ordenarei ao próprio inferno que abra seus portões e deixe entrar a luz de um novo mundo!",
  ui_story_5084_50840401_118_dialog_content = "Uau... Acho que realmente vejo um trem na escuridão...",
  ui_story_5084_50840401_119_dialog_content = "Isso é Charon para você... Não importa onde ele vá, o mundo é o seu palco...",
  ui_story_5084_50840401_120_dialog_content = "Ka-chunk, ka-chunk, ka-chunk—! Escute a sinfonia dos mundos antigos e novos enquanto escapa da minha boca! Não tenha medo do som!",
  ui_story_5084_50840401_121_dialog_content = "Agora dirija! Dirija até rompermos as portas do novo mundo! Um paraíso imortal nos aguarda!",
  ui_story_5084_50840401_122_dialog_content = "...",
  ui_story_5084_50840401_123_dialog_content = "É sua vez agora, primo!",
  ui_story_5084_50840401_124_dialog_content = "Heheh, você certamente tem um talento para o drama, mas essa \"porta para um novo mundo\" não é nada além de uma ilusão!",
  ui_story_5084_50840401_125_dialog_content = "A \"porta\" que você procura tão desesperadamente é mais como uma parede sem forma que vai se chocar violentamente contra o seu rosto!",
  ui_story_5084_50840401_126_dialog_content = "Os trilhos do trem irão incendiar, e este gigante vermelho e dourado queimará seus sonhos até virarem cinzas.",
  ui_story_5084_50840401_127_dialog_content = "A morte é a Verdade absoluta! Um prelúdio para o fim deve ser oferecido em tributo! Imortalidade é apenas medo e pânico sem fim!",
  ui_story_5084_50840401_128_dialog_content = "O medo irá te esmagar em um inseto insignificante e te prender na gaiola da eternidade sem nenhuma esperança de fuga.",
  ui_story_5084_50840401_129_dialog_content = "Um brinquedo indefeso para ser observado e atormentado por seres ainda superiores!",
  ui_story_5084_50840401_130_dialog_content = "Olhe para cima!",
  ui_story_5084_50840401_131_dialog_content = "Esta é a realidade do novo mundo—Um ciclo interminável de manipulação!",
  ui_story_5084_50840401_132_dialog_content = "...!",
  ui_story_5084_50840401_133_dialog_content = "Aos olhos de nossos senhores ocultos, sua loucura serve apenas para o divertimento deles.",
  ui_story_5084_50840401_134_dialog_content = "O poder de inspirar medo é a verdadeira arte!",
  ui_story_5084_50840401_135_dialog_content = "... Aaaaahhhh!",
  ui_story_5084_50840401_136_dialog_content = "... Primo, você—!",
  ui_story_5084_50840401_137_dialog_content = "Isso é muito mais emocionante do que a arte eterna, não é?",
  ui_story_5084_50840401_138_dialog_content = "Hahahahahahaha...!",
  ui_story_5084_50840401_139_dialog_content = "... Uaaaahhhh!!!",
  ui_story_5084_50840401_140_dialog_content = "M-Meu trem... Pare! Pare agora mesmo!",
  ui_story_5084_50840401_141_dialog_content = "Hahahahahahaha...",
  ui_story_5084_50840401_142_dialog_content = "Não fazia ideia que a Senhora Victoria tinha uma prima tão engraçada.",
  ui_story_5084_50840401_143_dialog_content = "Huh? Acho que você está perdendo o real problema aqui... Como Victoria poderia ser tão cruel com Charon?!",
  ui_story_5084_50840401_144_dialog_content = "Não é à toa que ele sempre reluta em falar sobre Victoria como seu parente... Que tipo de arte é essa?!",
  ui_story_5084_50840401_145_dialog_content = "Eu não posso concordar com isso, Wilhelm...",
  ui_story_5084_50840401_146_dialog_content = "Do que você tem tanto medo, Clavis? Ou você realmente não consegue ver a piora da nossa situação?",
  ui_story_5084_50840401_147_dialog_content = "Porfírio e os governantes da casa deixaram de seguir as regras após se desvincularem da linhagem Varaki.",
  ui_story_5084_50840401_148_dialog_content = "Você não vai salvar ninguém assim.",
  ui_story_5084_50840401_149_dialog_content = "Mas, em seu estado atual, a Verdadeira Ordem não é nada além de uma praga para nós e para as pessoas desta cidade! Os preceitos das famílias de sangue nos aprisionam a todos!",
  ui_story_5084_50840401_150_dialog_content = "A sede de sangue está em nossa natureza, Wilhelm... Em nosso próprio sangue. E embora você e eu sejamos um pouco mais afortunados que os demais, não somos diferentes neste aspecto.",
  ui_story_5084_50840401_151_dialog_content = "Nossa natureza, você diz...? Quando você começou a se preocupar com esse tipo de conversa, Clavis?",
  ui_story_5084_50840401_152_dialog_content = "Não me culpe por isso, Wilhelm. Simplesmente não posso negar o que sei ser verdade...",
  ui_story_5084_50840401_153_dialog_content = "Essa <color=#FFB400>chave</color> só vai te trazer mal.",
  ui_story_5084_50840401_154_dialog_content = "Logo antes de morrer, meu irmão pegou de volta dos <color=#FFB400>Vinekeepers</color> e deu para você... Claramente, era para garantir que a chave chegaria às minhas mãos algum dia.",
  ui_story_5084_50840401_155_dialog_content = "... Ou talvez fosse para impedir que você o pegasse à força dos <color=#FFB400>Vinekeepers</color> você mesmo.",
  ui_story_5084_50840401_156_dialog_content = "Apesar dos seus métodos não ortodoxos, você já liderou a Verdadeira Ordem como sucessor do seu irmão por muitos anos agora.",
  ui_story_5084_50840401_157_dialog_content = "Tudo o que aconteceu foi previsto em uma antiga profecia.",
  ui_story_5084_50840401_158_dialog_content = "O curso do destino não pode ser alterado. Você sabe disso melhor do que eu.",
  ui_story_5084_50840401_159_dialog_content = "Não! Eu me recuso a aceitar isso!",
  ui_story_5084_50840401_160_dialog_content = "Coloco minha fé no Senhor da Verdade; o destino dos Varaki não me preocupa! Pelo menos, me recuso a aceitar esse tal de \"curso do destino...\"",
  ui_story_5084_50840401_161_dialog_content = "Não importa o que me aconteça, eu vou suportar. Eu devo.",
  ui_story_5084_50840401_162_dialog_content = "Desde o início, sempre segui a orientação do meu coração. Para mim, isso é A Verdade.",
  ui_story_5084_50840401_163_dialog_content = "E o que dizer de Victoria? Seu irmão confiou ela a você...",
  ui_story_5084_50840401_164_dialog_content = "Não há necessidade de mencioná-la, Clavis.",
  ui_story_5084_50840401_165_dialog_content = "O desprezo de Victoria pelo nosso poder e sua indiferença pelos assuntos da cidade de Varaki são ainda maiores que os meus. Ela pode cuidar de si mesma.",
  ui_story_5084_50840401_166_dialog_content = "Heheh... Talvez isso também seja um castigo pelas ações do meu irmão.",
  ui_story_5084_50840401_167_dialog_content = "Wilhelm...",
  ui_story_5084_50840401_168_dialog_content = "Em qualquer caso... Por favor, cuide bem da sua família, Clavis.",
  ui_story_5084_50840401_169_dialog_content = "... Waaaahhhh!!!",
  ui_story_5084_50840401_170_dialog_content = "...",
  ui_story_5084_50840401_171_dialog_content = "É hora de irmos, Victoria Varaki.",
  ui_story_5084_50840401_172_dialog_content = "...",
  ui_story_5084_50840401_173_dialog_content = "Já? Mas eu ainda não aprendi nada... Eu tenho que encontrar uma maneira de alcançá-los... Espere, é isso! Eu só tenho que me concentrar, e...",
  ui_story_5084_50840401_174_dialog_content = "Está funcionando! A vela está começando a piscar! Rápido—",
  ui_story_5084_50840401_175_dialog_content = "Seque suas lágrimas, Charon...",
  ui_story_5084_50840401_176_dialog_content = "Amaldiçoe ela... Amaldiçoe essa louca...!",
  ui_story_5084_50840401_177_dialog_content = "Chega! Agora, pegue todos esses pedaços quebrados!",
  ui_story_5084_50840401_178_dialog_content = "... Cheira...",
  ui_story_5084_50840501_1_dialog_content = "Acho que agora peguei o jeito. Quando a vela começou a piscar, comecei a me perguntar o que Wilhelm estava pensando.",
  ui_story_5084_50840501_2_dialog_content = "Então isso significa... Estamos na casa do Lorde Wilhelm agora?",
  ui_story_5084_50840501_3_dialog_content = "É ele! Senhor Wilhelm!",
  ui_story_5084_50840501_4_dialog_content = "Ele parece realmente triste segurando aquele anel...",
  ui_story_5084_50840501_5_dialog_content = "Ainda não sabemos o que ele está realmente pensando, embora.",
  ui_story_5084_50840501_6_dialog_content = "Você é o lendário Último Celestita, não é? Apenas escute os pensamentos dele já!",
  ui_story_5084_50840501_7_dialog_content = "D-Não chame isso de \"espionagem\"! Não é para isso que servem meus poderes!",
  ui_story_5084_50840501_8_dialog_content = "Bem, como mais deveríamos descobrir o que ele está tramando?!",
  ui_story_5084_50840501_9_dialog_content = "...",
  ui_story_5084_50840501_10_dialog_content = "Agora pare de perder tempo! Como adulto, você precisa ser mais decisivo!",
  ui_story_5084_50840501_11_dialog_content = "Tudo bem! Tenho certeza de que não é contra as regras do Sikare se eu apenas ler um pouco dos seus pensamentos...",
  ui_story_5084_50840501_12_option_content = "Ligação da Mente—",
  ui_story_5084_50840501_13_dialog_content = "Os sussurros presos dentro desta relíquia... Ao simplesmente usá-la, vou experimentar a dor de ser devorado inúmeras vezes em um instante...",
  ui_story_5084_50840501_14_dialog_content = "Os Varaki... E o resto da família de sangue... Existe realmente uma fuga do nosso destino...?",
  ui_story_5084_50840501_15_dialog_content = "Nascidos como aurorianos, mas amaldiçoados a viver nesta cidade escura e sem sol, onde o poder só pode ser passado através da herança.",
  ui_story_5084_50840501_16_dialog_content = "Sob a orientação de nossos ancestrais, corremos, nos escondemos e levamos vidas que não são melhores que a morte...",
  ui_story_5084_50840501_17_dialog_content = "A vontade de nossos ancestrais... A sucessão de poder... Como é totalmente sem sentido. Os Varaki abandonarão nossas futuras gerações antes de ceder qualquer controle.",
  ui_story_5084_50840501_18_dialog_content = "E embora tenhamos aprendido a subsistir com substitutos de sangue, não há como nos livrarmos da fonte de nosso maléfico poder.",
  ui_story_5084_50840501_19_dialog_content = "(Substitutos de sangue... O \"néctar da vida\" que Victoria continua falando... Será que é...?)",
  ui_story_5084_50840501_20_dialog_content = "Amaldiçoe este anel infernal...",
  ui_story_5084_50840501_21_dialog_content = "Amaldiçoe tudo...",
  ui_story_5084_50840501_22_dialog_content = "A cada ano que passa, os chefes das famílias ficam mais famintos por sangue fresco...",
  ui_story_5084_50840501_23_dialog_content = "*Suspiro*, Clavis... Faz três anos desde a última vez que falamos. Eu me pergunto como ele está se saindo nos dias de hoje?",
  ui_story_5084_50840501_24_dialog_content = "(Já fazem três anos desde que Wilhelm e Victoria visitaram o pai de Charon? Espere... Então, que ano é agora?)",
  ui_story_5084_50840501_25_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5084_50840501_26_dialog_content = "...",
  ui_story_5084_50840501_27_dialog_content = "É Victoria...",
  ui_story_5084_50840501_28_dialog_content = "Mas aquela presença... Parece que ainda é a versão passada dela.",
  ui_story_5084_50840501_29_dialog_content = "É a Senhora Victoria do passado novamente! Então, você ouviu algo importante agora mesmo?",
  ui_story_5084_50840501_30_dialog_content = "Wilhelm guardou o anel assim que Victoria entrou na sala. Agora parece que algo está bloqueando meus poderes...",
  ui_story_5084_50840501_31_dialog_content = "Então você não consegue mais ler os pensamentos dele?",
  ui_story_5084_50840501_32_dialog_content = "Isso mesmo... Acho que aquele anel está colocando sua psique sob uma enorme tensão. Vamos apenas ver o que eles têm a dizer desta vez.",
  ui_story_5084_50840501_33_dialog_content = "Hum...",
  ui_story_5084_50840501_34_dialog_content = "Bem-vindo de volta... Você se foi por três meses desta vez. Como você se saiu?",
  ui_story_5084_50840501_35_dialog_content = "... Isso não é da sua conta.",
  ui_story_5084_50840501_36_dialog_content = "O olhar em seus olhos... Tão cheio de ressentimento e incerteza...",
  ui_story_5084_50840501_37_dialog_content = "O que você viu no mundo exterior, Wilhelm Varaki?",
  ui_story_5084_50840501_38_dialog_content = "Eu não me lembro de ter permitido que você entrasse no meu quarto.",
  ui_story_5084_50840501_39_dialog_content = "Você é o líder da Verdadeira Ordem, e ainda assim sai regularmente sem cumprir suas obrigações... Você também tem passado menos tempo em casa.",
  ui_story_5084_50840501_40_dialog_content = "Quantas vezes eu preciso dizer que isso não é da sua conta?! Agora me deixe!",
  ui_story_5084_50840501_41_dialog_content = "Muito bem então; Não sou estranho em ser negado a sua conversa. Mas, dado que esta noite é o Advento da Verdade, eu estava esperando que pudéssemos ter uma discussão final.",
  ui_story_5084_50840501_42_dialog_content = "Sobre A Verdade, e nós mesmos...",
  ui_story_5084_50840501_43_dialog_content = "Eu disse saia! Não me faça repetir!",
  ui_story_5084_50840501_44_dialog_content = "...",
  ui_story_5084_50840501_45_dialog_content = "O Lorde Wilhelm está tão hostil agora... O que poderia ter acontecido com ele...?",
  ui_story_5084_50840501_46_dialog_content = "... Nngh... <size=45>Aaaaah...!</size>",
  ui_story_5084_50840501_47_dialog_content = "Algo está errado com o Lorde Wilhelm... Rápido, faça alguma coisa!",
  ui_story_5084_50840501_48_dialog_content = "É aquele anel...?",
  ui_story_5084_50840501_49_option_content = "Mindlink—",
  ui_story_5084_50840501_50_dialog_content = "Hahahahaha! Morda os dedos dela! Quebre seu lindo pescoço!",
  ui_story_5084_50840501_51_dialog_content = "Fique em silêncio...",
  ui_story_5084_50840501_52_dialog_content = "Que tolice absoluta. Em sua desesperada tentativa de manter o poder, você voluntariamente usa um anel que te enlouquece diante do verdadeiro líder do seu povo.",
  ui_story_5084_50840501_53_dialog_content = "Deseja acabar com a vida dela... Ou com a sua?",
  ui_story_5084_50840501_54_dialog_content = "Heheh... Eu me acostumei com a dor que você me causou há muito tempo...",
  ui_story_5084_50840501_55_dialog_content = "O Varaki será destruído em suas mãos.",
  ui_story_5084_50840501_56_dialog_content = "Heh... Se estou destinado à destruição, então a Verdadeira Ordem compartilhará do meu destino...",
  ui_story_5084_50840501_57_dialog_content = "Ela fez muitas novas alianças. Uma vez que a linhagem Varaki seja erradicada, a True Order renascerá.",
  ui_story_5084_50840501_58_dialog_content = "Ela será a única a acabar com o Varaki de uma vez por todas.",
  ui_story_5084_50840501_59_dialog_content = "Incluindo eu?",
  ui_story_5084_50840501_60_dialog_content = "Somente morrendo em suas mãos você realmente começará a viver...",
  ui_story_5084_50840501_61_dialog_content = "Você está se ouvindo agora mesmo?",
  ui_story_5084_50840501_62_dialog_content = "Sim, e eu estou te dizendo para morrer!!",
  ui_story_5084_50840501_63_dialog_content = "(Essas vozes são aterrorizantes! É como se estivessem corroendo a consciência de Wilhelm...)",
  ui_story_5084_50840501_64_dialog_content = "(Será que este anel concede ao seu portador um poder enorme em troca de causar-lhes um sofrimento imenso?)",
  ui_story_5084_50840501_65_dialog_content = "(Parece muito algo da Verdadeira Ordem, isso é certo...)",
  ui_story_5084_50840501_66_dialog_content = "(E de quem são aquelas vozes? Os ancestrais Varaki? O dono original do anel? Ou talvez...)",
  ui_story_5084_50840501_67_dialog_content = "<size=45>Urgh... Ahhhhhhhhh!</size>",
  ui_story_5084_50840501_68_dialog_content = "Lute contra o destino até o conteúdo do seu coração...",
  ui_story_5084_50840501_69_dialog_content = "Sai... Fora!!!",
  ui_story_5084_50840501_70_dialog_content = "Conheça seus limites, tolo.",
  ui_story_5084_50840501_71_dialog_content = "Meu corpo... <size=45>Saia do meu corpo!!!</size>",
  ui_story_5084_50840501_72_dialog_content = "Senhor da Verdade...! Mostre-me o caminho!!!",
  ui_story_5084_50840501_73_dialog_content = "(Wilhelm está prestes a desmaiar!)",
  ui_story_5084_50840501_74_dialog_content = "(Essas vozes estão se transformando em monstros em sua mente. Eu posso ser capaz de fazer algo aqui!)",
  ui_story_5084_50840502_1_dialog_content = "Oh? Parece que você aprendeu uma nova habilidade, Wilhelm...",
  ui_story_5084_50840502_2_dialog_content = "Sua mente... Tão calma e estável...",
  ui_story_5084_50840502_3_dialog_content = "...",
  ui_story_5084_50840502_4_dialog_content = "(Uh-oh! Não me diga que eles me notaram...)",
  ui_story_5084_50840502_5_dialog_content = "Como recompensa, vou deixar você ver algo interessante.",
  ui_story_5084_50840502_6_dialog_content = "May A Verdade o abençoe.",
  ui_story_5084_50840502_7_dialog_content = "Finalmente... Outra grande conquista está agora completa.",
  ui_story_5084_50840502_8_dialog_content = "O sangue de um discípulo... Como eu ansiava pelo seu sabor...",
  ui_story_5084_50840502_9_dialog_content = "Que conhecimento você obteve da Verdade?",
  ui_story_5084_50840502_10_dialog_content = "A Verdade me mostrou apenas uma coisa... Gratidão.",
  ui_story_5084_50840502_11_dialog_content = "Apenas sob a luz de uma lua de sangue podemos realmente saciar nossa sede de sangue.",
  ui_story_5084_50840502_12_dialog_content = "Os fiéis dançam selvagemente enquanto rezam, oferecendo seus corpos auto-flagelados a um deus que nunca podem verdadeiramente compreender.",
  ui_story_5084_50840502_13_dialog_content = "Por séculos... Eles viveram dessa maneira...",
  ui_story_5084_50840502_14_dialog_content = "Mas este sabor delicioso merece muito mais apreciação...",
  ui_story_5084_50840502_15_dialog_content = "Por que não selecionar mais alguns discípulos fiéis para o Advento da Verdade deste ano?",
  ui_story_5084_50840502_16_dialog_content = "Este é o conhecimento que você adquiriu ao consumir o sangue deste fiel servo?",
  ui_story_5084_50840502_17_dialog_content = "Não completamente.",
  ui_story_5084_50840502_18_dialog_content = "Quando a Verdade flui através de seus corpos, consumimos seu sangue para adquirir esse conhecimento e passá-lo para as futuras gerações.",
  ui_story_5084_50840502_19_dialog_content = "Este é o pacto entre nós, os chefes de família, e os fiéis.",
  ui_story_5084_50840502_20_dialog_content = "Tais sacrifícios são inúteis se eles não nos permitem testemunhar A Verdade.",
  ui_story_5084_50840502_21_dialog_content = "Alguma coisa foi revelada para você?",
  ui_story_5084_50840502_22_dialog_content = "De nada.",
  ui_story_5084_50840502_23_dialog_content = "Deixe-me lembrá-lo de nossos princípios e nossa necessidade de sigilo.",
  ui_story_5084_50840502_24_dialog_content = "Como chefes de famílias, vocês têm a obrigação de sustentá-las. Em nenhuma circunstância somos permitidos a retornar aos nossos antigos modos bárbaros.",
  ui_story_5084_50840502_25_dialog_content = "Que a Verdade abençoe você.",
  ui_story_5084_50840502_26_dialog_content = "Que a Verdade abençoe você.",
  ui_story_5084_50840502_27_dialog_content = "Essas visões me foram reveladas há muito tempo, quando o poder da minha linhagem foi despertado.",
  ui_story_5084_50840502_28_dialog_content = "Um ritual antigo para o Advento da Verdade, no qual nossos ancestrais consomem totalmente o sangue de um sacrifício para obter inspiração divina.",
  ui_story_5084_50840502_29_dialog_content = "Espere... Isso significa que o Iniciado é comido durante cada Advento da Verdade?!",
  ui_story_5084_50840502_30_dialog_content = "Não admira que eles estavam rindo assim mais cedo!!",
  ui_story_5084_50840502_31_dialog_content = "Victoria realmente foi sacrificado assim?!",
  ui_story_5084_50840502_32_dialog_content = "Tem alguém aí...?",
  ui_story_5084_50840502_33_dialog_content = "Oh? Parece que você tem um visitante, Wilhelm.",
  ui_story_5084_50840502_34_dialog_content = "...",
  ui_story_5084_50840502_35_dialog_content = "Uh, PlayerName... O que você fez? O Senhor Wilhelm não nos vê, vê?",
  ui_story_5084_50840502_36_dialog_content = "Desculpe... Eu devo ter me exaltado demais agora...",
  ui_story_5084_50840502_37_dialog_content = "Mas eu vi algumas coisas realmente perturbadoras na mente de Wilhelm...",
  ui_story_5084_50840502_38_dialog_content = "Ainda estou bastante preocupado com Victoria, então vou tentar novamente!",
  ui_story_5084_50840502_39_option_content = "Mindlink—",
  ui_story_5084_50840502_40_dialog_content = "E quanto a estes?",
  ui_story_5084_50840502_41_dialog_content = "Mesmo após oferecer sua própria sobrinha, o Senhor da Verdade não lhe agraciou com nenhuma revelação. Sua própria falha finalmente te enlouqueceu?",
  ui_story_5084_50840502_42_dialog_content = "Não importa. Eu já me cansei dos seus jogos há muito tempo, Wilhelm.",
  ui_story_5084_50840502_43_dialog_content = "A Bíblia Sangrenta é minha agora! A Verdade está ao meu alcance!",
  ui_story_5084_50840502_44_dialog_content = "...! Isso é uma profecia...? O Advento da Verdade... Esta noite...",
  ui_story_5084_50840502_45_dialog_content = "(É aquele cara que eu vi no templo mais cedo! Eles estão prestes a sacrificar Victoria para o Advento da Verdade... O que significa que estamos de volta no ano de 1915!)",
  ui_story_5084_50840502_46_dialog_content = "Ainda não acredita em mim?",
  ui_story_5084_50840502_47_dialog_content = "... É assim que minha vida termina?",
  ui_story_5084_50840502_48_dialog_content = "Você ainda não consegue compreender o poder dos Varaki, mas condenaria a família de sangue à morte por causa de sua própria infelicidade.",
  ui_story_5084_50840502_49_dialog_content = "A juventude sempre torce o nariz para o dogma de seus predecessores.",
  ui_story_5084_50840502_50_dialog_content = "Mas você nunca foi o líder da Verdadeira Ordem para começar.",
  ui_story_5084_50840502_51_dialog_content = "Hehe... Hahahaha...",
  ui_story_5084_50840502_52_dialog_content = "A Verdade? Que absurdo...",
  ui_story_5084_50840502_53_dialog_content = "Você passou tanto tempo com a mão do meu irmão que herdou o temperamento ruim dele?",
  ui_story_5084_50840502_54_dialog_content = "Ele me amaldiçoou ao confiar a família e sua filha a mim... E agora Victoria, o verdadeiro líder da ordem, nos deixou...",
  ui_story_5084_50840502_55_dialog_content = "Ele se permitiu ser enganado por uma falsa visão do futuro, permitindo que isso o distorcesse e manipulasse para os fins de outra pessoa.",
  ui_story_5084_50840502_56_dialog_content = "Um sentimento que conheço muito bem...",
  ui_story_5084_50840502_57_dialog_content = "Cometi esse erro antes. Sou capaz de fazer isso novamente?",
  ui_story_5084_50840502_58_dialog_content = "Você realmente deseja poupar Victoria?",
  ui_story_5084_50840502_59_dialog_content = "Isso.",
  ui_story_5084_50840502_60_dialog_content = "Você hesitou.",
  ui_story_5084_50840502_61_dialog_content = "Aqueles que desejam vê-la morta são os outros chefes de famílias. Como o segundo filho dos Varaki, minha morte não teria consequências; o que eles realmente temem é ver Victoria ascender ao poder.",
  ui_story_5084_50840502_62_dialog_content = "Se a profecia for verdadeira...",
  ui_story_5084_50840502_63_dialog_content = "O poder na linhagem de Victoria despertou relativamente tarde, e ela não respondeu à Verdade que eu transmiti a ela.",
  ui_story_5084_50840502_64_dialog_content = "Se eu morrer, esses parasitas nunca a deixarão ir...",
  ui_story_5084_50840502_65_dialog_content = "Victoria... Victoria...",
  ui_story_5084_50840502_66_dialog_content = "(Hã? Ele está preocupado com Victoria?)",
  ui_story_5084_50840502_67_dialog_content = "Isso mesmo! Como líder da True Order, sou eu quem declara o Iniciado! Mas...",
  ui_story_5084_50840502_68_dialog_content = "Ela disse que não tinha intenção de estar no Advento da Verdade esta noite... Onde ela poderia estar...?",
  ui_story_5084_50840502_69_dialog_content = "Isso significa que Victoria apareceu no templo no pior momento possível! Ela realmente foi sacrificada!",
  ui_story_5084_50840502_70_dialog_content = "Quem está aí? Mostre-se...",
  ui_story_5084_50840502_71_dialog_content = "(Oh não, de novo não...!)",
  ui_story_5084_50840502_72_dialog_content = "Heheh, então você tem uma contingência em mente?",
  ui_story_5084_50840502_73_dialog_content = "PlayerName! Você fez alguma coisa de novo?!",
  ui_story_5084_50840502_74_dialog_content = "Acabou... Assim que ele mencionou sacrificar Victoria, eu não pude me controlar...",
  ui_story_5084_50840502_75_dialog_content = "Sacrificando a Senhora Victoria... Espere, é hoje à noite? Isso significa que a mesma coisa exata está prestes a acontecer?!",
  ui_story_5084_50840502_76_dialog_content = "Temo que sim... Mesmo que Wilhelm pareça estar preocupado com Victoria, ainda preciso saber o que ele planeja fazer com ela...",
  ui_story_5084_50840502_77_dialog_content = "Este estudo... É uma das relíquias de <color=#FFB400>Osten Varaki</color> ainda aqui em algum lugar?",
  ui_story_5084_50840502_78_dialog_content = "Ou poderia ser... Ele?",
  ui_story_5084_50840502_79_dialog_content = "Me diga! Oferecer Victoria como um sacrifício... Isso é a sua vontade?",
  ui_story_5084_50840502_80_dialog_content = "\"Ele\"?",
  ui_story_5084_50840502_81_dialog_content = "Quem falou com você agora?! Me diga!",
  ui_story_5084_50840502_82_dialog_content = "Meu senhor...!",
  ui_story_5084_50840502_83_dialog_content = "... Uraaagh! <size=45>Maldito seja este anel amaldiçoado!!!</size>",
  ui_story_5084_50840502_84_dialog_content = "Mate-me, meu senhor... Liberte-me do meu sofrimento!!!",
  ui_story_5084_50840502_85_dialog_content = "Apenas olhe para o seu estado distorcido... Patético.",
  ui_story_5084_50840502_86_dialog_content = "Argh... Aaaaahhh!",
  ui_story_5084_50840502_87_dialog_content = "Ahahahaha—! Eu sou o legítimo líder da True Order! Eu!!!",
  ui_story_5084_50840502_88_dialog_content = "(O anel está atacando a mente de Wilhelm novamente... O que eu deveria fazer?)",
  ui_story_5084_50840502_89_dialog_content = "Wilhelm, você tolo sem esperança. Como eu disse antes, você deve morrer para viver.",
  ui_story_5084_50840502_90_dialog_content = "Eu não temo a morte... Mas Victoria... E ela?!?",
  ui_story_5084_50840502_91_dialog_content = "Senhor da Verdade...",
  ui_story_5084_50840502_92_dialog_content = "Diga-me o que vai acontecer com Victoria depois de hoje...!!!",
  ui_story_5084_50840502_93_dialog_content = "Ele perdeu completamente o controle! Ele não vai sobreviver se isso continuar!",
  ui_story_5084_50840502_94_dialog_content = "Parece que você pode fazer contato com ele usando seus poderes, PlayerName. Por que não tentar isso?",
  ui_story_5084_50840502_95_dialog_content = "Mas se eu fizer isso, pode afetar o passado! Estaremos em apuros se isso acontecer...",
  ui_story_5084_50840502_96_dialog_content = "Você acredita no Senhor da Verdade, certo May? O que faria você se sentir calmo em uma situação como esta sem levantar suspeitas?",
  ui_story_5084_50840502_97_dialog_content = "Eu não sei, algo simples como \"May Que a Verdade te abençoe,\" ou \"Siga a orientação,\" eu suponho?",
  ui_story_5084_50840502_98_dialog_content = "Sério...? Acho que vale a pena tentar...",
  ui_story_5084_50840502_99_option_content = "Mindlink—",
  ui_story_5084_50840502_100_dialog_content = "Que a Verdade abençoe você.",
  ui_story_5084_50840502_101_dialog_content = "...",
  ui_story_5084_50840502_102_dialog_content = "Que a Verdade abençoe você.",
  ui_story_5084_50840502_103_dialog_content = "M-May Que a Verdade te abençoe...",
  ui_story_5084_50840502_104_dialog_content = "Você... Quem exatamente é você...?",
  ui_story_5084_50840502_105_dialog_content = "(Parece que está funcionando, mas é melhor eu ter cuidado para não dizer a coisa errada...)",
  ui_story_5084_50840502_106_dialog_content = "Peço desculpas, mas não posso mais acreditar em um deus que manipula os corações das pessoas. A Verdade em meu coração não me levará ao erro.",
  ui_story_5084_50840502_107_dialog_content = "A Verdadeira Ordem não pode continuar a existir desta maneira, pelo menos não no futuro de Victoria.",
  ui_story_5084_50840502_108_dialog_content = "Se você também acredita no Senhor da Verdade, entenderá minhas palavras.",
  ui_story_5084_50840502_109_dialog_content = "Para você aparecer diante de mim agora, deve significar que você tem algo para me dizer... Correto?",
  ui_story_5084_50840502_110_dialog_content = "... Siga a orientação.",
  ui_story_5084_50840502_111_dialog_content = "... Então você acredita que eu deveria aceitar a realidade e me permitir ser consumido pelos chefes de nossas famílias...",
  ui_story_5084_50840502_112_dialog_content = "Para que a Victoria possa continuar carregando a maldição do nosso povo, e finalmente encontrar seu fim nas mãos daquele vampiro?",
  ui_story_5084_50840502_113_dialog_content = "(Não, isso não está certo... Como eu pioro as coisas...?)",
  ui_story_5084_50840502_114_dialog_content = "... Não! Absolutamente não!",
  ui_story_5084_50840502_115_dialog_content = "Cheguei tão longe apesar de ter sido abandonado pela minha família, e devo tudo à Verdade dentro do meu próprio coração! Essa Verdade nunca me levará ao erro!",
  ui_story_5084_50840502_116_dialog_content = "São essas chamadas \"revelações\" que fizeram a Verdadeira Ordem cair tão baixo...",
  ui_story_5084_50840502_117_dialog_content = "Eu devo... Desfazer essa maldição.",
  ui_story_5084_50840502_118_dialog_content = "Mas como...",
  ui_story_5084_50840502_119_dialog_content = "... A única relíquia sagrada que não foi manchada por um líder... É <color=#FFB400>aquela</color>.",
  ui_story_5084_50840502_120_dialog_content = "A lua de sangue... Quando suas vinhas assumem forma viva, um guardião aguardará o mestre da cripta em sua entrada.",
  ui_story_5084_50840502_121_dialog_content = "Mas além de transportar o caixão do nosso ancestral para dentro e fora do túmulo... A única maneira de entrar é com a <color=#FFB400>chave</color>, ou com o consentimento dos chefes das famílias...",
  ui_story_5084_50840502_122_dialog_content = "Hah! Wilhelm, seu miserável... Ainda pensando nas regras mesmo quando está prestes a ser devorado? Você merece ser ridicularizado...",
  ui_story_5084_50840502_123_dialog_content = "Mesmo que Clavis se recuse a me dar a chave, os Guardiões das Vinhas serviram os Varaki por gerações...",
  ui_story_5084_50840502_124_dialog_content = "Certamente ele me permitirá entrar na cripta agora que adquiri esse conhecimento?",
  ui_story_5084_50840502_125_dialog_content = "Devo entrar antes do início da procissão!",
  ui_story_5084_50840502_126_dialog_content = "<color=#e8d9bb>Fwoosh!</color>",
  ui_story_5084_50840502_127_dialog_content = "Aguente firme, May!",
  ui_story_5084_50840502_128_dialog_content = "Para onde estamos indo desta vez?!",
  ui_story_5084_50840502_129_dialog_content = "A tumba do Varaki!",
  ui_story_5084_50840601_1_dialog_content = "<color=#e8d9bb>Na entrada de uma loja de alfaiate na Cidade Varaki</color>",
  ui_story_5084_50840601_2_dialog_content = "May Que a Verdade vos abençoe, uma costureira habilidosa.",
  ui_story_5084_50840601_3_dialog_content = "E que a Verdade lhe abençoe também, gentil senhor. Com tal aparência piedosa, você definitivamente será escolhido como o Iniciado este ano.",
  ui_story_5084_50840601_4_dialog_content = "Rezo para que seja assim, minha querida. Preciso ir agora; até nos encontrarmos no banquete esta noite. Não se atrase.",
  ui_story_5084_50840601_5_dialog_content = "Eu garanto que não vou.",
  ui_story_5084_50840601_6_dialog_content = "Que... Como viemos parar aqui?",
  ui_story_5084_50840601_7_dialog_content = "Você está aqui pela veste cerimonial, senhor?",
  ui_story_5084_50840601_8_dialog_content = "Vestimenta cerimonial...?",
  ui_story_5084_50840601_9_dialog_content = "Ah, você deve ser cliente de outra pessoa.",
  ui_story_5084_50840601_10_dialog_content = "Você deve saber, nossa família de alfaiates está no negócio há mais tempo aqui na Cidade Varaki. Durante cada Advento da Verdade, nossa loja também lida com a maioria dos pedidos de roupões.",
  ui_story_5084_50840601_11_dialog_content = "Até as pessoas que vivem nas bordas da nossa cidade virão comprar nossas túnicas na própria noite da celebração.",
  ui_story_5084_50840601_12_dialog_content = "Então, por que não fazer um pedido conosco? Garanto que o preço será do seu agrado.",
  ui_story_5084_50840601_13_dialog_content = "...",
  ui_story_5084_50840601_14_dialog_content = "Olha, amigo! A lua de sangue apareceu.",
  ui_story_5084_50840601_15_dialog_content = "A lua de sangue... O Advento da Verdade é esta noite...",
  ui_story_5084_50840601_16_dialog_content = "Meu mentor disse que me escolheria como o Iniciado deste ano, o que significa que devo me vestir piedosamente para a ocasião.",
  ui_story_5084_50840601_17_dialog_content = "O Iniciado?! Eu ouvi isso corretamente...?",
  ui_story_5084_50840601_18_dialog_content = "Mas a única pessoa que pode anunciar o Iniciado é o Lord Wilhelm Varaki! Por que ele escolheu você, de todas as pessoas?",
  ui_story_5084_50840601_19_dialog_content = "Sim, esse é o nome do meu mentor. Nos conhecemos na cripta da família dele.",
  ui_story_5084_50840601_20_dialog_content = "O túmulo do Varaki...?! Entendo... Diga-me, como você conseguiu se aproximar tanto da Verdade?",
  ui_story_5084_50840601_21_dialog_content = "... Eu confesso meus pecados e busco penitência todos os dias, mas todos ainda me evitam. Todos... Exceto meu mentor.",
  ui_story_5084_50840601_22_dialog_content = "Penitência... O Advento da Verdade... E a lua de sangue... Sim, acho que entendo agora...",
  ui_story_5084_50840601_23_dialog_content = "Obrigado por me transmitir este conhecimento da Verdade, honrado Iniciado...",
  ui_story_5084_50840601_24_dialog_content = "Tenho aceitado dinheiro dos fiéis em nome do Advento da Verdade... E assim, a Verdade me rejeitou...",
  ui_story_5084_50840601_25_dialog_content = "Abençoe você, Iniciado... Abençoe você por me mostrar o erro dos meus caminhos.",
  ui_story_5084_50840601_26_dialog_content = "Você se importaria de nos agraciar com sua presença por um pouco mais de tempo? Minha mãe, minha filha e eu ficaríamos honradas em confeccionar um conjunto de vestes para você com a máxima urgência!",
  ui_story_5084_50840601_27_dialog_content = "Th-Isso não será necessário... Eu estava simplesmente de passagem em busca do meu mentor.",
  ui_story_5084_50840601_28_dialog_content = "Isso não foi coincidência, senhor; A Verdade deve ter guiado você aqui hoje! Por favor, me perdoe por ter me comportado tão rudemente agora mesmo—",
  ui_story_5084_50840601_29_dialog_content = "De novo, realmente não é necessário...",
  ui_story_5084_50840601_30_dialog_content = "Mãe? O que você ainda está fazendo aqui?! Nossos clientes estão cansados de esperar!",
  ui_story_5084_50840601_31_dialog_content = "Diga a eles que entregaremos suas túnicas hoje, totalmente grátis!",
  ui_story_5084_50840601_32_dialog_content = "Há?",
  ui_story_5084_50840601_33_dialog_content = "Depois disso, vamos confeccionar um conjunto de roupas para este jovem imediatamente! Ele é o Iniciado!",
  ui_story_5084_50840601_34_dialog_content = "Você quer dizer agora mesmo?",
  ui_story_5084_50840601_35_dialog_content = "Sim, querida!",
  ui_story_5084_50840601_36_dialog_content = "A avó não vai ficar feliz com isso...",
  ui_story_5084_50840601_37_dialog_content = "Apenas faça o que eu digo, por enquanto, criança. Eu vou explicar tudo para a sua avó.",
  ui_story_5084_50840601_38_dialog_content = "Tá bom...",
  ui_story_5084_50840601_39_dialog_content = "Ah... Perdoe-me, Senhor da Verdade! Parece que cometi outro erro...",
  ui_story_5084_50840601_40_dialog_content = "Graças a Deus... Ainda tenho algum dinheiro comigo... Só rezo para que cubra algumas das suas perdas do dia...",
  ui_story_5084_50840601_41_dialog_content = "Mas eu não devo impor a este tipo de costureira ou à sua família mais do que isso...",
  ui_story_5084_50840601_42_dialog_content = "Wilhelm.",
  ui_story_5084_50840601_43_dialog_content = "Quem ousa falar meu nome e bloquear meu caminho?! Saia da frente! A Vinda da Verdade requer minha presença!",
  ui_story_5084_50840601_44_dialog_content = "Você perdeu de vista A Verdade, e sua visão está obscurecida pela realidade.",
  ui_story_5084_50840601_45_dialog_content = "Essa responsabilidade é muito grande para você suportar. Permita-me tomar o seu lugar...",
  ui_story_5084_50840601_46_dialog_content = "Você foi enviado pelos outros chefes de famílias? Então venha para mim!",
  ui_story_5084_50840601_47_dialog_content = "<color=#e8d9bb>A vela oscila e seus arredores mudam mais uma vez - De repente, um túmulo de origens claramente antigas aparece diante deles.</color>",
  ui_story_5084_50840601_48_dialog_content = "<color=#e8d9bb>Um vento frio sopra o pó e os detritos que se acumularam em suas vinhas por séculos.</color>",
  ui_story_5084_50840601_49_dialog_content = "<color=#e8d9bb>Com um susto, as videiras começam a se contorcer e desenrolar, libertando a pessoa presa dentro...</color>",
  ui_story_5084_50840601_50_dialog_content = "Chegamos... Espere, é isso...?",
  ui_story_5084_50840601_51_dialog_content = "O-O que estou fazendo aqui...?",
  ui_story_5084_50840601_52_dialog_content = "Foi aquela pessoa que encontrei mais cedo? Ele deve ter usado algum tipo de truque para me trazer aqui... E agora ele tomou meu lugar na cerimônia...",
  ui_story_5084_50840601_53_dialog_content = "A lua de sangue foi obscurecida... Que horas são agora? Eu perdi o Advento da Verdade?",
  ui_story_5084_50840601_54_dialog_content = "Você foi abençoado com a sabedoria da Verdade.",
  ui_story_5084_50840601_55_dialog_content = "<color=#e8d9bb>As vinhas na entrada da cripta convergem e assumem a forma de um homem de rosto pálido com olhos opacos e sem vida.</color>",
  ui_story_5084_50840601_56_dialog_content = "Meu senhor, a tumba de seus antepassados está aberta para você.",
  ui_story_5084_50840601_57_dialog_content = "Mas... Como?",
  ui_story_5084_50840601_58_dialog_content = "A <color=#FFB400>chave</color> está por perto... Eu posso sentir sua chama.",
  ui_story_5084_50840601_59_dialog_content = "Que chama? O único fogo que vejo por aqui... Está no castiçal em suas mãos.",
  ui_story_5084_50840601_60_dialog_content = "Poderia tudo isso ser... Por minha causa? Primeiro eu o guiei até aqui com minha voz, e agora eu abri a porta do túmulo para ele?",
  ui_story_5084_50840601_61_dialog_content = "O que exatamente eu tenho mudado aqui?",
  ui_story_5084_50840601_62_dialog_content = "Espere, eu não...",
  ui_story_5084_50840601_63_dialog_content = "<color=#e8d9bb>Sem esperar Wilhelm terminar de falar, o Guardião da Videira retorna ao chão musgoso e retoma sua vigília silenciosa.</color>",
  ui_story_5084_50840601_64_dialog_content = "A cripta está aberta, e seu guardião me concedeu entrada...",
  ui_story_5084_50840601_65_dialog_content = "Ainda não fiz nada. Isso poderia ser obra da Verdade?",
  ui_story_5084_50840601_66_dialog_content = "O destino me guiou até aqui, o que significa que o Senhor da Verdade deseja que eu execute sua vontade divina.",
  ui_story_5084_50840601_67_dialog_content = "Preciso entrar.",
  ui_story_5084_50840601_68_dialog_content = "O que ele está fazendo agora...? Vamos lá, May!",
  ui_story_5084_50840601_69_dialog_content = "Talvez o ancestral Varaki possa oferecer mais orientação...",
  ui_story_5084_50840601_70_dialog_content = "O-Onde está o caixão ancestral?! Era para ter sido devolvido assim que a procissão terminou...",
  ui_story_5084_50840601_71_dialog_content = "Quem ousaria perturbar o último lugar de descanso dos Varaki?! Não...",
  ui_story_5084_50840601_72_dialog_content = "O caixão ancestral, e até mesmo a Bíblia Sangrenta... Ambos se foram...",
  ui_story_5084_50840601_73_dialog_content = "Os chefes das famílias já colocaram seus planos em ação?",
  ui_story_5084_50840601_74_dialog_content = "Victoria... Ela está em perigo!",
  ui_story_5084_50840601_75_dialog_content = "Cavalheiro do Inverno! Leve-me de volta ao templo!",
  ui_story_5084_50840601_76_dialog_content = "Que cavalo preto de aparência legal... Não, espera, precisamos ir atrás dele!",
  ui_story_5084_50840601_77_dialog_content = "Discípulos mortos? Por que eles estão vagando por aqui?!",
  ui_story_5084_50840601_78_dialog_content = "Mais cadáveres... O que diabos aconteceu na cidade?!",
  ui_story_5084_50840601_79_dialog_content = "Criatura imunda! Como ousa invadir este lugar e prejudicar os fiéis!",
  ui_story_5084_50840601_80_dialog_content = "Esses seres miseráveis não têm mente própria. Seu mestre deve tê-los soltado na cidade.",
  ui_story_5084_50840601_81_dialog_content = "Eu vou limpar o mundo da existência deles!",
  ui_story_5084_50840602_1_dialog_content = "Ah, Senhor Wilhelm Varaki... Que figura poderosa e cativante!",
  ui_story_5084_50840602_2_dialog_content = "Através de sua sabedoria, me foi concedido um vislumbre através da porta da Verdade.",
  ui_story_5084_50840602_3_dialog_content = "Parece que os fiéis estão completamente inconscientes dos monstros que ameaçam a cidade...",
  ui_story_5084_50840602_4_dialog_content = "A cerimônia do Advento da Verdade acabou, mas os chefes das famílias ainda devem estar no templo...",
  ui_story_5084_50840602_5_dialog_content = "Huff, huff... N-Nós finalmente... Alcançamos...",
  ui_story_5084_50840602_6_dialog_content = "Olha, May! São aqueles dois discípulos para quem você tentou pregar mais cedo! Estamos de volta a este momento novamente!",
  ui_story_5084_50840602_7_dialog_content = "O que significa que deveríamos estar no templo agora mesmo!",
  ui_story_5084_50840602_8_dialog_content = "Uma vez que os discípulos partiram, pensei que a cerimônia havia concluído. Não esperava encontrar você me esperando aqui.",
  ui_story_5084_50840602_9_dialog_content = "Nails! O que você está fazendo aqui?!",
  ui_story_5084_50840602_10_dialog_content = "E que diabos você está vestindo...?",
  ui_story_5084_50840602_11_dialog_content = "Uma gentil costureira e sua família fizeram essas túnicas sob medida para mim. Sou eternamente grato pela generosidade deles.",
  ui_story_5084_50840602_12_dialog_content = "Também sou grato ao meu mentor por me permitir estar aqui hoje.",
  ui_story_5084_50840602_13_dialog_content = "Você...",
  ui_story_5084_50840602_14_dialog_content = "Huh? O que você está falando, Nails?",
  ui_story_5084_50840602_15_dialog_content = "Para ser honesto, eu realmente não entendo o que ele diz metade do tempo, também...",
  ui_story_5084_50840602_16_dialog_content = "Foi uma imensa honra para mim servir como sacrifício para este Advento da Verdade.",
  ui_story_5084_50840602_17_dialog_content = "Perdoe-me, mas eu não tenho ideia do que você está falando.",
  ui_story_5084_50840602_18_dialog_content = "Porfírio! Onde está a Bíblia Sangrenta?!",
  ui_story_5084_50840602_19_dialog_content = "Também tenho perguntas, Wilhelm. O que foi aquele vento negro agora há pouco? E para onde Victoria foi?!",
  ui_story_5084_50840602_20_dialog_content = "Victoria?",
  ui_story_5084_50840602_21_dialog_content = "Even after offering your own niece, the Lord of Truth did not grace you with any revelations. Has your own failure finally driven you mad?",
  ui_story_5084_50840602_22_dialog_content = "It matters not. I've long since grown tired of your games, Wilhelm.",
  ui_story_5084_50840602_23_dialog_content = "The Bloody Bible is mine now! The Truth is within my reach!",
  ui_story_5084_50840602_24_dialog_content = "No entanto... Agora que o ritual deste ano terminou, acredito que temos algo para discutir.",
  ui_story_5084_50840602_25_dialog_content = "É exatamente como vi na profecia... Heheh—Não há mais nada para discutir. Eu sei que você pretende me atacar, Porfírio!",
  ui_story_5084_50840602_26_dialog_content = "Não adianta fingir ignorância; Eu já purguei a cidade de seus servos, que você desencadeou sobre os fiéis inocentes!",
  ui_story_5084_50840602_27_dialog_content = "Então chegou a isso...",
  ui_story_5084_50840602_28_dialog_content = "Parece que Wilhelm Varaki não tem intenção de se render a nós... A Verdade ainda tem muito a me dizer, então devo me despedir de vocês dois.",
  ui_story_5084_50840602_29_dialog_content = "Nem mais um passo, Porfirio!",
  ui_story_5084_50840602_30_dialog_content = "É inútil resistir, Wilhelm. Com a Bíblia Sangrenta em minhas mãos, o destino agora está do meu lado...",
  ui_story_5084_50840602_31_dialog_content = "É hora de trabalhar, velho amigo.",
  ui_story_5084_50840602_32_dialog_content = "O que você pretende fazer com meu mentor? Eu sou o Iniciado, não ele.",
  ui_story_5084_50840602_33_dialog_content = "E de onde você veio, estranho?",
  ui_story_5084_50840602_34_dialog_content = "Nem mesmo os seguidores de Wilhelm serão poupados.",
  ui_story_5084_50840602_35_dialog_content = "Como líder da True Order, não vou permitir que você prejudique mais nenhum dos fiéis!",
  ui_story_5084_50840602_36_dialog_content = "Você deveria se preocupar consigo mesmo primeiro, idiota! Hahahaha!",
  ui_story_5084_50840602_37_dialog_content = "Wilhelm...!",
  ui_story_5084_50840602_38_dialog_content = "Meu senhor, conceda-me sua dor e permita-me sofrer em seu lugar. Engula-a, derrame-a e permita que a Verdade prevaleça sobre o mal...",
  ui_story_5084_50840602_39_dialog_content = "Não, Sr. Nails! Você tem que correr—",
  ui_story_5084_50840602_40_dialog_content = "Pare, May! Não estamos autorizados a interferir... Lembre-se do que Sikare nos disse!",
  ui_story_5084_50840602_41_dialog_content = "Isso é tudo culpa minha. Nada disso teria acontecido se eu tivesse ficado quieto... Precisamos pensar em outra maneira de ajudá-los. Ainda temos o castiçal, então deve haver algo que possamos fazer.",
  ui_story_5084_50840602_42_dialog_content = "Hmph, que surpresa. Seus ossos parecem ser tão fortes quanto a sua fé, pelo visto.",
  ui_story_5084_50840602_43_dialog_content = "Morra!",
  ui_story_5084_50840602_44_dialog_content = "Senhor da Verdade, seus rituais são tão insuportavelmente cruéis. Seus fiéis realmente podem suportar isso? Se sim, como eles podem sobreviver a uma dor tão imensa?",
  ui_story_5084_50840602_45_dialog_content = "Eu vou suportar! Eu vou engolir esse sofrimento e purificar meu corpo de seus pecados. Eu aceitarei essa maldição de dor e queimarei as feridas da minha alma—",
  ui_story_5084_50840602_46_dialog_content = "Permita-me suportar essa dor em solidão, para que nenhuma outra pessoa precise experimentá-la! Venha e apague meus pecados através da agonia!",
  ui_story_5084_50840602_47_dialog_content = "Uma vida de sofrimento em troca de sua redenção!",
  ui_story_5084_50840602_48_dialog_content = "(A este ritmo, Nails realmente vai morrer nas mãos deles! Vamos lá, castiçal... Leve-me onde eu possa fazer a diferença...!)",
  ui_story_5084_50840602_49_dialog_content = "Seu tolo!",
  ui_story_5084_50840602_50_dialog_content = "Isso não é um ritual, e eles não estão te ajudando a purificar sua alma! Você não consegue ver que eles estão tentando te matar?!",
  ui_story_5084_50840602_51_dialog_content = "Você se considera um asceta? Se sim, você deve sobreviver e dedicar o resto de sua vida à busca pela Verdade!",
  ui_story_5084_50840602_52_dialog_content = "Meu senhor?",
  ui_story_5084_50840602_53_dialog_content = "Viva, seu tolo!",
  ui_story_5084_50840602_54_dialog_content = "<color=#e8d9bb>Wilhelm agarra Nails e o arremessa com uma força surpreendente. Ele se choca contra as portas do templo, abrindo-as amplamente e permitindo que o vento negro entre.</color>",
  ui_story_5084_50840602_55_dialog_content = "Ah! A vela se apagou!",
  ui_story_5084_50840602_56_dialog_content = "Wilhelm Varaki não será forçado a se ajoelhar tão facilmente! Agora, o que mais você tem reservado para mim?!",
  ui_story_5084_50840602_57_dialog_content = "Vocês, demônios traiçoeiros, provarão da minha lâmina antes que a noite termine!",
  ui_story_5084_50840602_58_dialog_content = "Desperte, <color=#FF0000>Corrente Carmesim</color>! Minha lâmina demoníaca, que bebe do meu sangue em troca de abater meus inimigos!",
  ui_story_5084_50840602_59_dialog_content = "O que está acontecendo? Eles estão prestes a lutar...?",
  ui_story_5084_50840602_60_dialog_content = "Eu não sei! Eu não consigo ver nada!",
  ui_story_5084_50840602_61_dialog_content = "O mundo está começando a mudar ao nosso redor novamente, mas tenho que assistir isso até o fim! Não posso deixar... Ser teleportado para longe—",
  ui_story_5084_50840602_62_dialog_content = "Segure-se em mim e vá o mais longe que puder, May!",
  ui_story_5084_50840602_63_dialog_content = "Droga, não consigo ver nada aqui dentro.",
  ui_story_5084_50840602_64_dialog_content = "Mesmo assim, ele não vai durar muito mais sozinho.",
  ui_story_5084_50840602_65_dialog_content = "Ah!",
  ui_story_5084_50840602_66_dialog_content = "Qual de vocês é minha próxima vítima?",
  ui_story_5084_50840602_67_dialog_content = "Venha e fique ao meu lado, Clavis! Podemos derrotá-los juntos!",
  ui_story_5084_50840602_68_dialog_content = "...",
  ui_story_5084_50840602_69_dialog_content = "É inútil, Wilhelm. Mesmo que você corte minha cabeça, eu não vou morrer.",
  ui_story_5084_50840602_70_dialog_content = "Então vou continuar cortando você até que não possa mais suportar a dor!",
  ui_story_5084_50840602_71_dialog_content = "Incrível... Mesmo lutando contra tantas pessoas no escuro... Ele não está em desvantagem alguma.",
  ui_story_5084_50840602_72_dialog_content = "Patético... Você está mesmo tentando matá-lo?",
  ui_story_5084_50840602_73_dialog_content = "É mais fácil falar do que fazer...",
  ui_story_5084_50840602_74_dialog_content = "Ainda contando com os outros, Porfírio? Seu fim está próximo, e ninguém vai te salvar dele!",
  ui_story_5084_50840602_75_dialog_content = "Você se lembra do nosso acordo... Não se lembra?",
  ui_story_5084_50840602_76_dialog_content = "...",
  ui_story_5084_50840602_77_dialog_content = "<size=45>Ah—!!!</size>",
  ui_story_5084_50840602_78_dialog_content = "O que aconteceu? Eu não consigo mais sentir a respiração dele! Ele é...",
  ui_story_5084_50840602_79_dialog_content = "Continue aguentando! Estamos... Estamos prestes a ser teleportados para outro lugar!",
  ui_story_5084_50840602_80_dialog_content = "Por que... Por que tem que ser assim?",
  ui_story_5084_50840602_81_dialog_content = "(Se ele realmente morrer... O que vai acontecer com Victoria?)",
  ui_story_5084_50840602_82_dialog_content = "Ei, PlayerName? Lord Wilhelm não parece ser um assassino frio, não é? Você realmente acha que ele sacrificou a Senhora... Victoria...?",
  ui_story_5084_50840602_83_dialog_content = "Também tenho minhas dúvidas agora... Desde que o candelabro nos teleportou pela primeira vez, o Wilhelm que temos visto não é nada como o Wilhelm que vimos na cerimônia do Advento da Verdade...",
  ui_story_5084_50840602_84_dialog_content = "Minhas palavras realmente causaram todas essas mudanças...?",
  ui_story_5084_50840602_85_dialog_content = "Ou está acontecendo algo mais entre os Wilhelms que vimos...?",
  ui_story_5084_50840602_86_dialog_content = "Eu me pergunto onde a Senhora Victoria está agora...",
  ui_story_5084_50840602_87_dialog_content = "Durante a cerimônia, Victoria mencionou algo sobre Wilhelm ter desaparecido. Talvez ela esteja tentando encontrar as respostas por trás do desaparecimento dele?",
  ui_story_5084_50840602_88_dialog_content = "Algo me diz que essa cerimônia de sacrifício não é tão simples quanto parece... Se ela está disposta a revisitar tudo isso, deve significar que ela está procurando algo.",
  ui_story_5084_50840602_89_dialog_content = "Parece que ela e Wilhelm se entenderam mal por muito tempo... Eles ainda tinham mais a dizer um ao outro.",
  ui_story_5084_50840700_1_dialog_content = "Uau, olhe todas essas velas e flores, PlayerName! Espere... Isso é um caixão?!",
  ui_story_5084_50840700_2_dialog_content = "Acho que sim...",
  ui_story_5084_50840700_3_dialog_content = "Perguntando onde estamos agora?",
  ui_story_5084_50840700_4_dialog_content = "Está tão escuro e sombrio lá fora, também. Deixe-me dar uma olhada...",
  ui_story_5084_50840700_5_dialog_content = "Estamos em um antigo castelo com vista para um penhasco! Quem construiria sua casa em um lugar assim...?",
  ui_story_5084_50840700_6_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat—</color>",
  ui_story_5084_50840700_7_dialog_content = "Ah—É a Senhora Victoria!",
  ui_story_5084_50840700_8_dialog_content = "Mas como...? É porque eu estava pensando nela agora mesmo?",
  ui_story_5084_50840700_9_dialog_content = "Espere, tem mais alguém.",
  ui_story_5084_50840700_10_dialog_content = "Então você veio em busca de Wilhelm também?",
  ui_story_5084_50840700_11_dialog_content = "Além da família, parece que as únicas pessoas que vêm à sua casa são seus inimigos.",
  ui_story_5084_50840700_12_dialog_content = "Você sabe onde ele está?",
  ui_story_5084_50840700_13_dialog_content = "Infelizmente, eu não sei. Ele não deixou pistas sobre o paradeiro dele antes de desaparecer.",
  ui_story_5084_50840700_14_dialog_content = "Que pena. Eu pensei que ele teria pelo menos um ou dois confidentes de confiança.",
  ui_story_5084_50840700_15_dialog_content = "Sim, já estivemos tão perto.",
  ui_story_5084_50840700_16_dialog_content = "Se ao menos Wilhelm não tivesse sido tão imprudente... Poderia ter continuado assim.",
  ui_story_5084_50840700_17_dialog_content = "Você nunca entendeu muito bem o seu tio... Entendeu, Victoria?",
  ui_story_5084_50840700_18_dialog_content = "Não tenho interesse em conhecer pessoas como ele, muito menos entendê-las.",
  ui_story_5084_50840700_19_dialog_content = "Antes do seu pai se tornar líder da True Order, seu tio Wilhelm cobiçava o cargo mais do que qualquer outra coisa.",
  ui_story_5084_50840700_20_dialog_content = "Cego pela perspectiva de fortuna e glória, ele perseguiu fervorosamente as crenças mais radicais e as proclamou como A Verdade.",
  ui_story_5084_50840700_21_dialog_content = "Por causa disso, ele perdeu o controle repetidamente sempre que tentava herdar o poder de nossos ancestrais... Embora já fosse visto como um pária, ele se recusou a aceitar a derrota.",
  ui_story_5084_50840700_22_dialog_content = "Essa recusa, por sua vez, fez dele o fantoche das ambições de outro, o que resultou em sua expulsão da família.",
  ui_story_5084_50840700_23_dialog_content = "... Eu não me importo em aprender a história dele.",
  ui_story_5084_50840700_24_dialog_content = "Na verdade, estou bastante satisfeito por estar livre do controle dele.",
  ui_story_5084_50840700_25_dialog_content = "Durante minhas viagens, o Senhor da Verdade revelou algo para mim... É por isso que vim para dizer adeus.",
  ui_story_5084_50840700_26_dialog_content = "Estou partindo para o lugar que me foi mostrado, onde aguardarei a gloriosa chegada do Senhor da Verdade.",
  ui_story_5084_50840700_27_dialog_content = "Você é o sucessor da linhagem Varaki. Você está livre para tomar qualquer decisão como achar melhor.",
  ui_story_5084_50840700_28_dialog_content = "Mas antes de eu ir, posso perguntar sobre algo? Naquele dia, quando visitamos sua casa... O que era que Wilhelm queria pegar emprestado de você?",
  ui_story_5084_50840700_29_dialog_content = "That <color=#FFB400>key</color> will only bring you harm.",
  ui_story_5084_50840700_30_dialog_content = "Just before he died, my brother took it back from the <color=#FFB400>Vinekeepers</color> and gave it to you... Clearly, it was to ensure that the key would make it into my hands someday.",
  ui_story_5084_50840700_31_dialog_content = "... Or perhaps it was to prevent you from forcibly taking it from the <color=#FFB400>Vinekeepers</color> yourself.",
  ui_story_5084_50840700_32_dialog_content = "...! É a chave para todas as portas... Mas aqueles que queimam com ambição só serão consumidos por ela.",
  ui_story_5084_50840700_33_dialog_content = "... Cuide-se, Victoria Varaki. Você carrega um grande e pesado fardo, e o caminho para a Verdade é longo e árduo.",
  ui_story_5084_50840700_34_dialog_content = "<color=#e8d9bb>Victoria observa enquanto Clavis se despede. Uma vez que ele está fora de vista, ela se vira e entra no quarto de Wilhelm.</color>",
  ui_story_5084_50840700_35_dialog_content = "Pra onde você foi, cara incompreensível?",
  ui_story_5084_50840700_36_dialog_content = "<color=#e8d9bb>Ela olha ao redor do quarto antes de finalmente abrir o opulento caixão de Wilhelm e deitar-se dentro dele.</color>",
  ui_story_5084_50840700_37_dialog_content = "Se eu ver as coisas como meus pais uma vez viram... Serei capaz de entender suas ambições?",
  ui_story_5084_50840700_38_dialog_content = "(Essa sensação... Ela está tentando lembrar de algo...)",
  ui_story_5084_50840700_39_dialog_content = "Estamos reunidos aqui hoje para honrar os chefes da Família Varaki enquanto depositamos seus corpos para descansar.",
  ui_story_5084_50840700_40_dialog_content = "Ao seguir os passos de nossos nobres ancestrais, eles são sobrevividos por sua amada filha—Victoria Varaki.",
  ui_story_5084_50840700_41_dialog_content = "Venha, criança; coloque este anel no túmulo de seu pai com suas próprias mãos. Era um símbolo de sua honra e deve ser tratado como tal neste momento.",
  ui_story_5084_50840700_42_dialog_content = "Pai... Mãe...",
  ui_story_5084_50840700_43_dialog_content = "Tome seu tempo, minha querida. Entendemos que você ainda está sobrecarregada de tristeza e confusão.",
  ui_story_5084_50840700_44_dialog_content = "Mas não tema, minha senhora, pois ficaremos ao seu lado enquanto você navega por esta hora mais sombria - Ah, mas onde estão meus modos? Meu nome é David Porfirio.",
  ui_story_5084_50840700_45_dialog_content = "Seu pai uma vez me ajudou a domar o caos dentro do meu sangue, e restaurou minha preciosa sanidade.",
  ui_story_5084_50840700_46_dialog_content = "E eu sou Clavis Ibrahim. Nunca esqueci a gentileza que a Família Varaki me mostrou.",
  ui_story_5084_50840700_47_dialog_content = "Se algum dia precisar de ajuda com qualquer coisa, é só pedir.",
  ui_story_5084_50840700_48_dialog_content = "Senhora Varaki... Você não precisa saber meu nome. Sou apenas um humilde servo, então, por favor, dirija-se a mim dessa maneira.",
  ui_story_5084_50840700_49_dialog_content = "Meu pai... Como ele te chamou?",
  ui_story_5084_50840700_50_dialog_content = "Graves, minha dama...",
  ui_story_5084_50840700_51_dialog_content = "A passagem do tempo pode ser cruel, tanto que quase esqueci meu nome... Todos se referem a mim como <color=#FFB400>Adder</color>, então sinta-se à vontade para fazer o mesmo.",
  ui_story_5084_50840700_52_dialog_content = "O ritual acabou, e os líderes da Família Varaki foram agora postos para descansar. Agora chegou a hora de discutirmos o futuro.",
  ui_story_5084_50840700_53_dialog_content = "Você ainda é muito jovem, Senhora Victoria. Receio que você ainda não esteja pronta para suportar o poder deste anel.",
  ui_story_5084_50840700_54_dialog_content = "Eu vou assistir com prazer em seu lugar—Não tenha medo, pois não é nada mais do que um anel normal nas mãos de alguém que não pertence aos Varaki.",
  ui_story_5084_50840700_55_dialog_content = "É mesmo? Então por que você insiste em guardar isso para si mesmo, Porfírio?",
  ui_story_5084_50840700_56_dialog_content = "Wilhelm Varaki?!",
  ui_story_5084_50840700_57_dialog_content = "Hmph, não se esqueça que ainda vive outro membro dos Varaki, e que apenas um Varaki pode assumir a liderança da Verdadeira Ordem.",
  ui_story_5084_50840700_58_dialog_content = "...",
  ui_story_5084_50840700_59_dialog_content = "Como ousa falar tamanha loucura diante da Senhora Victoria! Você esqueceu que foi banido da Família Varaki?!",
  ui_story_5084_50840700_60_dialog_content = "Hah! Testemunhe enquanto herdo a sabedoria e o poder de nossos ancestrais!",
  ui_story_5084_50840700_61_dialog_content = "Ugh...",
  ui_story_5084_50840700_62_dialog_content = "Hahahaha! Por que a cara de decepção, Porfírio? A perspectiva de ver outro Varaki usando esse anel te atormenta tanto?",
  ui_story_5084_50840700_63_dialog_content = "Contemplem! Eu, Wilhelm Varaki, agora me ergo acima de todos vocês!",
  ui_story_5084_50840700_64_dialog_content = "Nosso ancestral me considerou digno de me tornar o novo chefe da Família Varaki!",
  ui_story_5084_50840700_65_dialog_content = "Wilhelm... Parece que suas ambições não foram extintas.",
  ui_story_5084_50840700_66_dialog_content = "Eh... Hahahaha! Querido Victoria, parece que seu tio não está disposto a conceder-lhe o que é legitimamente seu.",
  ui_story_5084_50840700_67_dialog_content = "Não temos o direito de interferir nos assuntos de Varaki. Vamos nos retirar.",
  ui_story_5084_50840700_68_dialog_content = "Wilhelm Varaki... Meu tio...",
  ui_story_5084_50840700_69_dialog_content = "Onde você deseja ir?",
  ui_story_5084_50840700_70_dialog_content = "Naturalmente, desejo deixar esta cidade e ir para o lugar que herdei por direito.",
  ui_story_5084_50840700_71_dialog_content = "Victoria Varaki... A partir deste dia, servirei como seu guardião. Enquanto eu for o chefe da família, você deve fazer exatamente como eu digo.",
  ui_story_5084_50840700_72_dialog_content = "... Esse anel pertencia ao meu pai, o que significa que agora deveria ser meu. Quando A Verdade falar comigo e despertar meu poder, eu o pegarei de volta.",
  ui_story_5084_50840700_73_dialog_content = "Como desejar. Mas por agora, fica em minhas mãos.",
  ui_story_5084_50840700_74_dialog_content = "The honor of hearing The Truth... I dearly wish to hear the thoughts of one as precocious as you, Victoria Varaki. What, in your definition, is The Truth?",
  ui_story_5084_50840700_75_dialog_content = "The Truth... is knowledge.",
  ui_story_5084_50840700_76_dialog_content = "Humph, Victoria Varaki... Though we share the same bloodline, in terms of strength, wisdom, capability, and even beauty... I stand far above you.",
  ui_story_5084_50840700_77_dialog_content = "So what makes you think this ring is rightfully yours?",
  ui_story_5084_50840700_78_dialog_content = "I am a true Varaki, and the leader of the True Order!",
  ui_story_5084_50840700_79_dialog_content = "As for you... You must first demonstrate that you are worthy of our family name. Do not disappoint me.",
  ui_story_5084_50840700_80_dialog_content = "(Wilhelm está dizendo coisas tão horríveis, e para uma criança que acabou de perder os pais, ainda por cima... Ele não está falando sério, está?)",
  ui_story_5084_50840700_81_dialog_content = "(De novo, aquela criança ainda é Victoria... É tão estranho! O Wilhelm que temos visto não é quase isso...)",
  ui_story_5084_50840700_82_dialog_content = "<color=#e8d9bb>Um raio rasga o céu lá fora enquanto a jovem Victoria abre o caixão de seus pais e rasteja para dentro.</color>",
  ui_story_5084_50840700_83_dialog_content = "Father... Mother...",
  ui_story_5084_50840700_84_dialog_content = "Dê-me sua orientação... Diga-me o que fazer...",
  ui_story_5084_50840700_85_dialog_content = "Estou... Em casa? Mas como?",
  ui_story_5084_50840700_86_dialog_content = "<color=#e8d9bb>Farfalhar, farfalhar—</color>",
  ui_story_5084_50840700_87_dialog_content = "Quem se atreve a invadir a casa dos Varaki—",
  ui_story_5084_50840700_88_dialog_content = "... O que você está fazendo aqui? E onde estão meus servos?",
  ui_story_5084_50840700_89_dialog_content = "Desaparecido. A partir deste momento, o tempo será nosso servo eterno.",
  ui_story_5084_50840700_90_dialog_content = "<color=#e8d9bb>Wilhelm Varaki, o cara que havia invadido repentinamente a casa de Victoria, estava lá para ficar e cuidar dela como seu tio.</color>",
  ui_story_5084_50840700_91_dialog_content = "Minha querida Victoria, sua situação pesa muito em nossos corações, e realmente, pesa... Mas somos impotentes para mudá-la. Por favor, nos perdoe, criança.",
  ui_story_5084_50840700_92_dialog_content = "Enquanto Wilhelm for o chefe dos Varaki, devemos obedecê-lo. Na verdade, ele é quem nos mantém à distância...",
  ui_story_5084_50840700_93_dialog_content = "Esperando que nada estivesse errado, corri para cá o mais rápido que pude... Estou aliviado em ver que você realmente está bem.",
  ui_story_5084_50840700_94_dialog_content = "Ele só está sendo cauteloso comigo. Ele teme que eu conspire com você e os outros para destroná-lo.",
  ui_story_5084_50840700_95_dialog_content = "Sim, isso é o que Wilhelm teme... Pois ele sabe que seu pai era um líder muito mais capaz. Ele não é nada mais do que um excluído e um oportunista.",
  ui_story_5084_50840700_96_dialog_content = "Senhora Victoria, eu preciso perguntar... Seus talentos devem ser tão impressionantes quanto os do seu pai. Diga-me, você conseguiu ressoar com o vaso sagrado do ancestral?",
  ui_story_5084_50840700_97_dialog_content = "Se sim, como foi a sensação?",
  ui_story_5084_50840700_98_dialog_content = "Parecia que... Alguém havia entrado em minha mente para me contar sobre o néctar que uma vez continha.",
  ui_story_5084_50840700_99_dialog_content = "Algumas de suas histórias foram contadas em silêncio, como se quisessem dizer...",
  ui_story_5084_50840700_100_dialog_content = "Porfírio! Quem te concedeu entrada em meu domínio?!",
  ui_story_5084_50840700_101_dialog_content = "Heheh, eu só vim ver como a Senhora Victoria está se saindo, Wilhelm. Vou me despedir agora.",
  ui_story_5084_50840700_102_dialog_content = "Ela está se saindo perfeitamente bem. Se você estava esperando sangue fresco, sugiro que descarte esse pensamento imediatamente.",
  ui_story_5084_50840700_103_dialog_content = "Não influencie as ações dela com suas ambições selvagens!",
  ui_story_5084_50840700_104_dialog_content = "Sou livre para falar com quem eu quiser, Wilhelm.",
  ui_story_5084_50840700_105_dialog_content = "Você ainda é muito ingênuo, Victoria. Você não vai aprender sobre o mundo se imergindo em textos antigos; você só vai se distanciar dele.",
  ui_story_5084_50840700_106_dialog_content = "Você sabe sobre a Bíblia Sangrenta que repousa no túmulo de nossos ancestrais, sim? A sabedoria que ela proporciona nunca pode ser encontrada nas páginas de nenhum outro livro.",
  ui_story_5084_50840700_107_dialog_content = "Desde que seus pais foram sepultados, você nunca visitou a cripta.",
  ui_story_5084_50840700_108_dialog_content = "Mas isso não importa. Não te culpo por detestar a True Order, mas suas emoções não são motivo suficiente para isso.",
  ui_story_5084_50840700_109_dialog_content = "Caso contrário, isso não te faz melhor do que uma criança petulante.",
  ui_story_5084_50840700_110_dialog_content = "Tive que me tornar mais forte, para que ninguém pudesse nunca mais me controlar.",
  ui_story_5084_50840700_111_dialog_content = "Para esse fim, busquei A Verdade tentando ressoar com várias relíquias através de rituais antigos...",
  ui_story_5084_50840700_112_dialog_content = "Onde está? Onde poderia estar aquele texto antigo...?",
  ui_story_5084_50840700_113_dialog_content = "O Senhor da Verdade apareceu para mim em meu sonho, me convocando para encontrar seu texto sagrado antes que Wilhelm Varaki percebesse que eu estava desaparecido...",
  ui_story_5084_50840700_114_dialog_content = "Ah!",
  ui_story_5084_50840700_115_dialog_content = "<color=#FFB400>As estrelas</color>... Está devorando as <color=#FFB400>estrelas</color>... Não há tempo! Não há tempo algum... Um <color=#FFB400>novo começo</color> está à mão...",
  ui_story_5084_50840700_116_dialog_content = "<size=45>O verdadeiro final está dentro dessa escuridão—!</size>",
  ui_story_5084_50840700_117_dialog_content = "Solte isso imediatamente, seu idiota! Como ousa tentar ressoar com essa relíquia ancestral!",
  ui_story_5084_50840700_118_dialog_content = "A sabedoria dos tempos antigos, as revelações de um louco - eu, Wilhelm Varaki, ordeno que você fique longe dela!",
  ui_story_5084_50840700_119_dialog_content = "... Ah!",
  ui_story_5084_50840700_120_dialog_content = "... Retorne ao seu sono eterno.",
  ui_story_5084_50840700_121_dialog_content = "V-Você me salvou? Mas como você sabia que eu estava...",
  ui_story_5084_50840700_122_dialog_content = "Aprenda a distinguir as características de diferentes relíquias, ou então seu cadáver será a única coisa que eu recuperarei na próxima vez.",
  ui_story_5084_50840700_123_dialog_content = "E não interprete mal as minhas intenções. Como líder da Verdadeira Ordem, a última coisa que preciso é que os fiéis me acusem de prejudicar a filha do meu falecido irmão.",
  ui_story_5084_50840700_124_dialog_content = "Manter você vivo apenas ajuda a garantir a estabilidade da minha posição.",
  ui_story_5084_50840700_125_dialog_content = "Além disso, em vez de salvar alguém à beira da morte, a família do sangue prefere drenar até a última gota de sangue do corpo deles.",
  ui_story_5084_50840700_126_dialog_content = "Wilhelm Varaki...!",
  ui_story_5084_50840700_127_dialog_content = "Esse homem arrogante, presunçoso, desprezível... Ele tirou minha vida e liberdade, e suas razões para fazer isso são sempre tão estranhas.",
  ui_story_5084_50840700_128_dialog_content = "Mas, comparado ao meu detestável tio, os outros mal eram melhores.",
  ui_story_5084_50840700_129_dialog_content = "Os chefes das famílias eram tolos de coração negro, cada um deles. As pessoas que eles lideravam eram como larvas ou cadáveres reanimados, cambaleando pela cidade sem propósito nem consciência.",
  ui_story_5084_50840700_130_dialog_content = "Os sermões deles exalavam maldade e tolice, e não ofereciam orientação para os fiéis da Verdade. Tais pessoas não são aptas para guiar os perdidos.",
  ui_story_5084_50840700_131_dialog_content = "Tive que ficar atento a eles... Não podia me deixar cair presa das tendências nefastas da True Order.",
  ui_story_5084_50840700_132_dialog_content = "Para acatar a vontade do Senhor da Verdade e resolver o \"final\" que me foi mostrado.",
  ui_story_5084_50840700_133_dialog_content = "Você tem se trancado em casa recentemente. Você finalmente perdeu o interesse nas relíquias?",
  ui_story_5084_50840700_134_dialog_content = "Quando tínhamos a sua idade, seu pai e eu já havíamos despertado há muito tempo o poder de nossa linhagem, e nossos corações eram insaciáveis pela sabedoria da Verdade.",
  ui_story_5084_50840700_135_dialog_content = "Será que você ainda é tão ignorante quanto antes? Você ainda é incapaz de responder à minha pergunta sobre a Verdade?",
  ui_story_5084_50840700_136_dialog_content = "... Decidi viajar o mundo em busca da Verdade.",
  ui_story_5084_50840700_137_dialog_content = "Faça como quiser.",
  ui_story_5084_50840700_138_dialog_content = "E assim comecei minha jornada, e busquei a orientação da Verdade para mim mesmo.",
  ui_story_5084_50840700_139_dialog_content = "No momento em que coloquei o pé fora de minha casa, comecei a adquirir um conhecimento mais profundo do mundo.",
  ui_story_5084_50840700_140_dialog_content = "E à medida que fortaleci minha compreensão da Verdade, o poder da minha linhagem começou a despertar gradualmente... Mesmo assim, recusei-me a me juntar à True Order.",
  ui_story_5084_50840700_141_dialog_content = "Quando finalmente encontrei a resposta que ele havia pedido, voltei para a cidade de Varaki para contar a ele... Apenas para descobrir que ele não esperava mais isso de mim.",
  ui_story_5084_50840700_142_dialog_content = "Welcome back... You were gone for three months this time. How did you fare?",
  ui_story_5084_50840700_143_dialog_content = "... That's none of your concern.",
  ui_story_5084_50840700_144_dialog_content = "The look in your eyes... So full of resentment and uncertainty...",
  ui_story_5084_50840700_145_dialog_content = "What did you see in the outside world, Wilhelm Varaki?",
  ui_story_5084_50840700_146_dialog_content = "I don't recall letting you enter my room.",
  ui_story_5084_50840700_147_dialog_content = "You're the leader of the True Order, and yet you regularly leave without fulfilling your duties... You've been spending less time at home, as well.",
  ui_story_5084_50840700_148_dialog_content = "How many times must I tell you that it's none of your concern?! Now leave me!",
  ui_story_5084_50840700_149_dialog_content = "Very well then; I am no stranger to being denied your conversation. But given that tonight is the Advent of Truth, I was hoping we could have one final discussion.",
  ui_story_5084_50840700_150_dialog_content = "About The Truth, and ourselves...",
  ui_story_5084_50840700_151_dialog_content = "I said get out! Do not make me repeat myself!",
  ui_story_5084_50840700_152_dialog_content = "...",
  ui_story_5084_50840700_153_dialog_content = "Para esta estadia, eu ainda não entendo ele.",
  ui_story_5084_50840700_154_dialog_content = "Temo que também perdi minha última chance de fazer isso.",
  ui_story_5084_50840700_155_dialog_content = "Wilhelm Varaki: meu tio arrogante, desprezível e inescrutável, bem como meu último parente vivo... Onde você foi?",
  ui_story_5084_50840700_156_dialog_content = "(Então é assim que Victoria vê Wilhelm em suas memórias...)",
  ui_story_5084_50840700_157_dialog_content = "(Mas do ponto de vista de Wilhelm, ele sempre cuidou dela...)",
  ui_story_5084_50840700_158_dialog_content = "(Ele sofreu perdendo o controle sozinho e recusou-se a beber o sangue dos fiéis como o resto dos chefes de famílias. Ele pensava nos outros até o fim e até conseguiu salvar Nails...)",
  ui_story_5084_50840700_159_dialog_content = "(Por tantos anos... Eles nunca conseguiram se entender... Mesmo quando Wilhelm foi atacado...)",
  ui_story_5084_50840700_160_dialog_content = "(Eu me pergunto se Victoria consegue ver o que eu vi...)",
  ui_story_5084_50840801_1_dialog_content = "A vela está começando a cintilar novamente—Para onde vai nos levar desta vez?",
  ui_story_5084_50840801_2_dialog_content = "É Victoria... E o resto dos chefes de famílias. O que todos eles estão fazendo aqui?",
  ui_story_5084_50840801_3_dialog_content = "Hã? É aquele Faust parado ao lado dela? E acho que ele está olhando para nós!",
  ui_story_5084_50840801_4_dialog_content = "Isso poderia ser...?",
  ui_story_5084_50840801_5_option_content = "Mindlink",
  ui_story_5084_50840801_6_dialog_content = "Faust! Você consegue ouvir minha voz?",
  ui_story_5084_50840801_7_dialog_content = "Claro, e estou plenamente ciente das suas dúvidas atuais.",
  ui_story_5084_50840801_8_dialog_content = "A pessoa que você vê aqui é a Senhora Victoria, a qual você está tão bem familiarizado.",
  ui_story_5084_50840801_9_dialog_content = "Mas se é a Victoria do nosso tempo... Por que ela está de pé na frente dessas pessoas...?",
  ui_story_5084_50840801_10_dialog_content = "Wilhelm está desaparecido há três anos. Os únicos descendentes restantes dos Varaki são o filho de Ibrahim e Victoria, a sobrinha de Wilhelm.",
  ui_story_5084_50840801_11_dialog_content = "(Três anos... Wilhelm foi atacado em 1915, o que significa que deveríamos estar no ano de 1918 agora, certo?)",
  ui_story_5084_50840801_12_dialog_content = "No entanto, Clavis Ibrahim não está disposto a permitir que sua criança entre na True Order, o que significa que ele não tem direito à sua liderança.",
  ui_story_5084_50840801_13_dialog_content = "Como está, a posição ainda está vaga e o anel da família não foi encontrado. Suspeitamos que ele desapareceu junto com Wilhelm Varaki.",
  ui_story_5084_50840801_14_dialog_content = "E já que Victoria não tem mais o privilégio de herdar a sabedoria de nossos ancestrais...",
  ui_story_5084_50840801_15_dialog_content = "Oh? Todos vocês se reuniram aqui hoje simplesmente para me dizer isso?",
  ui_story_5084_50840801_16_dialog_content = "Fui informado que você prefere buscar a Verdade viajando pelo mundo exterior. Respeitamos sua escolha.",
  ui_story_5084_50840801_17_dialog_content = "Você é livre para deixar este lugar, ou ficar e se tornar parte da Família Porfirio. De qualquer forma, você não está mais qualificado para liderar a True Order.",
  ui_story_5084_50840801_18_dialog_content = "Com o Advento da Verdade acontecendo esta noite, a liderança da Verdadeira Ordem deve cair para...",
  ui_story_5084_50840801_19_dialog_content = "Os encontros da Ordem realmente se tornaram tão solitários e depravados na ausência de Wilhelm?",
  ui_story_5084_50840801_20_dialog_content = "Até mesmo as famílias de sangue devem pagar um alto preço por beber sangue que não é destinado ao consumo.",
  ui_story_5084_50840801_21_dialog_content = "<color=#e8d9bb>Victoria derrama um copo de vinho vermelho-sangue na mesa à sua frente. No fundo do copo jaz o anel que Wilhelm usava.</color>",
  ui_story_5084_50840801_22_dialog_content = "...?",
  ui_story_5084_50840801_23_dialog_content = "... o anel de Wilhelm.",
  ui_story_5084_50840801_24_dialog_content = "Ele me confiou isso pouco antes de deixar este lugar. As palavras de nossos ancestrais há muito tempo guiam meus passos.",
  ui_story_5084_50840801_25_dialog_content = "Agora me diga, o que mais você tem a dizer sobre a liderança da True Order?",
  ui_story_5084_50840801_26_dialog_content = "Impossível!",
  ui_story_5084_50840801_27_dialog_content = "O plano deve ser alterado...",
  ui_story_5084_50840801_28_dialog_content = "Parece que cada um de vocês está a par de algum tipo de esquema.",
  ui_story_5084_50840801_29_dialog_content = "Este é o conhecimento que foi revelado para mim durante o Advento da Verdade três anos atrás.",
  ui_story_5084_50840801_30_dialog_content = "Três anos atrás...",
  ui_story_5084_50840801_31_dialog_content = "Não, isso não pode ser!",
  ui_story_5084_50840801_32_dialog_content = "Still counting on others, Porfirio? Your end is near, and no one will save you from it!",
  ui_story_5084_50840801_33_dialog_content = "You remember our deal... Don't you?",
  ui_story_5084_50840801_34_dialog_content = "...",
  ui_story_5084_50840801_35_dialog_content = "<size=45>Ah—!!!</size>",
  ui_story_5084_50840801_36_dialog_content = "Condenado a uma morte vergonhosa em sua própria cidade natal... Como eu tenho pena de você, Wilhelm Varaki.",
  ui_story_5084_50840801_37_dialog_content = "...",
  ui_story_5084_50840801_38_dialog_content = "E sem descendentes para mencionar, o anel dos Varaki perdeu todo o significado.",
  ui_story_5084_50840801_39_dialog_content = "O que você fez? Ao esmagar o anel, você...",
  ui_story_5084_50840801_40_dialog_content = "É inútil para você ou para mim agora. Deixe os destroços descansarem em paz com Wilhelm.",
  ui_story_5084_50840801_41_dialog_content = "A partir deste dia, não pode ser usado para nos ameaçar nunca mais.",
  ui_story_5084_50840801_42_dialog_content = "A algema que são os chefes de Varaki está no passado!",
  ui_story_5084_50840801_43_dialog_content = "Aquele anel... Ele deveria ter sido queimado até virar cinzas, junto com Wilhelm...",
  ui_story_5084_50840801_44_dialog_content = "Parece que você descobriu a verdade.",
  ui_story_5084_50840801_45_dialog_content = "Oh? Era para permanecer em segredo?",
  ui_story_5084_50840801_46_dialog_content = "... Mas você realmente usou? Ele realmente lhe transmitiu sua sabedoria?",
  ui_story_5084_50840801_47_dialog_content = "A menos que seja considerado digno pelos nossos antepassados, você nunca terá sucesso Wilhelm!",
  ui_story_5084_50840801_48_dialog_content = "Fui batizado com o nome Varaki pelos nossos antepassados, e este anel há muito perdido é um símbolo da aprovação deles. Agora vou colocá-lo para todos verem.",
  ui_story_5084_50840801_49_dialog_content = "PlayerName Esse anel vai fazer a Senhora Victoria perder o controle!",
  ui_story_5084_50840801_50_dialog_content = "Não se preocupe May, estou começando a perceber lentamente por que estou aqui agora. Eu sei exatamente o que fazer!",
  ui_story_5084_50840801_51_option_content = "Mindlink—",
  ui_story_5084_50840801_52_dialog_content = "Ah... De novo não...",
  ui_story_5084_50840801_53_dialog_content = "As vozes... As revelações antigas...",
  ui_story_5084_50840801_54_dialog_content = "Não se preocupe Victoria, eu vou te ajudar a suprimi-los!",
  ui_story_5084_50840801_55_dialog_content = "? Entendo... Isso deve ser a vontade do Senhor da Verdade. Nesse caso, deixo com você.",
  ui_story_5084_50840801_56_dialog_content = "Ela está vestindo... Ela realmente está vestindo...",
  ui_story_5084_50840801_57_dialog_content = "Por que todos vocês estavam tão preocupados? Um verdadeiro Varaki não deveria ter problema em suportar as vozes de nossos ancestrais, afinal de contas.",
  ui_story_5084_50840801_58_dialog_content = "Hehe... Hahahaha—",
  ui_story_5084_50840801_59_dialog_content = "Essa risada...",
  ui_story_5084_50840801_60_dialog_content = "Behold! I, Wilhelm Varaki, now tower over all of you!",
  ui_story_5084_50840801_61_dialog_content = "Our ancestor has deemed me worthy of becoming the new head of the Varaki Family!",
  ui_story_5084_50840801_62_dialog_content = "Varaki...!",
  ui_story_5084_50840801_63_dialog_content = "Eis o sucessor da Família Varaki!",
  ui_story_5084_50840802_1_dialog_content = "Vou limpar o mundo da sua existência!",
  ui_story_5084_50840802_2_dialog_content = "O que estou vendo...?",
  ui_story_5084_50840802_3_dialog_content = "Eu fiz o meu melhor para manter as vozes à distância, mas essas visões ainda conseguiram escapar do anel.",
  ui_story_5084_50840802_4_dialog_content = "Eles não parecem estar conectados às vozes, no entanto. Se for o caso, acho que eles estão vindo de um nível ainda mais alto de consciência.",
  ui_story_5084_50840802_5_dialog_content = "Eles não parecem ser perigosos. Permita-me vê-los.",
  ui_story_5084_50840802_6_dialog_content = "<size=45>Ah—!!!</size>",
  ui_story_5084_50840802_7_dialog_content = "Seu sangue e a autoridade que ele concede são meus agora, Wilhelm Varaki!",
  ui_story_5084_50840802_8_dialog_content = "Você servirá como minha <color=#FFB400>chave</color> e desbloqueará a sabedoria de nossos ancestrais para mim! Hahahaha!",
  ui_story_5084_50840802_9_dialog_content = "Wilhelm Varaki... Ele...!",
  ui_story_5084_50840802_10_dialog_content = "Wilhelm... Quando você me contou sobre seus planos de partir, presumi que havia encontrado um refúgio seguro para Victoria e para você mesmo.",
  ui_story_5084_50840802_11_dialog_content = "Então por que... Por que você voltou para este lugar, seu tolo...",
  ui_story_5084_50840802_12_dialog_content = "Heheh... Embora eu suponha que também sou um tolo por acreditar tão facilmente naquele <color=#FFB400>cara</color>.",
  ui_story_5084_50840802_13_dialog_content = "Antepassados, eu imploro que aceitem Wilhelm Varaki em seu meio. Apesar da ambição impura que ardia em suas veias, ele mais do que honrou o nobre nome dos Varaki.",
  ui_story_5084_50840802_14_dialog_content = "Agora que ele foi traído por um pecador como eu, absolve-o de seus crimes e transfira-os para mim.",
  ui_story_5084_50840802_15_dialog_content = "Embora minha alma logo seja amaldiçoada, eu humildemente rezo para que minha esposa e Charon encontrem uma maneira de deixar este lugar...",
  ui_story_5084_50840802_16_dialog_content = "Wilhelm Varaki, meu antigo amigo... May você encontra a paz eterna neste caixão.",
  ui_story_5084_50840802_17_dialog_content = "Ele... Realmente morreu? Wilhelm Varaki... Ele esteve morto todo esse tempo...",
  ui_story_5084_50840802_18_dialog_content = "É esta a verdade que o anel deseja me mostrar?",
  ui_story_5084_50840802_19_dialog_content = "O cara que me deu isso há três anos atrás... Ele realmente se foi?",
  ui_story_5084_50840802_20_dialog_content = "... O que você vai fazer agora?",
  ui_story_5084_50840802_21_dialog_content = "Posso sentir que estou me aproximando cada vez mais da Verdade.",
  ui_story_5084_50840802_22_dialog_content = "Como o atual líder da True Order, pensei que o Senhor da Verdade me guiou até aqui para simplesmente testemunhar este momento mais uma vez.",
  ui_story_5084_50840802_23_dialog_content = "Mas a sua presença e o sacrifício anterior mostraram-me que eu devo participar. Além da bênção do meu senhor, também carrego um ódio inegável no meu coração.",
  ui_story_5084_50840802_24_dialog_content = "Isso é algo que só eu posso fazer, e apenas com controle suficiente sobre meu poder e mente.",
  ui_story_5084_50840802_25_dialog_content = "Bendito seja o Senhor da Verdade por dissipar minhas dúvidas e conceder-me o prazer da retribuição.",
  ui_story_5084_50840802_26_dialog_content = "Esta noite é o Advento da Verdade. Nosso ressentimento surgiu de nossa sede pela sabedoria de nossos antepassados; deixe-os assistir enquanto colocamos um fim em tudo.",
  ui_story_5084_50840802_27_dialog_content = "Pessoas da Cidade Varaki, por favor me perdoem por tê-los deixado esperando.",
  ui_story_5084_50840802_28_dialog_content = "Após receber orientação do Senhor da Verdade, agora entendo meu propósito.",
  ui_story_5084_50840802_29_dialog_content = "Esse anel não te causa uma dor imensa?",
  ui_story_5084_50840802_30_dialog_content = "Até mesmo Wilhelm não conseguiu vesti-lo tão facilmente.",
  ui_story_5084_50840802_31_dialog_content = "Que revelação você recebeu?",
  ui_story_5084_50840802_32_dialog_content = "<color=#e8d9bb>Victoria se levanta e caminha até a cabeceira da mesa.</color>",
  ui_story_5084_50840802_33_dialog_content = "<color=#FF0000>Para purgar a ordem.</color>",
  ui_story_5084_50840802_34_dialog_content = "O quê?!",
  ui_story_5084_50840802_35_dialog_content = "<color=#e8d9bb>Um vento negro irrompe no templo, sacudindo violentamente suas portas e janelas. Empunhando um poder muito além de seu tempo, a sucessora dos Varaki parece emitir um ultimato aos chefes das casas.</color>",
  ui_story_5084_50840802_36_dialog_content = "<color=#e8d9bb>Esmagar—</color>",
  ui_story_5084_50840802_37_dialog_content = "Derrubar seu copo de surpresa? Que vergonha.",
  ui_story_5084_50840802_38_dialog_content = "...",
  ui_story_5084_50840802_39_dialog_content = "Esse anel... Me diga o que ele te mostrou!",
  ui_story_5084_50840802_40_dialog_content = "Pare, David! Você esqueceu que estamos no Templo da Verdade?!",
  ui_story_5084_50840802_41_dialog_content = "...!",
  ui_story_5084_50840802_42_dialog_content = "Como tudo começou com o festival de nossos ancestrais, é apropriado que tudo deva terminar esta noite.",
  ui_story_5084_50840802_43_dialog_content = "Agora, se me dá licença, como o novo líder dos Varaki, devo me preparar para o Advento da Verdade.",
  ui_story_5084_50840802_44_dialog_content = "Quando a lua de sangue paira no céu e os corredores do templo ressoam com o som dos sinos, devemos nos reunir mais uma vez para testemunhar o fim desta longa noite.",
  ui_story_5084_50840900_1_dialog_content = "<color=#e8d9bb>Na luz fraca da lanterna, David Porfirio está em uma poça de sangue. Além de seus seguidores enlouquecidos, a única outra pessoa na sala é Clavis Ibrahim, cujo corpo foi torturado além do reconhecimento.</color>",
  ui_story_5084_50840900_2_dialog_content = "Diga-me... Wilhelm ainda está vivo?!",
  ui_story_5084_50840900_3_dialog_content = "Fale... Agora...!",
  ui_story_5084_50840900_4_dialog_content = "Já te contei tudo o que sei... Não adianta mais me torturar...",
  ui_story_5084_50840900_5_dialog_content = "Coloquei seu corpo sem vida naquele caixão com minhas próprias mãos... Não havia como negar sua morte...",
  ui_story_5084_50840900_6_dialog_content = "Durante o Advento da Verdade três anos atrás, Wilhelm ajudou Victoria a escapar do caixão.",
  ui_story_5084_50840900_7_dialog_content = "Incapazes de suportar sua tirania por mais tempo, finalmente nos levantamos contra ele e destruímos o anel que nos unia.",
  ui_story_5084_50840900_8_dialog_content = "Então por que, após três anos, Victoria apareceu com o mesmo anel em suas mãos?!",
  ui_story_5084_50840900_9_dialog_content = "Aqueles dois devem estar tramando algo.",
  ui_story_5084_50840900_10_dialog_content = "A Bíblia Sangrenta não contém nenhum texto escrito. Ela não mostrará as palavras do divino que você busca tão desesperadamente.",
  ui_story_5084_50840900_11_dialog_content = "A garota Varaki, por outro lado, provou ser muito parecida com seu pai.",
  ui_story_5084_50840900_12_dialog_content = "Hehe... Hehehehe... Hahahaha—",
  ui_story_5084_50840900_13_dialog_content = "O que você acha tão divertido?",
  ui_story_5084_50840900_14_dialog_content = "Fomos tolos em nos acovardar com as ameaças de Wilhelm, e agora não nos resta escolha.",
  ui_story_5084_50840900_15_dialog_content = "Devíamos tê-lo matado e Victoria no dia em que os pais dela faleceram.",
  ui_story_5084_50840900_16_dialog_content = "Os poderes de Wilhelm ainda não estavam despertos naquela época, e Victoria mal era uma ameaça.",
  ui_story_5084_50840900_17_dialog_content = "Depois de se curvar aos Varaki por tanto tempo, parece que quase esquecemos... Que a chamada \"Verdade\" não é nada além dos resíduos de uma fé externa.",
  ui_story_5084_50840900_18_dialog_content = "De fato. Consumir sangue fresco e extrair poder dele é a única maneira de nosso povo sobreviver!",
  ui_story_5084_50840900_19_dialog_content = "Sem o nosso verdadeiro poder, fomos forçados a manter nossa fé no <color=#FFB400>Senhor da Verdade</color> através de afirmação, repetição, restrição e oração. Não é nada menos que heresia!",
  ui_story_5084_50840900_20_dialog_content = "Já é tarde demais agora, Porfírio... Com o poder do anel em suas mãos, ela está se preparando para nos destruir enquanto falamos.",
  ui_story_5084_50840900_21_dialog_content = "Não importa o quanto nos preparemos, temos menos de meio dia antes de todos nós...",
  ui_story_5084_50840900_22_dialog_content = "Silêncio! Wilhelm também usava esse anel no passado, e ainda conseguimos sangrá-lo até a última gota!",
  ui_story_5084_50840900_23_dialog_content = "O meu único arrependimento é que beber o sangue dele não me permitiu formar um pacto com a Bíblia Sangrenta. Para começar, parece que ele nunca foi o sucessor dos Varaki.",
  ui_story_5084_50840900_24_dialog_content = "Mas graças ao meu suprimento infinito de crentes, recuperei gradualmente meu poder... E agora finalmente posso ouvir o chamado suave da Bíblia Sangrenta!",
  ui_story_5084_50840900_25_dialog_content = "Só um pouco mais... E logo seu conhecimento se revelará para mim!",
  ui_story_5084_50840900_26_dialog_content = "Os Varaki são os culpados por suprimir nossa linhagem e nos impedir de alcançar a verdadeira superioridade!",
  ui_story_5084_50840900_27_dialog_content = "Nascemos para consumir o sangue dos vivos, mas os Varaki procuraram restringir nossas tendências naturais... Presumivelmente porque temiam nosso poder.",
  ui_story_5084_50840900_28_dialog_content = "O que você pretende fazer...?",
  ui_story_5084_50840900_29_dialog_content = "O mesmo que planejamos desde o início... Aparecerei diante dos fiéis durante o ritual desta noite e demonstrarei que a Bíblia Sangrenta me reconheceu.",
  ui_story_5084_50840900_30_dialog_content = "Sem força nem apoio, Victoria não tem como me parar.",
  ui_story_5084_50840900_31_dialog_content = "O túmulo da família e seu humilde guardião são as únicas coisas em que eles podem confiar. Goblin, Viper, Undine... Eu deixo os Vinekeepers para os três de vocês.",
  ui_story_5084_50840900_32_dialog_content = "Entendi.",
  ui_story_5084_50840900_33_dialog_content = "Se eu pudesse matar Wilhelm, então Victoria não deveria ser um problema.",
  ui_story_5084_50840900_34_dialog_content = "Só preciso recarregar minhas forças e ver quais truques ela reservou para esta noite.",
  ui_story_5084_50840900_35_dialog_content = "Nngh... David...",
  ui_story_5084_50840900_36_dialog_content = "... E isso é tudo que sabemos. Depois de viajar de um lado para o outro no tempo tantas vezes, mal sabemos onde estamos.",
  ui_story_5084_50840900_37_dialog_content = "Embora as revelações da Verdade possam ser obscuras, seus planos não estão sem seu significado.",
  ui_story_5084_50840900_38_dialog_content = "Três anos atrás, em nosso tempo atual - o ano de 1915 - eu vi Wilhelm pela última vez. Foi durante aquele Advento da Verdade que ele me ordenou a entrar no caixão ancestral.",
  ui_story_5084_50840900_39_dialog_content = "Lembro-me de vê-lo torcendo o anel em seu dedo naquela época, algo que nunca o tinha visto fazer antes. Foi então que eu soube...",
  ui_story_5084_50840900_40_dialog_content = "Ele estava tentando me dizer algo. Foi por isso que decidi participar do ritual.",
  ui_story_5084_50840900_41_dialog_content = "Mas quando retomei a consciência, me encontrei no atual \"presente.\"",
  ui_story_5084_50840900_42_dialog_content = "Três anos se passaram, e eu acordei na minha cama com o anel da nossa família na minha mão.",
  ui_story_5084_50840900_43_dialog_content = "Wilhelm me deu isso no final daquele ritual.",
  ui_story_5084_50840900_44_dialog_content = "E quando acordei, me encontrei naquela mansão justo quando alguém chegou com uma carta. Ele me confiou a entrega para a Senhora Victoria antes de partir.",
  ui_story_5084_50840900_45_dialog_content = "Assim que comecei a pensar sobre minha situação, a Senhora Victoria saiu da sala próxima.",
  ui_story_5084_50840900_46_dialog_content = "A carta apenas pedia que eu comparecesse à reunião dos chefes de família antes do Advento da Verdade. Mas claramente, eles não estavam esperando minha aparição.",
  ui_story_5084_50840900_47_dialog_content = "Quem veio entregar aquela carta sabia que eu estava aqui. Não só isso, mas eles sabiam que era o eu presente, não o Victoria, pertencente a este ponto.",
  ui_story_5084_50840900_48_dialog_content = "Isso me lembra, Senhora Victoria... Nós encontramos Nails mais cedo, mas... Ele estava agindo de maneira muito estranha...",
  ui_story_5084_50840900_49_dialog_content = "Ele agradeceu a Wilhelm por lhe dar a chance de estar lá, mesmo que Wilhelm não tivesse ideia de quem ele era.",
  ui_story_5084_50840900_50_dialog_content = "Poderia a pessoa que organizou tudo isso ser o Wilhelm do Advento da Verdade de três anos atrás?",
  ui_story_5084_50840900_51_dialog_content = "Ele estava morto nas visões que vimos anteriormente, e ainda assim ele de alguma forma ainda existe no passado.",
  ui_story_5084_50840900_52_dialog_content = "Ele deve ter feito algo durante o Advento da Verdade há três anos, algo que ainda está além do nosso entendimento.",
  ui_story_5084_50840900_53_dialog_content = "Mesmo assim, posso sentir que estamos nos aproximando ainda mais da Verdade.",
  ui_story_5084_50840900_54_dialog_content = "Senhora Victoria, eu preciso perguntar... Onde exatamente você estava durante o Advento da Verdade de 1918?",
  ui_story_5084_50840900_55_dialog_content = "Se eu me lembro corretamente... Eu ainda estava viajando durante o Advento da Verdade daquele ano. Como tal, eu não tinha como estar presente naquela reunião.",
  ui_story_5084_50840900_56_dialog_content = "Mas na mesma noite, eu estava dormindo na cidade de Vortex quando A Verdade me ordenou a voltar para a Bíblia Sangrenta.",
  ui_story_5084_50840900_57_dialog_content = "Quando acordei, me encontrei em um <color=#FFB400>caixão</color> no fundo do túmulo dos Varaki, a Bíblia Sangrenta firmemente apertada em minhas mãos.",
  ui_story_5084_50840900_58_dialog_content = "Depois, revelou-me que tinha reconhecido Vórtice, e que eu deveria ser o líder da Verdadeira Ordem.",
  ui_story_5084_50840900_59_dialog_content = "Esta foi a memória que o anel me mostrou antes de partirmos em nossa missão.",
  ui_story_5084_50840900_60_dialog_content = "Você disse... Um <color=#FFB400>caixão</color> na tumba Varaki? Mas por que era um <color=#FFB400>caixão</color>?",
  ui_story_5084_50840900_61_dialog_content = "Talvez seja porque... Eu também tenho o hábito de dormir neles.",
  ui_story_5084_50840900_62_dialog_content = "(Isso é verdade... Ela fez isso no caixão dos pais dela... No do Wilhelm também...)",
  ui_story_5084_50840900_63_dialog_content = "Talvez os caixões no túmulo da Família Varaki possuam algum tipo de poder desconhecido?",
  ui_story_5084_50840900_64_dialog_content = "Como o poder de viajar para diferentes épocas?",
  ui_story_5084_50840900_65_dialog_content = "Assim como o candelabro do celestita, talvez eles também possam transportá-lo para vários pontos no tempo.",
  ui_story_5084_50840900_66_dialog_content = "Também ajudou Wilhelm a abrir a porta para a cripta durante o Advento da Verdade há três anos atrás...",
  ui_story_5084_50840900_67_dialog_content = "Sikare... Quantas dessas coisas ela tem?!",
  ui_story_5084_50840900_68_dialog_content = "A família de Sikare sempre protegeu a cripta e impediu a Senhora Victoria de espiar dentro.",
  ui_story_5084_50840900_69_dialog_content = "Sempre que perguntávamos, Sikare simplesmente dizia que ainda não era o momento... Então por que agora é o momento certo?",
  ui_story_5084_50840900_70_dialog_content = "Talvez haja um significado mais profundo por trás do desaparecimento de Wilhelm, e até mesmo de sua morte.",
  ui_story_5084_50840900_71_dialog_content = "Parece que ele estava ciente do perigo que enfrentaria naquele dia há muito tempo, e ele simplesmente estava esperando que nós aparecêssemos.",
  ui_story_5084_50840900_72_dialog_content = "Ele uma vez exigiu que eu lhe desse uma explicação sobre a Verdade. Ele era quase implacável sobre isso... Mas agora percebo que ele nunca esperou uma resposta \"correta\" de mim.",
  ui_story_5084_50840900_73_dialog_content = "Porque A Verdade não tem uma resposta correta, e nunca terá.",
  ui_story_5084_50840900_74_dialog_content = "É uma fé inabalável que busca oferecer respostas infinitas.",
  ui_story_5084_50840900_75_dialog_content = "E agora que entendo o poder dessas respostas, não alimento mais nenhum medo ou dúvida. Meu propósito é claro: Devo purgar os chefes de famílias da Verdadeira Ordem.",
  ui_story_5084_50840900_76_dialog_content = "Se ao menos ele tivesse conseguido falar abertamente comigo três anos atrás e entendido minha busca...",
  ui_story_5084_50840900_77_dialog_content = "(Os dois estavam sendo teimosos por tanto tempo... Realmente não há maneira de eles se reconciliarem depois de todo esse tempo?)",
  ui_story_5084_50840900_78_dialog_content = "De qualquer forma, eu não vou parar... Até que eu tenha descoberto o significado por trás deste anel reaparecer em minha posse.",
  ui_story_5084_50840900_79_dialog_content = "(Depois de saltar de um lado para o outro no tempo tantas vezes... Eu também gostaria de uma resposta definitiva...)",
  ui_story_5084_50840900_80_dialog_content = "(Por que Victoria e eu vemos Wilhelm de maneiras tão diferentes? Pelo que vi, ele realmente se importa com ela, mas não parece ser assim nas memórias dela.)",
  ui_story_5084_50840900_81_dialog_content = "(Algo ainda está faltando... Seja lá o que for, tenho certeza de que as coisas ficarão muito mais claras quando o encontrarmos. Victoria pode até ter a chance de dar a Wilhelm sua resposta...)",
  ui_story_5084_50840900_82_dialog_content = "(... O que houve, candelabro? Você sempre me leva a uma resposta quando tenho perguntas, então por que não está funcionando desta vez?)",
  ui_story_5084_50840900_83_dialog_content = "(Ah... Acho que finalmente entendo de onde vem a fé inabalável da Verdadeira Ordem...)",
  ui_story_5084_50840900_84_dialog_content = "A noite caiu, e o Advento da Verdade está quase sobre nós. Não temos muito tempo restante.",
  ui_story_5084_50840900_85_dialog_content = "Tempo... Isso me lembra, só me resta cerca de um terço do meu castiçal.",
  ui_story_5084_50840900_86_dialog_content = "Não se preocupe, eu sei o que deve ser feito agora.",
  ui_story_5084_50840900_87_dialog_content = "Minhas ameaças durante a reunião incutiram medo em seus corações, o que só alimentou seu desejo por mais poder. Eles não medirão esforços para me derrotar agora.",
  ui_story_5084_50840900_88_dialog_content = "Mas e se eles tentarem fugir? Você pode ser bastante assustador quando quer, Victoria.",
  ui_story_5084_50840900_89_dialog_content = "A ambição de David Porfirio não permitirá que ele fuja. Ele nunca estará satisfeito a menos que alcance seu objetivo.",
  ui_story_5084_50840900_90_dialog_content = "Parece que ele possui a Bíblia Sangrenta desta vez em sua posse.",
  ui_story_5084_50840900_91_dialog_content = "Para realizar sua aspiração de se tornar o líder da Verdadeira Ordem, ele permanecerá e fará tudo ao seu alcance para presidir o ritual desta noite.",
  ui_story_5084_50840900_92_dialog_content = "A ambição pode ser uma fera aterrorizante. Assim como consumiu Wilhelm, também consumirá David.",
  ui_story_5084_50840900_93_dialog_content = "Então, onde devemos ir?",
  ui_story_5084_50840900_94_dialog_content = "Para o túmulo dos meus antepassados—Há algo que preciso confirmar lá. Se as coisas prosseguirem como esperado, David também enviará alguém para lá.",
  ui_story_5084_50840900_95_dialog_content = "Espere, Senhora Victoria... O que devemos fazer sobre o Sr. Nails?",
  ui_story_5084_50840900_96_dialog_content = "Ele ainda está em algum lugar na cidade.",
  ui_story_5084_50840900_97_dialog_content = "Não há necessidade de se preocupar por ele. Nosso senhor o abençoou com proteção, e a Verdade o guiará para onde ele precisa estar.",
  ui_story_5084_50840900_98_dialog_content = "Mas Senhora Victoria, eu vi os chefes das famílias machucá-lo gravemente com meus próprios olhos...",
  ui_story_5084_50840900_99_dialog_content = "Ainda estou preocupado com ele e tenho querido procurá-lo todo esse tempo. Só não tenho certeza se isso causará mais problemas para todos.",
  ui_story_5084_50840900_100_dialog_content = "Sentir-se confuso não é motivo para alarme, e se preocupar com os outros é uma qualidade nobre. Faça o que o seu coração mandar, May.",
  ui_story_5084_50840900_101_dialog_content = "Faust, por favor, fique com May e cuide de Nails.",
  ui_story_5084_50840900_102_dialog_content = "O Celestita e eu vamos te encontrar no templo esta noite.",
  ui_story_5084_50841001_1_dialog_content = "As vinhas na entrada estão cobertas de sangue, e os caixões foram arrombados... Será que os chefes das famílias estavam um passo à nossa frente?",
  ui_story_5084_50841001_2_dialog_content = "Perturbar os restos de nossos ancestrais... Seu desprezo por nossas doutrinas não conhece limites.",
  ui_story_5084_50841001_3_dialog_content = "Acho que este é o lugar que vimos mais cedo!",
  ui_story_5084_50841001_4_dialog_content = "É aqui que Clavis colocou Wilhelm naquele caixão...",
  ui_story_5084_50841001_5_dialog_content = "No entanto, seu caixão não está em lugar nenhum.",
  ui_story_5084_50841001_6_dialog_content = "Minha senhora... Senhora Victoria... É você?",
  ui_story_5084_50841001_7_dialog_content = "Túmulos? Graças a Deus você ainda vive. Quando vi as vinhas do lado de fora, temi o pior...",
  ui_story_5084_50841001_8_dialog_content = "Três anos, minha senhora... Por três anos, não houve um chefe da Família Varaki para defender este lugar, e assim ele caiu no caos.",
  ui_story_5084_50841001_9_dialog_content = "Com a morte de Wilhelm e seu paradeiro desconhecido, os chefes das famílias de ramo saquearam as relíquias deste túmulo com total impunidade.",
  ui_story_5084_50841001_10_dialog_content = "Eles levaram minha família e os torturaram... Me torturaram...",
  ui_story_5084_50841001_11_dialog_content = "Foi David Porfirio... Ele busca tirar tudo, incluindo meu poder como servo dos Varaki...",
  ui_story_5084_50841001_12_dialog_content = "... Me perdoe. Eu não tinha ideia de que minha ausência causaria a você e sua família um dano indescritível.",
  ui_story_5084_50841001_13_dialog_content = "Graves... Wilhelm realmente está morto?",
  ui_story_5084_50841001_14_dialog_content = "Clavis... O que você fez?",
  ui_story_5084_50841001_15_dialog_content = "... Eu simplesmente vim para colocar outro corpo sob seus cuidados.",
  ui_story_5084_50841001_16_dialog_content = "Por favor, vigie meu amigo tolo.",
  ui_story_5084_50841001_17_dialog_content = "Chave... Chave...",
  ui_story_5084_50841001_18_dialog_content = "Vi com meus próprios olhos, minha senhora. Wilhelm estava morto... E Clavis Ibrahim usou aquela chave para entrar no túmulo e colocá-lo para descansar.",
  ui_story_5084_50841001_19_dialog_content = "... Vamos entrar, Celestita.",
  ui_story_5084_50841001_20_dialog_content = "Você tem a minha palavra, Graves: Vou acabar com toda essa luta esta noite.",
  ui_story_5084_50841001_21_dialog_content = "Por favor, seja cuidadoso... Minha senhora...",
  ui_story_5084_50841001_22_dialog_content = "Nas partes mais distantes da cripta... Eles continuam a perturbar os mortos... Em busca de algo...",
  ui_story_5084_50841001_23_dialog_content = "Bem, olha quem está aqui.",
  ui_story_5084_50841001_24_dialog_content = "A própria mocinha dos Varaki.",
  ui_story_5084_50841001_25_dialog_content = "... Minha senhora!",
  ui_story_5084_50841001_26_dialog_content = "Estou surpreso que você sobreviveu, Vinekeeper...",
  ui_story_5084_50841001_27_dialog_content = "Porfírio deseja se livrar da mulher Varaki, sim?",
  ui_story_5084_50841001_28_dialog_content = "Agora é a nossa chance.",
  ui_story_5084_50841001_29_dialog_content = "Lacaios estúpidos...!",
  ui_story_5084_50841001_30_dialog_content = "Como ousa invadir a tumba dos Varaki e perturbar nossos ancestrais adormecidos!",
  ui_story_5084_50841001_31_dialog_content = "Eu pretendia punir cada um de vocês durante o ritual de hoje à noite, mas parece que vocês trouxeram a luta para mim.",
  ui_story_5084_50841002_1_dialog_content = "Victoria... A chamada Undine se escondeu no subsolo e escapou...",
  ui_story_5084_50841002_2_dialog_content = "Hmph, isso só deixa esses dois. Estão prontos para aceitar seus destinos?",
  ui_story_5084_50841002_3_dialog_content = "Espere, Senhora Victoria... Como adulta e membro respeitável dos Varaki, talvez você devesse falar com Porfirio antes de fazer algo precipitado?",
  ui_story_5084_50841002_4_dialog_content = "Impossível! Você esteve fora por apenas três anos... De onde você obteve tanto poder?!",
  ui_story_5084_50841002_5_dialog_content = "Três anos, você diz? Parece que você esteve preso em seu próprio mundo estagnado por tanto tempo que não consegue mais compreender mudanças tão drásticas.",
  ui_story_5084_50841002_6_dialog_content = "Tenho acumulado esse poder por muito mais tempo do que três anos... Mas não tenho intenção de revelar meus segredos para você.",
  ui_story_5084_50841002_7_dialog_content = "Por permitir que seus desejos o afastem da Verdade, suas vidas devem ser oferecidas como prelúdio para o Advento da Verdade!",
  ui_story_5084_50841002_8_dialog_content = "(Sikare nos disse para não mudar nada, mas Victoria matou os dois... Isso não conta como mudar o passado?!)",
  ui_story_5084_50841002_9_dialog_content = "(Ou poderia ser... as ações de Victoria foram escritas nas páginas da história há muito tempo?)",
  ui_story_5084_50841002_10_dialog_content = "Hum?",
  ui_story_5084_50841002_11_dialog_content = "Parece que você também não entende... o segredo da víbora.",
  ui_story_5084_50841002_12_dialog_content = "Mesmo que você corte minha cabeça, vou trocar minha pele e renascer...",
  ui_story_5084_50841002_13_dialog_content = "Então eu vou cortá-lo quantas vezes for necessário!",
  ui_story_5084_50841002_14_dialog_content = "E-Espere! Você não pode me matar dessa maneira!",
  ui_story_5084_50841002_15_dialog_content = "Nunca foi minha intenção fazer isso. Estou simplesmente curioso para ver quanto tempo mais você pode suportar a dor de ter sua cabeça cortada.",
  ui_story_5084_50841002_16_dialog_content = "Agora grite! Peça por misericórdia! <size=45>Implore para que eu acabe com a sua miséria—!</size>",
  ui_story_5084_50841002_17_dialog_content = "(Aff, Victoria... Eu não percebi que ela poderia ser tão cruel...)",
  ui_story_5084_50841002_18_dialog_content = "<color=#e8d9bb>De repente, um dos caixões dentro da cripta se abre com uma força violenta, e uma pessoa sai dele—</color>",
  ui_story_5084_50841002_19_dialog_content = "Não há necessidade de desperdiçar sua força com alguém como ele.",
  ui_story_5084_50841002_20_dialog_content = "?!",
  ui_story_5084_50841002_21_dialog_content = "... W-Wilhelm?!?",
  ui_story_5084_50841002_22_dialog_content = "Impossível! Você deveria ter morrido há muito tempo!",
  ui_story_5084_50841002_23_dialog_content = "... Então você ainda está vivo afinal.",
  ui_story_5084_50841002_24_dialog_content = "Não exatamente. Após minha morte, passei muitos anos percorrendo o fluxo infinito do tempo, e agora finalmente tenho uma leve noção da vontade do nosso senhor.",
  ui_story_5084_50841002_25_dialog_content = "A chegada da Verdade três anos atrás... Foi você.",
  ui_story_5084_50841002_26_dialog_content = "Três anos... Um piscar de olhos no grande esquema da existência. Foi o destino que me guiou até aqui, e este parece ser minha última parada.",
  ui_story_5084_50841002_27_dialog_content = "...?!",
  ui_story_5084_50841002_28_dialog_content = "(Eu sabia! Realmente havia dois Wilhelms o tempo todo!)",
  ui_story_5084_50841002_29_dialog_content = "(Então o que sacrificou Victoria e organizou tudo isso... Foi Wilhelm após sua própria morte?)",
  ui_story_5084_50841002_30_dialog_content = "Pegue isso. É um símbolo do desejo do destino de seguir você—",
  ui_story_5084_50841002_31_dialog_content = "... A Bíblia Sangrenta?",
  ui_story_5084_50841002_32_dialog_content = "Não... Isso não é nada como a relíquia que eu conheci ao longo dos anos.",
  ui_story_5084_50841002_33_dialog_content = "Uma nova Bíblia Sangrenta, destinada àquele que guiará o futuro.",
  ui_story_5084_50841002_34_dialog_content = "Pegue, pois você é o único que pode empunhar seu poder.",
  ui_story_5084_50841002_35_dialog_content = "Use-o para derrotar os tolos traidores que estão diante de você.",
  ui_story_5084_50841002_36_dialog_content = "... Eu recuso.",
  ui_story_5084_50841002_37_dialog_content = "...?!",
  ui_story_5084_50841002_38_dialog_content = "Eu não preciso do seu poder—Eles foram os que te mataram, então sua vingança é um assunto seu.",
  ui_story_5084_50841002_39_dialog_content = "Qual é o significado disso? Por que estamos impotentes contra ele?!",
  ui_story_5084_50841002_40_dialog_content = "Esse homem não é o mesmo cara que matamos no passado.",
  ui_story_5084_50841002_41_dialog_content = "Maldito seja, Wilhelm! O que exatamente aconteceu com você depois que morreu?! Você tem que nos contar... Pelo menos compartilhe essa Verdade conosco!",
  ui_story_5084_50841002_42_dialog_content = "... Silêncio, traidores!",
  ui_story_5084_50841002_43_dialog_content = "A Verdade não precisa da sua compreensão!",
  ui_story_5084_50841002_44_dialog_content = "Ele apenas exige seu sangue em troca de seus crimes contra os ancestrais dos Varaki!",
  ui_story_5084_50841002_45_dialog_content = "Va... raki...",
  ui_story_5084_50841002_46_dialog_content = "(Wilhelm os destruiu ambos com um único ataque...!)",
  ui_story_5084_50841002_47_dialog_content = "Wilhelm Varaki... Este caixão deveria conter os restos de nossos ancestrais. O que exatamente aconteceu com você?",
  ui_story_5084_50841002_48_dialog_content = "Por que você desapareceu? E o que fez você reaparecer diante de nós hoje?",
  ui_story_5084_50841002_49_dialog_content = "Você renasceu? Ou você é apenas um fantasma agora?",
  ui_story_5084_50841002_50_dialog_content = "Você é exatamente como eu me lembro, Victoria: sempre tão cheio de perguntas.",
  ui_story_5084_50841002_51_dialog_content = "Infelizmente, não adianta mais discutir essas coisas. O tempo já nos escapou e há muito tempo estamos mortos.",
  ui_story_5084_50841002_52_dialog_content = "Adeus, Victoria.",
  ui_story_5084_50841002_53_dialog_content = "(Ele está saindo assim...? Eles finalmente têm a chance de se ver novamente e claramente se importam um com o outro... Então por que eles não dizem nada?)",
  ui_story_5084_50841002_54_dialog_content = "P-Por favor, espere, Sr. Wilhelm!",
  ui_story_5084_50841002_55_dialog_content = "Celestita...",
  ui_story_5084_50841002_56_dialog_content = "E você é...?",
  ui_story_5084_50841002_57_dialog_content = "Espere, aquela voz...",
  ui_story_5084_50841002_58_dialog_content = "Ah... Agora entendi...",
  ui_story_5084_50841002_59_dialog_content = "Isso deve ser destino...",
  ui_story_5084_50841002_60_dialog_content = "Hehe... Como é divertido...",
  ui_story_5084_50841002_61_dialog_content = "Senhor Wilhelm! Você pode chamar isso de \"destino\"—",
  ui_story_5084_50841002_62_dialog_content = "Mas quando você ouviu suas palavras, ainda decidiu buscar a Verdade em seu coração. Você foi para a cripta porque estava preocupado com Victoria!",
  ui_story_5084_50841002_63_dialog_content = "E em vez de aceitar seu destino pré-determinado, Victoria escolheu usar o anel e suportar aquelas vozes para te encontrar...",
  ui_story_5084_50841002_64_dialog_content = "Você já realizou o inimaginável ao viajar de um lado para o outro no tempo; seria realmente tão irracional para vocês dois terem uma conversa normal?",
  ui_story_5084_50841002_65_dialog_content = "Quando você lutou lado a lado contra os chefes das famílias... Eu pude ver as emoções que motivavam suas ações.",
  ui_story_5084_50841002_66_dialog_content = "Desculpe... Eu não sei se estou mudando a história ao dizer algo que não deveria dizer...",
  ui_story_5084_50841002_67_dialog_content = "Mas, do fundo do meu coração, acredito em tudo que estou prestes a dizer...",
  ui_story_5084_50841002_68_dialog_content = "Sempre pensei que as palavras eram a melhor maneira de guardar um segredo... Se vocês não se abrirem um para o outro agora, podem nunca mais ter a chance de se entenderem novamente.",
  ui_story_5084_50841002_69_dialog_content = "...",
  ui_story_5084_50841002_70_dialog_content = "...",
  ui_story_5084_50841002_71_dialog_content = "Perguntas, respostas... Nenhum deles realmente importa mais. Tudo o que importa é que vocês dois estão aqui agora.",
  ui_story_5084_50841002_72_dialog_content = "Independentemente de \"destino\" decidir ou não, cada uma de suas decisões deve vir do coração.",
  ui_story_5084_50841002_73_dialog_content = "Celestita... Você...",
  ui_story_5084_50841002_74_dialog_content = "Heheh, se o resto do mundo pudesse ser tão sincero quanto você... Talvez eles não fossem tão facilmente enganados.",
  ui_story_5084_50841002_75_dialog_content = "Uma sinceridade tão pura é um dos maiores tesouros dos jovens Celestitas.",
  ui_story_5084_50841002_76_dialog_content = "Agora então... Por onde começar?",
  ui_story_5084_50841002_77_dialog_content = "Eu tenho vagado pelo tempo por incontáveis eras agora... E nunca anseiei pelo fim mais do que agora.",
  ui_story_5084_50841002_78_dialog_content = "Victoria... Finalmente entendo o desejo do meu irmão por um sono eterno, e acredito que você também entenda.",
  ui_story_5084_50841002_79_dialog_content = "As escolhas feitas pelos nossos corações são mais numerosas do que as estrelas no céu.",
  ui_story_5084_50841002_80_dialog_content = "Devo agradecer a você, Victoria... Você libertará os Varaki de sua maldição de sangue algum dia, e finalmente poderei descansar em paz.",
  ui_story_5084_50841002_81_dialog_content = "É tão improvável que você possa expressar gratidão... Serei eu realmente o único a desfazer a maldição da nossa família...?",
  ui_story_5084_50841002_82_dialog_content = "Como diz o celestita, nossas perguntas e respostas...",
  ui_story_5084_50841002_83_dialog_content = "Não são importantes agora!",
  ui_story_5084_50841002_84_dialog_content = "A Verdade varia de pessoa para pessoa. Não há uma resposta final ou absoluta; apenas uma crença que deve ser constantemente perseguida.",
  ui_story_5084_50841002_85_dialog_content = "... Você pode falar à vontade agora.",
  ui_story_5084_50841002_86_dialog_content = "Nosso mundo é marcado pelo sofrimento e pelas diferenças. Aqueles abençoados com a imortalidade são consumidos pelo seu desejo de morte, enquanto seus equivalentes mortais anseiam por futuros mais longos.",
  ui_story_5084_50841002_87_dialog_content = "Realmente existe um salvador em <color=#FFB400>Eoria</color>?",
  ui_story_5084_50841002_88_dialog_content = "Em minhas visões, vi sofrimentos incontáveis, e ainda assim minha fé na <color=#FFB400>salvação</color> só se fortaleceu por causa disso.",
  ui_story_5084_50841002_89_dialog_content = "Portanto, A Verdade que busco deve levar à <color=#FFB400>salvação</color> do mundo e à erradicação de toda semente caída.",
  ui_story_5084_50841002_90_dialog_content = "Ao transcender as limitações da consciência e corporeidade, os Aurorians alcançarão sua evolução final e se aproximarão das estrelas, onde a suprema Verdade aguarda sua chegada.",
  ui_story_5084_50841002_91_dialog_content = "... Você realmente cresceu e se tornou um líder digno, Victoria. É exatamente como a Verdade me revelou.",
  ui_story_5084_50841002_92_dialog_content = "Você mencionou as estrelas... No momento da minha queda, vi um rio na escuridão.",
  ui_story_5084_50841002_93_dialog_content = "Nela, a causalidade de toda existência flui sem fim. Mesmo a menor perturbação pode resultar em uma catástrofe insondável.",
  ui_story_5084_50841002_94_dialog_content = "Como membros da família imortal de sangue, passamos uma quantidade excessiva de tempo perseguindo algo que é apenas um grão de areia neste rio.",
  ui_story_5084_50841002_95_dialog_content = "Mesmo assim, minha obsessão implacável me levou a esse rio.",
  ui_story_5084_50841002_96_dialog_content = "Desde então, fortaleci a Verdade dentro do meu coração - E embora minha jornada tenha sido de dificuldades e sofrimentos, estou convencido de que meus desejos eventualmente influenciarão o fluxo da causalidade.",
  ui_story_5084_50841002_97_dialog_content = "Você acredita que suas convicções são poderosas o suficiente para transcender as algemas do destino?",
  ui_story_5084_50841002_98_dialog_content = "Sim. Eu vou obedecê-los, praticá-los e, finalmente... encontrarei uma maneira de ver os desígnios do destino e remodelá-los com minhas próprias mãos.",
  ui_story_5084_50841002_99_dialog_content = "... Agora vá, Victoria. Percorra o caminho da sua Verdade e remova qualquer obstáculo que esteja em seu caminho.",
  ui_story_5084_50841002_100_dialog_content = "Como eu certamente vou.",
  ui_story_5084_50841002_101_dialog_content = "Então, deixo David a seu cargo. Pare-o antes que ele transforme nossa cidade em um lugar de morte.",
  ui_story_5084_50841002_102_dialog_content = "Para onde você vai agora?",
  ui_story_5084_50841002_103_dialog_content = "Já sou um ser que existe fora do fluxo do tempo. Só posso alterar os eventos da história se o destino permitir...",
  ui_story_5084_50841002_104_dialog_content = "... Eu nunca esperava ter essa discussão final com você, tio.",
  ui_story_5084_50841002_105_dialog_content = "Você realmente amadureceu, Victoria... Que reconfortante.",
  ui_story_5084_50841002_106_dialog_content = "Agora, pegue esta Bíblia Sangrenta em suas mãos. Você vai precisar dela.",
  ui_story_5084_50841002_107_dialog_content = "Eu já tenho o poder que preciso para buscar a Verdade. Não há razão para eu pegá-lo.",
  ui_story_5084_50841002_108_dialog_content = "... Mesmo assim, o destino irá guiá-lo até lá algum dia.",
  ui_story_5084_50841002_109_dialog_content = "Adeus, Victoria Varaki.",
  ui_story_5084_50841002_110_dialog_content = "Seu discípulo, aquele chamado Nails... Ele pode aprender muito.",
  ui_story_5084_50841002_111_dialog_content = "Deixo o futuro da True Order em suas mãos.",
  ui_story_5084_50841002_112_dialog_content = "... Veremos um ao outro novamente?",
  ui_story_5084_50841002_113_dialog_content = "Já concluí a tarefa que nosso senhor me designou. Agora, chegou a hora de cuidar dos meus próprios assuntos.",
  ui_story_5084_50841002_114_dialog_content = "Quando todas as coisas tiverem terminado, venha me encontrar aqui.",
  ui_story_5084_50841002_115_dialog_content = "E quanto a você, Celestita do futuro... Obrigado por me guiar com sua sinceridade.",
  ui_story_5084_50841101_1_dialog_content = "Isso é tudo culpa da avó... Ela insistiu em me fazer ouvir suas orações ao Senhor da Verdade antes de me deixar ir...",
  ui_story_5084_50841101_2_dialog_content = "Agora estou preso no fundo do público sem nenhuma maneira de ver o desfile!",
  ui_story_5084_50841101_3_dialog_content = "Sua avó é muito velha para participar do Advento da Verdade, querida.",
  ui_story_5084_50841101_4_dialog_content = "Mas, após passar toda a sua vida fazendo roupas para os fiéis, ela ainda deseja que alguém apresente seus desejos ao Senhor da Verdade. É por isso que ela os confiou a você.",
  ui_story_5084_50841101_5_dialog_content = "Vou te levantar para ver o desfile - Mas você deve lembrar das palavras da sua avó. Esta é uma ocasião sincera, e você deve tratá-la como tal.",
  ui_story_5084_50841101_6_dialog_content = "... Entendo.",
  ui_story_5084_50841101_7_dialog_content = "Esta rua é bastante familiar. É onde eu encontrei PlayerName antes.",
  ui_story_5084_50841101_8_dialog_content = "Mas como vamos encontrar Nails em um público enorme como este?",
  ui_story_5084_50841101_9_dialog_content = "May... Você se lembra de ter visto essas pessoas vestidas estranhamente antes?",
  ui_story_5084_50841101_10_dialog_content = "D-Deixe-me pensar sobre isso...",
  ui_story_5084_50841101_11_dialog_content = "Ah—!!!",
  ui_story_5084_50841101_12_dialog_content = "O que foi isso? Vamos investigar, May!",
  ui_story_5084_50841101_13_dialog_content = "... É o morto-vivo! Eles caminham entre nós—!",
  ui_story_5084_50841101_14_dialog_content = "Todo-poderoso senhor... Esta deve ser minha punição por ler o diário secreto da minha irmã e revelar sua hipocrisia ao público...",
  ui_story_5084_50841101_15_dialog_content = "Mas os líderes da True Order afirmaram que eu estava doente, e que você nunca favoreceria meu sangue.",
  ui_story_5084_50841101_16_dialog_content = "Devo me redimir com minha carne...!",
  ui_story_5084_50841101_17_dialog_content = "Mãe...?",
  ui_story_5084_50841101_18_dialog_content = "Mas eu imploro que poupe minha filha, senhor. Ela é apenas uma criança inocente...",
  ui_story_5084_50841101_19_dialog_content = "Ó Senhor da Verdade!",
  ui_story_5084_50841101_20_dialog_content = "Esses são seus servos? Eles vieram... Para me punir pelos meus pecados?",
  ui_story_5084_50841101_21_dialog_content = "Eu entendo e me submeto à sua vontade divina! Faça o que deve comigo!",
  ui_story_5084_50841101_22_dialog_content = "—!",
  ui_story_5084_50841101_23_dialog_content = "Mãe—!",
  ui_story_5084_50841101_24_dialog_content = "Ah...!!!",
  ui_story_5084_50841101_25_dialog_content = "C-Corre, criança—!",
  ui_story_5084_50841101_26_dialog_content = "O sangue está fluindo pelas ruas. Esses monstros encapuzados... Eles estão atacando os cidadãos!",
  ui_story_5084_50841101_27_dialog_content = "May! Prepare-se para a batalha!",
  ui_story_5084_50841101_28_dialog_content = "Como eu pensei... Agora que a Senhora Victoria entrou em ação, o destino está nos permitindo interferir.",
  ui_story_5084_50841101_29_dialog_content = "Parece bom para mim! Hora de punir algumas crianças desobedientes!",
  ui_story_5084_50841101_30_dialog_content = "... Eu não sinto dor!",
  ui_story_5084_50841101_31_dialog_content = "Ainda há tantos deles...!",
  ui_story_5084_50841101_32_dialog_content = "Ah...!!!",
  ui_story_5084_50841101_33_dialog_content = "Mãe—!!!!",
  ui_story_5084_50841101_34_dialog_content = "Não temas, meu cordeiro perdido... O Sangue Sagrado está prestes a se condensar e tomar forma...",
  ui_story_5084_50841101_35_dialog_content = "É você... O Iniciado! Mas por que está se machucando?!",
  ui_story_5084_50841101_36_dialog_content = "Criança tola... Este não é o meu poder, e eu não sou este chamado \"Iniciado\". Eu sou Nails...",
  ui_story_5084_50841101_37_dialog_content = "O Senhor da Verdade me disse para não sentir nem pena nem remorso.",
  ui_story_5084_50841101_38_dialog_content = "Embora sua mãe seja uma pecadora, assim como eu...",
  ui_story_5084_50841101_39_dialog_content = "Devo responder por todos os pecadores!",
  ui_story_5084_50841101_40_dialog_content = "O que... O que é isso...?",
  ui_story_5084_50841101_41_dialog_content = "É tanto um pecado... Quanto uma bênção...",
  ui_story_5084_50841101_42_dialog_content = "É o poder do Sangue Sagrado... O poder mencionado pelo meu mentor!",
  ui_story_5084_50841101_43_dialog_content = "Ferve com vida enquanto percorre minhas veias, queimando-me com o calor infinito de nosso senhor!",
  ui_story_5084_50841101_44_dialog_content = "Eis aqui, meu cordeiro perdido—",
  ui_story_5084_50841101_45_dialog_content = "O Senhor da Verdade nos absolverá de nossos pecados!",
  ui_story_5084_50841101_46_dialog_content = "...!",
  ui_story_5084_50841101_47_dialog_content = "É você... O Iniciado de mais cedo hoje! Você ascendeu e se tornou um dos santos sagrados do nosso senhor!",
  ui_story_5084_50841101_48_dialog_content = "Não... Por favor, não se refira a mim dessa maneira... Eu sou simplesmente—",
  ui_story_5084_50841101_49_dialog_content = "As túnicas que você está vestindo... São as túnicas que minha mãe e avó fizeram especialmente para você.",
  ui_story_5084_50841101_50_dialog_content = "Foi graças a você e sua família que eu pude me tornar a pessoa que sou hoje.",
  ui_story_5084_50841101_51_dialog_content = "O Lord Wilhelm deve ter tido seus motivos naquela época... Mas você certamente será escolhido como o Iniciado este ano!",
  ui_story_5084_50841101_52_dialog_content = "Meu mentor me mostrou muitas verdades nobres, pelas quais sou eternamente grato.",
  ui_story_5084_50841101_53_dialog_content = "Agora, por favor, deixe este lugar antes que o perigo retorne. Tudo ficará bem, eu asseguro a você.",
  ui_story_5084_50841101_54_dialog_content = "Muito bem. May Que a Verdade te abençoe agora e para sempre, Santo Nails!",
  ui_story_5084_50841101_55_dialog_content = "May Que a Verdade vos abençoe, Santo Nails!",
  ui_story_5084_50841101_56_dialog_content = "May A Verdade lhe abençoe também.",
  ui_story_5084_50841101_57_dialog_content = "\"Santo Nails,\" huh?",
  ui_story_5084_50841101_58_dialog_content = "Vimos você derrotar aqueles monstros de longe.",
  ui_story_5084_50841101_59_dialog_content = "Oh? May, Faust... Já faz bastante tempo, não é?",
  ui_story_5084_50841101_60_dialog_content = "Eu... Eu estou feliz que você esteja bem!",
  ui_story_5084_50841101_61_dialog_content = "PlayerName e eu estávamos tão preocupados com você!",
  ui_story_5084_50841101_62_dialog_content = "Foi minha culpa por superestimar minhas habilidades... Eu causei a você preocupações desnecessárias... E por isso eu preciso me redimir...",
  ui_story_5084_50841101_63_dialog_content = "Seu poder agora foi incrível! Isso tem algo a ver com essas vestes?",
  ui_story_5084_50841101_64_dialog_content = "Possivelmente... Nos últimos três anos, tenho usado as vestes confeccionadas para mim por aquela família de costureiras.",
  ui_story_5084_50841101_65_dialog_content = "Q-Quer dizer que você nunca foi a nenhum outro lugar? Em outras palavras... Você ficou sentado em Varaki Town por três anos inteiros?!",
  ui_story_5084_50841101_66_dialog_content = "Não ficando parado, May, mas praticando com meu mentor... Ele me levou a muitos lugares diferentes... Não apenas na cidade.",
  ui_story_5084_50841101_67_dialog_content = "Seu mentor...",
  ui_story_5084_50841101_68_dialog_content = "É por causa do treinamento dele que você consegue condensar e remodelar seu sangue assim agora?",
  ui_story_5084_50841101_69_dialog_content = "De fato... Meu mentor afirma que meu Sangue Raro é tudo, menos uma maldição...",
  ui_story_5084_50841101_70_dialog_content = "\"Onde você perde, aqui você ganha. Onde você expia, aqui você é abençoado.\"",
  ui_story_5084_50841102_1_dialog_content = "<color=#e8d9bb>Três anos atrás...</color>",
  ui_story_5084_50841102_2_dialog_content = "Ó Senhor da Verdade, seu humilde servo Nails implora que o liberte de seu sofrimento mais uma vez...",
  ui_story_5084_50841102_3_dialog_content = "Uma presença vil permeia meu sangue... Eu já estou pronto para o fim há muito tempo...",
  ui_story_5084_50841102_4_dialog_content = "O que é isso...?",
  ui_story_5084_50841102_5_dialog_content = "Embora a Senhora Victoria tenha dito uma vez que minha devoção me guiaria... Eu anseio por sacrifício...",
  ui_story_5084_50841102_6_dialog_content = "Eu vou...",
  ui_story_5084_50841102_7_dialog_content = "...",
  ui_story_5084_50841102_8_dialog_content = "... Meu senhor?",
  ui_story_5084_50841102_9_dialog_content = "É você! O todo-poderoso Senhor da Verdade!",
  ui_story_5084_50841102_10_dialog_content = "Você acabou de dizer... Senhora Victoria?",
  ui_story_5084_50841102_11_dialog_content = "Sou apenas um pecador sem vergonha... Mas meus erros não preocupam a Senhora Victoria.",
  ui_story_5084_50841102_12_dialog_content = "Ela me acolheu e me abençoou com a companhia da Verdadeira Ordem... No entanto, eu retribuo sua bondade permitindo que meu sangue manchado polua este mundo.",
  ui_story_5084_50841102_13_dialog_content = "Então, essa Senhora Victoria é a líder da Verdadeira Ordem, e você é um dos seus membros?",
  ui_story_5084_50841102_14_dialog_content = "Sim, meu senhor... Meu nome é Nails.",
  ui_story_5084_50841102_15_dialog_content = "Você é o único nesta cripta?",
  ui_story_5084_50841102_16_dialog_content = "Não, meu senhor. Estou acompanhado pela Senhora Victoria, Faust, May e o Celestita... Entramos na cripta juntos, mas logo depois nos separamos.",
  ui_story_5084_50841102_17_dialog_content = "Eles são corajosos, gentis e cheios de luz... Tenho certeza de que você os guiou para onde precisavam estar, meu senhor...",
  ui_story_5084_50841102_18_dialog_content = "\"Para servir como um guia para a Verdade...\"",
  ui_story_5084_50841102_19_dialog_content = "Você seguiu seus próprios caminhos... Estou surpreso que um Celestita tenha se juntado à Verdadeira Ordem...",
  ui_story_5084_50841102_20_dialog_content = "\"A Verdade se revelou em seu coração e o abençoou. Ele é um agente de mudança dentro da True Order.\"",
  ui_story_5084_50841102_21_dialog_content = "Ser abençoado pela Verdade...",
  ui_story_5084_50841102_22_dialog_content = "Deseja confessar algo ao Senhor da Verdade?",
  ui_story_5084_50841102_23_dialog_content = "Confesso... Que pequei desde o momento em que nasci. Veja por si mesmo, meu senhor...",
  ui_story_5084_50841102_24_dialog_content = "Apenas uma criatura pecadora como eu seria amaldiçoada com um sangue tão contaminado...",
  ui_story_5084_50841102_25_dialog_content = "Tais palavras tolas...",
  ui_story_5084_50841102_26_dialog_content = "M-Meu senhor...?",
  ui_story_5084_50841102_27_dialog_content = "O sol ainda brilha sobre a terra. Tenho tempo para ouvir sobre o seu passado pecaminoso.",
  ui_story_5084_50841102_28_dialog_content = "Você não precisa se preocupar com as minhas ações, agora fale.",
  ui_story_5084_50841102_29_dialog_content = "Eu apenas peço que você guarde esse prego. Este é o túmulo dos Varaki, e eu não permitirei que você derrame seu sangue nele.",
  ui_story_5084_50841102_30_dialog_content = "Como você ordena, Senhor da Verdade!",
  ui_story_5084_50841102_31_dialog_content = "Além disso, não sou o Senhor da Verdade.",
  ui_story_5084_50841102_32_dialog_content = "Não? Então quem é você—?",
  ui_story_5084_50841102_33_dialog_content = "Meu nome é Wilhelm Varaki, embora esse sobrenome dificilmente seja adequado para um cara como eu.",
  ui_story_5084_50841102_34_dialog_content = "... \"Varaki\"?! Você compartilha o mesmo sobrenome glorioso que a Senhora Victoria!",
  ui_story_5084_50841102_35_dialog_content = "\"Glorioso\", você diz? Heheh, não é nada mais do que um nome usado para intimidar os outros.",
  ui_story_5084_50841102_36_dialog_content = "A pessoa que você vê diante de você é alguém com laços intrincados com a Verdadeira Ordem, um ser que existe além do fluxo do tempo.",
  ui_story_5084_50841102_37_dialog_content = "Agora me diga, quem é que te vê como um monstro?",
  ui_story_5084_50841102_38_dialog_content = "Meu irmão... Meus pais... Minha família inteira...",
  ui_story_5084_50841102_39_dialog_content = "E isso é tudo por causa do chamado \"Sangue Raro\" que corre em suas veias?",
  ui_story_5084_50841102_40_dialog_content = "Sim... Mas também porque minha própria existência trouxe danos ao meu irmão e vergonha para minha família.",
  ui_story_5084_50841102_41_dialog_content = "Meu irmão já foi um membro gentil e corajoso da Ordem, muito parecido com meus companheiros...",
  ui_story_5084_50841102_42_dialog_content = "No passado, eu parecia estar no caminho para a riqueza e glória por causa dos meus poderes, que me permitiam superar muitos outros cavaleiros em duelos.",
  ui_story_5084_50841102_43_dialog_content = "Meu irmão, no entanto, não teve tanta sorte...",
  ui_story_5084_50841102_44_dialog_content = "Quando o filho de uma família rival o atacou, tentei protegê-lo sem perceber o alcance dos meus próprios poderes...",
  ui_story_5084_50841102_45_dialog_content = "E como resultado...!",
  ui_story_5084_50841102_46_dialog_content = "Meu pobre irmão... Ele sabia o quão vergonhoso seria para nossa família... Se um pecador como eu continuasse a viver naquela cidade pura e nobre.",
  ui_story_5084_50841102_47_dialog_content = "Então ele decidiu me libertar, deixando meu \"sangue raro\" se manifestar e subsequentemente... me baniu de Lumópolis.",
  ui_story_5084_50841102_48_dialog_content = "Onde eu já vi isso antes...",
  ui_story_5084_50841102_49_dialog_content = "Então você se mudou antes de Victoria recrutá-lo para a True Order?",
  ui_story_5084_50841102_50_dialog_content = "Sim, mesmo que eu tivesse esperado morrer na guerra entre Aurorianos e Eclipsitas.",
  ui_story_5084_50841102_51_dialog_content = "Mas o Senhor deve ter me marcado como um pecador, já que o Sangue Raro continuava me tirando do coma vez após vez para me lembrar...",
  ui_story_5084_50841102_52_dialog_content = "Ainda não me redimi... Ainda não posso voltar para o Senhor da Verdade.",
  ui_story_5084_50841102_53_dialog_content = "...",
  ui_story_5084_50841102_54_dialog_content = "Você falou demais? Desculpe, Sr. Wilhelm, eu pensei, de forma bastante ingênua, que eu havia sido perdoado e estava de volta às boas graças do Senhor.",
  ui_story_5084_50841102_55_dialog_content = "Sua história soa como se você nasceu em uma família nobre e muito talentosa para mim.",
  ui_story_5084_50841102_56_dialog_content = "Mas aquele irmão inepto seu guardava rancor contra você e queria ser o patriarca, assim, tramando para eliminá-lo.",
  ui_story_5084_50841102_57_dialog_content = "Ele assumiu como patriarca agora, não é?",
  ui_story_5084_50841102_58_dialog_content = "Ah, ele mereceu, e não foi um \"plano para eliminar\".",
  ui_story_5084_50841102_59_dialog_content = "Bem, eu tenho minhas dúvidas... Criança de Lumópolis, gentil, corajosa, otimista?",
  ui_story_5084_50841102_60_dialog_content = "O décimo segundo chefe da True Order é um herege rejeitado por Lumópolis.",
  ui_story_5084_50841102_61_dialog_content = "Sem aquele herege, não haveria a atual True Order.",
  ui_story_5084_50841102_62_dialog_content = "Eu sou de fato o herege rejeitado por Lumópolis, mas meu irmão...",
  ui_story_5084_50841102_63_dialog_content = "Diga-me, que emoção ela mostrou quando você partiu?",
  ui_story_5084_50841102_64_dialog_content = "...",
  ui_story_5084_50841102_65_dialog_content = "Aposto que você nunca esqueceria como ele te olhava, você, a quem ele fez de tudo para arruinar, indo para o exílio.",
  ui_story_5084_50841102_66_dialog_content = "Ele sorriu e me desejou tudo de bom.",
  ui_story_5084_50841102_67_dialog_content = "Heh, eles sempre conseguem encontrar algo para te culpar, quando querem te intimidar ou perseguir.",
  ui_story_5084_50841102_68_dialog_content = "Portanto, você pensou que era irredimível e se juntou à Verdadeira Ordem, enquanto se apegava à auto-culpa e ao tormento.",
  ui_story_5084_50841102_69_dialog_content = "A raiz de sua penitência é o auto-ódio. Você detesta o Sangue Raro!",
  ui_story_5084_50841102_70_dialog_content = "E a raiz do meu ódio é a esperança que você tem por aqueles malfeitores, que falaram mal de você, mas você aceitou isso como verdade.",
  ui_story_5084_50841102_71_dialog_content = "Deixe-me dizer, Sangue Raro não é uma maldição, mas uma bênção do Senhor da Verdade.",
  ui_story_5084_50841102_72_dialog_content = "O fato de eles terem te ajudado a matar os Eclipsitas é a prova. Não tenha dúvidas sobre isso. Você não tem motivo para se odiar.",
  ui_story_5084_50841102_73_dialog_content = "Ele não merecia ser seu irmão, Nails. Mas a coisa triste é que você é um bom irmão.",
  ui_story_5084_50841102_74_dialog_content = "Irmãos traem e se separam um do outro... O destino decretou que nos encontrássemos aqui, Wilhelm Varaki.",
  ui_story_5084_50841102_75_dialog_content = "Você realmente se certificou de zombar de mim de novo!",
  ui_story_5084_50841102_76_dialog_content = "Ouça com atenção, Nails. Você é gentil e corajoso, mas um pouco falta de doçura. O que acha de Hails? É parecido com o seu nome.",
  ui_story_5084_50841102_77_dialog_content = "Você desfrutará da verdadeira salvação se escolher proteger os outros com seu Sangue Raro.",
  ui_story_5084_50841102_78_dialog_content = "Você é muito ousado para sentir dessa maneira, mas eu...",
  ui_story_5084_50841102_79_dialog_content = "Você pode lidar com isso—",
  ui_story_5084_50841102_80_dialog_content = "...",
  ui_story_5084_50841102_81_dialog_content = "O Senhor não mostra favoritismo a ninguém. Se você não pode se perdoar, como Ele pode te redimir?",
  ui_story_5084_50841102_82_dialog_content = "Lembre-se, somente quando você se reconhecer é que o Senhor o reconhecerá.",
  ui_story_5084_50841102_83_dialog_content = "Por que você está dizendo tudo isso para mim, Sr. Wilhelm?",
  ui_story_5084_50841102_84_dialog_content = "Porque eu sei que nosso encontro aqui mudou algo para sempre.",
  ui_story_5084_50841102_85_dialog_content = "Acredito firmemente que foi o Senhor que te enviou aqui.",
  ui_story_5084_50841102_86_dialog_content = "Então isso não é o fim para você, Nails, mas o início de sua devoção. Você vai aprender comigo?",
  ui_story_5084_50841102_87_dialog_content = "Farei qualquer coisa para me purificar dos pecados.",
  ui_story_5084_50841102_88_dialog_content = "Bom. Então vamos começar. Temos muito a ser feito, mas não aqui.",
  ui_story_5084_50841102_89_dialog_content = "Este é o lugar onde o passado termina, e seus três anos de cultivo começaram com a Chegada da Verdade em sua chegada.",
  ui_story_5084_50841102_90_dialog_content = "Seu líder retornou para lá. Deite-se no caixão atrás de mim e lembre-se do Advento da Verdade em Varaki, onde você encontrará seus companheiros.",
  ui_story_5084_50841102_91_dialog_content = "Quando abrir os olhos novamente, me encontre no Advento da Verdade. Vou garantir que você seja iniciado e receba as bênçãos da Verdade.",
  ui_story_5084_50841102_92_dialog_content = "Como chego lá?",
  ui_story_5084_50841102_93_dialog_content = "Através da sua fé, Nails.",
  ui_story_5084_50841102_94_dialog_content = "É a sua fé que te trouxe aqui. Apenas sinta com seu corpo.",
  ui_story_5084_50841102_95_dialog_content = "Quando você renasce com qualquer bênção ou celebração, você descobriu A Verdade.",
  ui_story_5084_50841102_96_dialog_content = "Você está se referindo à fé...?",
  ui_story_5084_50841102_97_dialog_content = "Sim. A partir de agora, sou seu mentor.",
  ui_story_5084_50841102_98_dialog_content = "<color=#e8d9bb>At the entrance to a tailor's shop in Varaki Town</color>",
  ui_story_5084_50841102_99_dialog_content = "Como cheguei aqui?",
  ui_story_5084_50841102_100_dialog_content = "Are you here for the ceremonial robe, sir?",
  ui_story_5084_50841102_101_dialog_content = "Ceremonial robe...?",
  ui_story_5084_50841102_102_dialog_content = "Não é de se admirar que você falou em palavras que não entendemos... Você conhece o Sr. Wilhelm há bastante tempo, pelo que vejo.",
  ui_story_5084_50841102_103_dialog_content = "E o mais enigmático nisso tudo.",
  ui_story_5084_50841102_104_dialog_content = "Não acredito que realmente pensei que fui escolhido para a iniciação... e realmente entrei no salão com essa ideia.",
  ui_story_5084_50841102_105_dialog_content = "Ainda não consigo acreditar em tudo o que está acontecendo comigo. Eu nem mesmo sei quando foi a primeira vez que vi meu mentor.",
  ui_story_5084_50841102_106_dialog_content = "Mas quando ele me mandou de volta para o Advento da Verdade, aquele cara não me reconheceu...",
  ui_story_5084_50841102_107_dialog_content = "E então, Nails? O que aconteceu depois que Wilhelm te expulsou da igreja?",
  ui_story_5084_50841102_108_dialog_content = "...",
  ui_story_5084_50841102_109_dialog_content = "Oh, que todo o sangue pecaminoso escorra de mim... Eu nunca mais orarei pela redenção do Senhor...",
  ui_story_5084_50841102_110_dialog_content = "Eu sou um pecador... Pecados imperdoáveis...",
  ui_story_5084_50841102_111_dialog_content = "Sou um monstro que traz a ruína para todos, até mesmo aqui.",
  ui_story_5084_50841102_112_dialog_content = "Na minha pressa para chegar ao Advento da Verdade, eu decepcionei a costureira e sua filha.",
  ui_story_5084_50841102_113_dialog_content = "Eles perderam a oportunidade de ganhar a vida porque me conheceram...",
  ui_story_5084_50841102_114_dialog_content = "Essas pessoas me viram por completo, não aprovaram minha iniciação e queriam me matar em vez disso...",
  ui_story_5084_50841102_115_dialog_content = "Não sou um iniciado... Eu sou o culpado pelo problema entre meu mentor e a Ordem.",
  ui_story_5084_50841102_116_dialog_content = "Onde quer que eu vá, sou rejeitado...",
  ui_story_5084_50841102_117_dialog_content = "Aghhhh!",
  ui_story_5084_50841102_118_dialog_content = "Minhas mãos e pés estão ficando dormentes... O frio que acabei de sentir agora é um calor que estava me faltando...",
  ui_story_5084_50841102_119_dialog_content = "Pode até ser...",
  ui_story_5084_50841102_120_dialog_content = "Eu morreria em silêncio com meus pecados. Sem mais problemas para o mundo.",
  ui_story_5084_50841102_121_dialog_content = "Eu...",
  ui_story_5084_50841102_122_dialog_content = "Estou ponderando se não me fiz claro.",
  ui_story_5084_50841102_123_dialog_content = "...?",
  ui_story_5084_50841102_124_dialog_content = "Por que você odeia tanto um presente tão maravilhoso como o Sangue Raro?",
  ui_story_5084_50841102_125_dialog_content = "Mentor? Meu mentor! Você está bem!",
  ui_story_5084_50841102_126_dialog_content = "Não se mova. Deixe-me dar uma olhada na sua ferida.",
  ui_story_5084_50841102_127_dialog_content = "Fui eu quem você encontrou, mas não o original ou o eu presente.",
  ui_story_5084_50841102_128_dialog_content = "Tenho observado os eventos o tempo todo e ainda não consigo descobrir do que você é culpado.",
  ui_story_5084_50841102_129_dialog_content = "Tenho certeza que você pode dizer que tenho monstros em mim...",
  ui_story_5084_50841102_130_dialog_content = "Monstros? Até o eu do passado poderia reconhecer o quão assustadoramente poderoso você é e que está destinado a estar com a True Order.",
  ui_story_5084_50841102_131_dialog_content = "Você deveria saber que o futuro que vejo para a Ordem é uma congregação dos excêntricos, porém graciosos, sensatos, porém sábios.",
  ui_story_5084_50841102_132_dialog_content = "Enquanto você continuar descobrindo sua própria singularidade, o tempo o levará ao lugar certo e às pessoas certas.",
  ui_story_5084_50841102_133_dialog_content = "Eu te disse, você está aprendendo comigo. Tudo o que você experimentou também faz parte desse processo.",
  ui_story_5084_50841102_134_dialog_content = "Vejo que você não me levou a sério e tentou se matar por culpa.",
  ui_story_5084_50841102_135_dialog_content = "Castigue-me, por favor... Eu não segui o que prometi a você, meu mentor...",
  ui_story_5084_50841102_136_dialog_content = "Está tudo bem. Você foi humilhado, o que fez você se desviar do curso. Não é sua culpa.",
  ui_story_5084_50841102_137_dialog_content = "Mas agora que você chegou ao lugar certo, deve brilhar com suas habilidades únicas.",
  ui_story_5084_50841102_138_dialog_content = "Eu...?",
  ui_story_5084_50841102_139_dialog_content = "Pense bem. Deixando todos os outros de lado, o Sangue Raro tentou te machucar em algum momento?",
  ui_story_5084_50841102_140_dialog_content = "...",
  ui_story_5084_50841102_141_dialog_content = "A abundância que faz os privilegiados caírem em desgraça é talvez o que salvará os deslocados.",
  ui_story_5084_50841102_142_dialog_content = "É você quem tem danificado sua alma com os pecados dos outros, ignorando assim a própria coisa que tenta salvar você e eles.",
  ui_story_5084_50841102_143_dialog_content = "Por que você não acreditaria que o Sangue Raro poderia matar monstros e salvar os outros?",
  ui_story_5084_50841102_144_dialog_content = "Eles vão me evitar... desgostar de mim...",
  ui_story_5084_50841102_145_dialog_content = "Eles de novo... Prestem atenção, essa ideia pertence ao passado. Não caia nisso nunca mais.",
  ui_story_5084_50841102_146_dialog_content = "Para citar você, \"Farei qualquer coisa para me purificar dos pecados.\" O primeiro passo, então, é acreditar que você não tem pecado.",
  ui_story_5084_50841102_147_dialog_content = "Você pode fazer isso?",
  ui_story_5084_50841102_148_dialog_content = "Sr. Wilhelm...",
  ui_story_5084_50841102_149_dialog_content = "Sim, eu sei que você é definitivamente inteligente o suficiente para entender isso.",
  ui_story_5084_50841102_150_dialog_content = "Siga-me de volta para minha residência. É perfeitamente isolada.",
  ui_story_5084_50841102_151_dialog_content = "A partir daí, você pode alcançar muitas cidades para procurar e ajudar ovelhas perdidas.",
  ui_story_5084_50841102_152_dialog_content = "Salve-os com seu poder. Guie-os para o louvor do Sangue Raro.",
  ui_story_5084_50841102_153_dialog_content = "O Sangue Raro é abençoado pela Verdade. Com o tempo, você será capaz de entendê-lo através da meditação.",
  ui_story_5084_50841102_154_dialog_content = "Eu sei...",
  ui_story_5084_50841102_155_dialog_content = "Assim, tenho vagado pelos últimos três anos, controlando meu temperamento e ouvindo o que os outros dizem.",
  ui_story_5084_50841102_156_dialog_content = "Percebi que meu Sangue Raro mudou lentamente após curar a dor dos outros.",
  ui_story_5084_50841102_157_dialog_content = "Mas não foi até eu ajudar a costureira e sua filha há um momento atrás que percebi que os três anos foram bem gastos.",
  ui_story_5084_50841102_158_dialog_content = "Em todos esses anos com a True Order, eu não ouviria e simplesmente reiteraria meu arrependimento.",
  ui_story_5084_50841102_159_dialog_content = "Foi meu mentor que descobriu a raiz dos meus pecados. Eu estava ocupado demais falando para ouvir a Verdade.",
  ui_story_5084_50841102_160_dialog_content = "Minhas palavras negativas moldaram meus pensamentos e aprofundaram minha culpa...",
  ui_story_5084_50841102_161_dialog_content = "Eu não sabia o que realmente era A Verdade. É por isso que ela se recusou a se manifestar em mim.",
  ui_story_5084_50841102_162_dialog_content = "Agora percebo que a Verdade faz parte da minha fé desde sempre.",
  ui_story_5084_50841102_163_dialog_content = "Como a dor, a Verdade nunca mostrou preconceito em relação a ninguém.",
  ui_story_5084_50841102_164_dialog_content = "O que quer que eu tenha perdido, eu deveria perder. O que quer que eu tenha ganhado, eu deveria ganhar.",
  ui_story_5084_50841102_165_dialog_content = "Deve-se ter cometido um pecado para se arrepender. As bênçãos dos discípulos me permitiram ser ungido pelo Sangue Sagrado.",
  ui_story_5084_50841102_166_dialog_content = "Para ser honesto, não entendo metade do que você disse, Sr. Nails...",
  ui_story_5084_50841102_167_dialog_content = "Mas me sinto confortado pelo seu comportamento, como se eu tivesse acabado de tomar um banho quente.",
  ui_story_5084_50841102_168_dialog_content = "Foi meu mentor que me fez acreditar que o Sangue Raro não é um pecado, mas sagrado, porque o Senhor da Verdade está comigo em todos os momentos.",
  ui_story_5084_50841102_169_dialog_content = "Senhora Victoria ficará satisfeita em conhecer as mudanças em você.",
  ui_story_5084_50841102_170_dialog_content = "Mas eu não sei como as coisas estão indo com ela.",
  ui_story_5084_50841102_171_dialog_content = "Acredito na Senhora Victoria! Mais importante, acredito que posso ser de grande ajuda para ela!",
  ui_story_5084_50841102_172_dialog_content = "Meu mentor colocou meu treinamento em pausa. Preciso fazer algo importante para a True Order com meu poder.",
  ui_story_5084_50841102_173_dialog_content = "Venha, quero trazer minha alegria para a Senhora Victoria e também mais discípulos.",
  ui_story_5084_50841201_1_dialog_content = "Mesmo que ninguém mais ande no meu trem novamente, prometo que vou convencer o Pai a levá-lo em uma viagem para Astra.",
  ui_story_5084_50841201_2_dialog_content = "<color=#e8d9bb>Splat, splat....</color>",
  ui_story_5084_50841201_3_dialog_content = "Espere, deixe-me fechar a janela.",
  ui_story_5084_50841201_4_dialog_content = "Nossa!",
  ui_story_5084_50841201_5_dialog_content = "<color=#e8d9bb>Bata!</color>",
  ui_story_5084_50841201_6_dialog_content = "Isso é estranho. Esses vermes repugnantes têm aparecido por aqui ultimamente...",
  ui_story_5084_50841201_7_dialog_content = "Mas o Pai só me disse para fechar as janelas e nada mais. Eu nem mesmo sei onde ele está agora.",
  ui_story_5084_50841201_8_dialog_content = "<color=#e8d9bb>A lua de sangue pairava alta sobre a Cidade Varaki como um relógio eterno, soando para o Advento da Verdade à meia-noite.</color>",
  ui_story_5084_50841201_9_dialog_content = "Isso é simplesmente surreal. Por que isso não pode acontecer todos os dias da minha vida...?",
  ui_story_5084_50841201_10_dialog_content = "Você está se referindo à nomeação de um novo líder para a True Order? Há menções de alguém sendo morto não faz muito tempo.",
  ui_story_5084_50841201_11_dialog_content = "Não é incomum a liderança mudar. Mas estou mais preocupado com a forma como aqueles no comando sempre excluem todos que não são de herança Varaki.",
  ui_story_5084_50841201_12_dialog_content = "Talvez o brilho desta lua de sangue brilhe apenas sobre aquela linhagem.",
  ui_story_5084_50841201_13_dialog_content = "Nunca cabe a nós chegar ao caixão no Salão da Verdade e ouvir a palestra do Senhor.",
  ui_story_5084_50841201_14_dialog_content = "Não caia na teoria da conspiração da linhagem. O Senhor rejeitou a filha mais velha dos Varakis três anos atrás.",
  ui_story_5084_50841201_15_dialog_content = "E escolheu outro seguidor em reclusão. Ele agora é um santo e redime os outros através do poder do Senhor.",
  ui_story_5084_50841201_16_dialog_content = "Dizem que ele não é daqui. Talvez A Verdade possa se proliferar fora da Cidade Varaki.",
  ui_story_5084_50841201_17_dialog_content = "Isso é realmente motivador. O chefe da cidade parece estar enfrentando uma reforma também.",
  ui_story_5084_50841201_18_dialog_content = "Se for o Porfírio esta noite, A Verdadeira Ordem vai ter dificuldades pela frente...",
  ui_story_5084_50841201_19_dialog_content = "O mundo está mudando, e a Verdade também. May abençoe nossa casa.",
  ui_story_5084_50841201_20_dialog_content = "Ainda não há sinais da Senhora Victoria e PlayerName... Espero que nada aconteça com eles.",
  ui_story_5084_50841201_21_dialog_content = "A Senhora Victoria nunca voltou atrás em suas palavras. Talvez esteja muito lotado agora, e ela mostrará isso depois que os discípulos se dispersarem.",
  ui_story_5084_50841201_22_dialog_content = "Não. Dada a situação, eu não acho que ela tenha algum motivo para se esconder.",
  ui_story_5084_50841201_23_dialog_content = "PlayerName também está presente e deve se destacar no público.",
  ui_story_5084_50841201_24_dialog_content = "O Sr. Faust está certo! Tenho a sensação de que vou testemunhar um milagre da True Order esta noite!",
  ui_story_5084_50841201_25_dialog_content = "Que história eu terei para Lenore!",
  ui_story_5084_50841201_26_dialog_content = "Apesar da recente onda de assassinatos na cidade, os seguidores ainda comparecem ao evento.",
  ui_story_5084_50841201_27_dialog_content = "Acho que essa é a tradição da Verdadeira Ordem se estendendo até o Calendário Matutino de 2000 para você.",
  ui_story_5084_50841201_28_dialog_content = "Vou permanecer vigilante e garantir que todos os discípulos permaneçam seguros durante a cerimônia.",
  ui_story_5084_50841201_29_dialog_content = "Faz muito tempo, e a Senhora Victoria ainda não está aqui.",
  ui_story_5084_50841201_30_dialog_content = "Você viu que a garota Varaki está na cerimônia?",
  ui_story_5084_50841201_31_dialog_content = "Sim, e usando um traje maravilhoso também... Isso é uma violação das regras da True Order!",
  ui_story_5084_50841201_32_dialog_content = "(Ela voltou e trocou de roupa? Onde ela está?)",
  ui_story_5084_50841201_33_dialog_content = "Sempre há problemas entre ela e seu tio. É normal para ela não seguir as regras.",
  ui_story_5084_50841201_34_dialog_content = "Os Varakis vão mudar de líder?",
  ui_story_5084_50841201_35_dialog_content = "Não pode ser... Ouvi dizer que a Senhora Victoria voltou especificamente para liderar a Verdadeira Ordem.",
  ui_story_5084_50841201_36_dialog_content = "Sério? Mas no Advento da Verdade três anos atrás, ela não...",
  ui_story_5084_50841201_37_dialog_content = "Quem sabe? Foi ela quem entrou no caixão, não nós.",
  ui_story_5084_50841201_38_dialog_content = "Não consigo explicar isso, mas já se passaram centenas de anos e me sinto mais confortável com um Varaki liderando a True Order.",
  ui_story_5084_50841201_39_dialog_content = "Desculpe mantê-lo esperando.",
  ui_story_5084_50841201_40_dialog_content = "Uau... Você fez questão de trocar para algo adequado ao evento?",
  ui_story_5084_50841201_41_dialog_content = "Não exatamente. Este vestido é um presente daqueles que ainda sentem falta de Varakis e sabem que estou na cidade.",
  ui_story_5084_50841201_42_dialog_content = "Algo tão refinado não pode ser feito por uma ou duas pessoas em tão pouco tempo.",
  ui_story_5084_50841201_43_dialog_content = "Talvez o grupo envolvido esteja tentando expressar sua objeção ao poderoso cabala de líderes através disso.",
  ui_story_5084_50841201_44_dialog_content = "Então, para apreciar o esforço deles e mostrar que você tem o que é preciso para liderar a Ordem...",
  ui_story_5084_50841201_45_dialog_content = "Você tem que usar isso para a cerimônia de hoje à noite?",
  ui_story_5084_50841201_46_dialog_content = "A autoridade não tem nada a ver com trajes. Posso exibir meu poder em qualquer fantasia, antiga ou nova.",
  ui_story_5084_50841201_47_dialog_content = "Mas mudanças emocionantes são exatamente o que esta cidade histórica tem perdido.",
  ui_story_5084_50841201_48_dialog_content = "Como a Bíblia Sangrenta, o anel e a lua de sangue, são todos meios de marcar os momentos que as pessoas acreditavam ser importantes.",
  ui_story_5084_50841201_49_dialog_content = "Se os líderes odeiam tais mudanças salientes, então é exatamente isso que vou mostrar a eles.",
  ui_story_5084_50841201_50_dialog_content = "Pois para eles, uma mulher adotando uma imagem extravagante está dizendo adeus ao seu passado submisso.",
  ui_story_5084_50841201_51_dialog_content = "Sim. Eu só quero dizer que a roupa cai como uma luva em você.",
  ui_story_5084_50841201_52_dialog_content = "PlayerName! PlayerName!",
  ui_story_5084_50841201_53_dialog_content = "É você!",
  ui_story_5084_50841201_54_dialog_content = "Sim, é a Senhora Victoria, alguém que eu posso identificar em qualquer público!",
  ui_story_5084_50841201_55_dialog_content = "Não pude acreditar que era você quando te vi de longe.",
  ui_story_5084_50841201_56_dialog_content = "Como eu pareço?",
  ui_story_5084_50841201_57_dialog_content = "É a Senhora Victoria! E mais deslumbrante do que antes!",
  ui_story_5084_50841201_58_dialog_content = "Parece que está tudo bem com você, Senhora Victoria. Parabéns.",
  ui_story_5084_50841201_59_dialog_content = "Nails passou por grandes mudanças, eu vejo.",
  ui_story_5084_50841201_60_dialog_content = "Faz muito tempo, Senhora Victoria! Eu atribuo os resultados ao meu mentor...",
  ui_story_5084_50841201_61_dialog_content = "Eu tenho tanto que quero dizer a você!",
  ui_story_5084_50841201_62_dialog_content = "Sim, eu te vi na rua. Estou ansioso para ouvir isso mais tarde.",
  ui_story_5084_50841201_63_dialog_content = "Está quase na hora.",
  ui_story_5084_50841201_64_dialog_content = "Mas acabamos de ver mortos-vivos ferindo pessoas, Senhora Victoria...",
  ui_story_5084_50841201_65_dialog_content = "Agora sei do que se trata o recente boato na cidade sobre o Cavaleiro Negro.",
  ui_story_5084_50841201_66_dialog_content = "Venham, seguidores na rua. Wilhelm garantirá que eles estejam seguros.",
  ui_story_5084_50841201_67_dialog_content = "A True Order deve mostrar sua força esta noite. Siga-me até a igreja.",
  ui_story_5084_50841201_68_dialog_content = "Sim!",
  ui_story_5084_50841201_69_dialog_content = "May A Verdade abençoe para sempre A Ordem Verdadeira.",
  ui_story_5084_50841201_70_dialog_content = "<color=#e8d9bb>Ranger!</color>",
  ui_story_5084_50841201_71_dialog_content = "Está...",
  ui_story_5084_50841201_72_dialog_content = "Todos no chão como se...",
  ui_story_5084_50841201_73_dialog_content = "...",
  ui_story_5084_50841201_74_dialog_content = "Eles pararam de respirar, Senhora Victoria.",
  ui_story_5084_50841201_75_dialog_content = "...!",
  ui_story_5084_50841201_76_dialog_content = "Deixe-me tentar ajudá-los... Estou disposto a suportar a dor por eles.",
  ui_story_5084_50841201_77_dialog_content = "Ei, vejo que a chefe da família Varaki e seus lacaios finalmente chegaram.",
  ui_story_5084_50841201_78_dialog_content = "Esta é uma celebração da True Order, como eu poderia não estar presente?",
  ui_story_5084_50841201_79_dialog_content = "Lady Victoria...",
  ui_story_5084_50841201_80_dialog_content = "...",
  ui_story_5084_50841201_81_dialog_content = "Gram está ferido em muitos lugares...",
  ui_story_5084_50841201_82_dialog_content = "Essa é a consequência de me trair.",
  ui_story_5084_50841201_83_dialog_content = "O que você fizer está bom... só não machuque Charon e sua esposa...",
  ui_story_5084_50841201_84_dialog_content = "Ferindo pessoas no Salão da Verdade...",
  ui_story_5084_50841201_85_dialog_content = "Fique onde está, Varaki!",
  ui_story_5084_50841201_86_dialog_content = "Você...!",
  ui_story_5084_50841201_87_dialog_content = "Fique atrás de mim, May.",
  ui_story_5084_50841201_88_dialog_content = "Você deve ter esquecido muitas das regras para vampiros. Vou deixar Abraham explicar para você quais delas você violou...",
  ui_story_5084_50841201_89_dialog_content = "Você não deveria ter voltado, Victoria...",
  ui_story_5084_50841201_90_dialog_content = "Nem mesmo você pode fazer algo a respeito, agora que o ritual acabou. Todos os \"sacrifícios\" ao Senhor foram feitos.",
  ui_story_5084_50841201_91_dialog_content = "Agora, estou apenas ensinando meus pequenos a não desperdiçar comida.",
  ui_story_5084_50841201_92_dialog_content = "Aurorianos são um presente do Senhor da Verdade. Você acha que eles são comida?",
  ui_story_5084_50841201_93_dialog_content = "Oh, senhora dos Varaki, não envia seu povo para buscar sangue fresco para você quando também sente sede no meio da noite?",
  ui_story_5084_50841201_94_dialog_content = "Eu mesmo não desperdicei uma gota do sacrifício que me pertencia.",
  ui_story_5084_50841201_95_dialog_content = "Mas o mesmo não pode ser dito sobre Abraham, que não só desperdiçou sua parte, mas também mentiu para mim!",
  ui_story_5084_50841201_96_dialog_content = "!",
  ui_story_5084_50841201_97_dialog_content = "Pare com isso, Porfirio... Pare!",
  ui_story_5084_50841201_98_dialog_content = "Onde está Wilhelm?!",
  ui_story_5084_50841201_99_dialog_content = "Pare, David Porfirio!",
  ui_story_5084_50841201_100_dialog_content = "Então, você dá as ordens agora?",
  ui_story_5084_50841201_101_dialog_content = "Traga-o aqui.",
  ui_story_5084_50841201_102_dialog_content = "Yes, Lady Victoria.",
  ui_story_5084_50841201_103_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5084_50841201_104_dialog_content = "O que você está fazendo, Vine?",
  ui_story_5084_50841201_105_dialog_content = "Estou apenas seguindo as ordens da Senhorita Varaki para entregar o caixão do desfile a você, Lord Porfirio.",
  ui_story_5084_50841201_106_dialog_content = "Não me diga que você acha que os restos ancestrais de Varaki me assustariam.",
  ui_story_5084_50841201_107_dialog_content = "Ou você está tentando fugir com o mesmo truque que Wilhelm Varaki usou?",
  ui_story_5084_50841201_108_dialog_content = "É Wilhelm no caixão.",
  ui_story_5084_50841201_109_dialog_content = "...?",
  ui_story_5084_50841201_110_dialog_content = "Você já o machucou sem piedade como está e ainda quer mais?",
  ui_story_5084_50841201_111_dialog_content = "Bem, estou no meu último fio de paciência...",
  ui_story_5084_50841201_112_dialog_content = "Depois que eu acabar com o sangue nesta garrafa, acho que terei que me alimentar de você.",
  ui_story_5084_50841201_113_dialog_content = "Aproxime-se e me diga que artimanhas você e Wilhelm estão tramando.",
  ui_story_5084_50841201_114_dialog_content = "Wilhelm está morto.",
  ui_story_5084_50841201_115_dialog_content = "Mentiroso!",
  ui_story_5084_50841201_116_dialog_content = "Cuidado, Victoria!",
  ui_story_5084_50841201_117_dialog_content = "Só por cima do meu cadáver!",
  ui_story_5084_50841201_118_dialog_content = "Isso não é novidade para alguém tentando construir um grupo em torno da Verdade, mas é raro para vocês lacaios protegerem seu superior assim.",
  ui_story_5084_50841201_119_dialog_content = "Não me tome por um tolo, no entanto. Eu vi vocês dois matando Viper e Gold Rush.",
  ui_story_5084_50841201_120_dialog_content = "Está assustado? Viper e Gold Rush, bem como todos vocês conspiradores, morrerão por sua espada.",
  ui_story_5084_50841201_121_dialog_content = "Então, independentemente de como você tenta atormentar, assassinar ou enterrar Wilhelm Varaki, você nunca pode matá-lo.",
  ui_story_5084_50841201_122_dialog_content = "Wilhelm... não está morto? Ele está vivo...?",
  ui_story_5084_50841201_123_dialog_content = "...",
  ui_story_5084_50841201_124_dialog_content = "Não morto... então Varaki poderia se tornar um espírito após morrer?",
  ui_story_5084_50841201_125_dialog_content = "Não existem espíritos no mundo! Os revenants só se tornaram o que eram depois de absorver o poder de Porfírio.",
  ui_story_5084_50841201_126_dialog_content = "Esse é o meu poder sobre os revenants... Único na história das casas de vampiros!",
  ui_story_5084_50841201_127_dialog_content = "Não brinque com isso, não é ressurreição. Nem pense.",
  ui_story_5084_50841201_128_dialog_content = "Você pensou que o poder detido pelos Varakis era apenas um dom ancestral usado para ver o futuro?",
  ui_story_5084_50841201_129_dialog_content = "...?",
  ui_story_5084_50841201_130_dialog_content = "Há apenas um momento, fiz um pacto com a Bíblia Sangrenta para sua aprovação como líder da Verdadeira Ordem.",
  ui_story_5084_50841201_131_dialog_content = "Os discípulos se curvam e retornam à Verdade com louvores piedosos...",
  ui_story_5084_50841201_132_dialog_content = "Eu deveria saber até agora que a seleção de Varaki é apenas um meio dos Varakis de manter o poder.",
  ui_story_5084_50841201_133_dialog_content = "Eu, Porfírio, deveria ter tido a honra há muito tempo e assumir o dever de devolver a Ordem aos seguidores.",
  ui_story_5084_50841201_134_dialog_content = "Os vampiros são os governantes do sangue e da noite. Por que eu deveria servir as criaturas da luz?",
  ui_story_5084_50841201_135_dialog_content = "O título deveria ser meu, e eu dominarei o povo de acordo com o que os ancestrais queriam. Isso é o que a Bíblia Sangrenta me revelou!",
  ui_story_5084_50841301_1_dialog_content = "<color=#e8d9bb>A luta feroz e sem sentido levou a um caixão derrubado para todos os presentes testemunharem...</color>",
  ui_story_5084_50841301_2_dialog_content = "<color=#e8d9bb>Uma nova Bíblia Sangrenta pousando aos pés de Victoria... como destinado.</color>",
  ui_story_5084_50841301_3_dialog_content = "A Verdade gostaria de terminar de pavimentar o caminho para a redenção, e aparentemente prefere me usar como seu intermediário.",
  ui_story_5084_50841301_4_dialog_content = "Códice da Calamidade, manifeste-se!",
  ui_story_5084_50841301_5_dialog_content = "...",
  ui_story_5084_50841301_6_dialog_content = "O que isso deveria ser?",
  ui_story_5084_50841301_7_dialog_content = "O Códice profético ofereceu-lhe vislumbres do futuro, mas você falhou em aproveitar isso enquanto tropeçava como um bebê aprendendo a andar.",
  ui_story_5084_50841301_8_dialog_content = "Este Códice, batizado no Rio Prístino, sabe tudo... É onisciente.",
  ui_story_5084_50841301_9_dialog_content = "O novo capítulo foi revelado, e eu vou virar a página!",
  ui_story_5084_50841301_10_dialog_content = "Gostaria de testemunhar suas revelações de quando você nasceu, quando morrerá e quando se arrependerá?",
  ui_story_5084_50841301_11_dialog_content = "...!",
  ui_story_5084_50841301_12_dialog_content = "O resto de vocês, líderes de clãs que se consorciam com Porfírio, ouçam.",
  ui_story_5084_50841301_13_dialog_content = "O mestre da terceira das doze Grandes Casas, Porifiro..",
  ui_story_5084_50841301_14_dialog_content = "Caiu em uma sede de sangue sob a lua de sangue, assassinou inúmeros discípulos, bebeu seu sangue e controlou os mortos através de uma herança de família, o Tubo Dourado.",
  ui_story_5084_50841301_15_dialog_content = "Ele conspirou com o líder da décima terceira Grande Casa abolida da Ordem para libertar uma entidade maligna em Cidade Varaki e massacrar seguidores.",
  ui_story_5084_50841301_16_dialog_content = "Aquela criança abandonada...?",
  ui_story_5084_50841301_17_dialog_content = "O chefe da décima terceira casa procurou onde o Senhor da Verdade desceu na Zona Escura...",
  ui_story_5084_50841301_18_dialog_content = "Então levou um falso deus à cidade, atacou discípulos e sabotou a cerimônia do Senhor.",
  ui_story_5084_50841301_19_dialog_content = "David Porfirio criou e aproveitou a oportunidade para drenar sangue dos seguidores feridos.",
  ui_story_5084_50841301_20_dialog_content = "É essa a perspectiva que você quer que lidere todos vocês e a Ordem?",
  ui_story_5084_50841301_21_dialog_content = "...",
  ui_story_5084_50841301_22_dialog_content = "Pare com toda essa bobagem!",
  ui_story_5084_50841301_23_dialog_content = "Pelo poder do <color=#FFB400>Anel de Varaki</color>, mostre sua <color=#FFB400>verdadeira natureza</color>!",
  ui_story_5084_50841301_24_dialog_content = "—!",
  ui_story_5084_50841301_25_dialog_content = "Pensei que me associar à décima terceira casa e ingerir o sangue dos apóstolos aumentaria meu poder...",
  ui_story_5084_50841301_26_dialog_content = "O restante dos governantes recebeu a bênção do Senhor e mudou para outra alternativa.",
  ui_story_5084_50841301_27_dialog_content = "Exceto eu... Minha sede de sangue só aumentou. Agora, preciso contar com este frasco de sangue flutuante apenas para me manter minimamente.",
  ui_story_5084_50841301_28_dialog_content = "Aparentemente, você não percebe que o chefe da décima terceira casa nunca sentiu que qualquer coisa disso está no pacto entre vocês.",
  ui_story_5084_50841301_29_dialog_content = "Sacrificar você não é diferente de sacrificar todas as criaturas para ela. Ela estava apenas usando você.",
  ui_story_5084_50841301_30_dialog_content = "<color=#FFB400>Ela</color> se juntou ao Eclipse e se tornou uma das <color=#FFB400>fantasmas</color>. Você achou que poderia enganá-la?",
  ui_story_5084_50841301_31_dialog_content = "Cale a boca!",
  ui_story_5084_50841301_32_dialog_content = "Você, Victoria Varaki... Como é possível para você me controlar com o anel?",
  ui_story_5084_50841301_33_dialog_content = "Não, isso não pode ser... Isso não é como o Anel de Varaki agiu antes.",
  ui_story_5084_50841301_34_dialog_content = "Eu dominei e alinhei com todos os ancestrais de Varaki.",
  ui_story_5084_50841301_35_dialog_content = "O que você está enfrentando é o poder combinado do Clã Varaki. Confesse seus pecados agora!",
  ui_story_5084_50841301_36_dialog_content = "Heh, eu...",
  ui_story_5084_50841301_37_dialog_content = "Eu matei Wilhelm!",
  ui_story_5084_50841301_38_dialog_content = "Mas eu fiz isso para livrar a Verdadeira Ordem do verdadeiro obstáculo!",
  ui_story_5084_50841301_39_dialog_content = "Como poderia um segundo filho distorcido de Varaki, que viveu em reclusão e prejudicou seu irmão, liderar a Ordem?",
  ui_story_5084_50841301_40_dialog_content = "Wilhelm não fez mal a ninguém!",
  ui_story_5084_50841301_41_dialog_content = "Não é seu lugar de falar!",
  ui_story_5084_50841301_42_dialog_content = "—!",
  ui_story_5084_50841301_43_dialog_content = "A Bíblia Sangrenta é uma relíquia Varaki. Ela concede poder ao portador e me liberta do medo.",
  ui_story_5084_50841301_44_dialog_content = "Mesmo quando matei para saciar minha sede de sangue, ainda assim aprovou e me deu poder.",
  ui_story_5084_50841301_45_dialog_content = "Ninguém na True Order poderia esperar desafiar-me!",
  ui_story_5084_50841301_46_dialog_content = "Bíblia Sangrenta, por favor, conceda-me o poder para erradicar Varakis!",
  ui_story_5084_50841301_47_dialog_content = "...",
  ui_story_5084_50841301_48_dialog_content = "Bíblia Sangrenta...!",
  ui_story_5084_50841301_49_dialog_content = "Você nunca entendeu o motivo pelo qual os Varakis se tornaram líderes da Ordem.",
  ui_story_5084_50841301_50_dialog_content = "Jamais prejudicaríamos alguém com a Bíblia Sangrenta.",
  ui_story_5084_50841301_51_dialog_content = "Muito pelo contrário, foi a Bíblia que sugou o sangue de Varaki em troca de revelar o futuro.",
  ui_story_5084_50841301_52_dialog_content = "...?",
  ui_story_5084_50841301_53_dialog_content = "É o mesmo, seja os antepassados, meus pais, Wilhelm e até mesmo eu.",
  ui_story_5084_50841301_54_dialog_content = "Essas relíquias mantiveram a vontade de cada chefe da casa, seja ela racional ou não.",
  ui_story_5084_50841301_55_dialog_content = "Aqueles que fazem um pacto devem ter a determinação para resistir aos sussurros tentadores para alcançar a Verdade...",
  ui_story_5084_50841301_56_dialog_content = "E interprete as revelações do Senhor da Verdade em um nível superior!",
  ui_story_5084_50841301_57_dialog_content = "Quais revelações você vislumbrou?",
  ui_story_5084_50841301_58_dialog_content = "...",
  ui_story_5084_50841301_59_dialog_content = "O que você vai fazer...?!",
  ui_story_5084_50841301_60_dialog_content = "Você se esqueceu da reunião?",
  ui_story_5084_50841301_61_dialog_content = "What revelation did you receive?",
  ui_story_5084_50841301_62_dialog_content = "<color=#FF0000>To purge the order.</color>",
  ui_story_5084_50841301_63_dialog_content = "Você...!",
  ui_story_5084_50841301_64_dialog_content = "Discípulos da Verdade, recitem o mantra comigo!",
  ui_story_5084_50841301_65_dialog_content = "Eu, Nails, vou recitar o mantra com a minha vida!",
  ui_story_5084_50841301_66_dialog_content = "Eu, May, vou recitar o mantra com o Sr. Beau!",
  ui_story_5084_50841301_67_dialog_content = "O discípulo Faust deve recitar o mantra com a Senhora Victoria!",
  ui_story_5084_50841301_68_dialog_content = "Ceda, David.",
  ui_story_5084_50841301_69_dialog_content = "Covarde! O chefe da Casa Porfirio deve liderar a Verdadeira Ordem!",
  ui_story_5084_50841301_70_dialog_content = "Adeus.",
  ui_story_5084_50841301_71_dialog_content = "Todos vocês me prometeram!",
  ui_story_5084_50841301_72_dialog_content = "Chega. Nosso acordo expira na lua de sangue. Vejo que fiz a aposta certa! Divirta-se bebendo sangue.",
  ui_story_5084_50841301_73_dialog_content = "Meu morto-vivo!",
  ui_story_5084_50841301_74_dialog_content = "Soberanos de todas as casas na Ordem, vocês são convidados a presenciar—",
  ui_story_5084_50841301_75_dialog_content = "...",
  ui_story_5084_50841301_76_dialog_content = "O Espírito da Verdade percorrendo todos os discípulos. Por favor, levantem-se!",
  ui_story_5084_50841301_77_dialog_content = "Ouça a Verdade comigo!",
  ui_story_5084_50841301_78_dialog_content = "O fluxo ondulante que dançou comigo rompeu o vazio e emergiu aqui.",
  ui_story_5084_50841301_79_dialog_content = "Eu sou a Runa detida pelo Senhor da Verdade, aguardando sua chegada em solo sagrado.",
  ui_story_5084_50841301_80_dialog_content = "Sou o Arauto da Luz, Condutor da Escuridão! May A morte se manifesta no Reino da Imortalidade.",
  ui_story_5084_50841301_81_dialog_content = "Todo-poderoso Senhor da Verdade, por favor, conceda poderes divinos através das revelações do sangue de Varaki em mim!",
  ui_story_5084_50841301_82_dialog_content = "O Sangue Sagrado tomará forma... Eu ouvirei todas as confissões!",
  ui_story_5084_50841301_83_dialog_content = "A videira foi revivida. May o Senhor venha até mim!",
  ui_story_5084_50841301_84_dialog_content = "Venha até mim neste verdadeiro pesadelo! Eu irei liberar poderes ancestrais!",
  ui_story_5084_50841301_85_dialog_content = "Empreste-nos seu poder, Navegador da Verdade Universal que serve como a ponte para o Rio Prístino!",
  ui_story_5084_50841301_86_dialog_content = "O que você quer dizer com Verdade Universal e ponte para o Rio Prístino?",
  ui_story_5084_50841301_87_dialog_content = "Claro, eu vou ajudar!",
  ui_story_5084_50841301_88_dialog_content = "Ele verá sua contribuição. O pacto foi concluído. Aguarde a chegada do Deus comigo!",
  ui_story_5084_50841302_1_dialog_content = "Você veio da mesma linhagem sedenta de sangue, suja, amaldiçoada desde o nascimento como eu...",
  ui_story_5084_50841302_2_dialog_content = "O que fez de você, Varakis, merecedor de monopolizar a posição?",
  ui_story_5084_50841302_3_dialog_content = "A resposta deve ser clara para você quando fizer a pergunta.",
  ui_story_5084_50841302_4_dialog_content = "Varaki...",
  ui_story_5084_50841302_5_dialog_content = "A sede por sangue, imortalidade, maldição... Vampires devem pagar um certo preço pelo poder.",
  ui_story_5084_50841302_6_dialog_content = "Essa noção está comigo e me moldou desde que nasci.",
  ui_story_5084_50841302_7_dialog_content = "Mas recentemente, cheguei à conclusão iluminada de que tudo o que vivi não é o custo, mas o que me torna merecedor do presente e da orientação que recebo.",
  ui_story_5084_50841302_8_dialog_content = "O Senhor da Verdade escolheu e nos concedeu o poder de liderar mudanças e novas eras.",
  ui_story_5084_50841302_9_dialog_content = "Qualquer um dos Eclipsitas, armas de uma antiga civilização, ou falsos deuses poderiam representar ameaças para a sobrevivência dos Aurorianos.",
  ui_story_5084_50841302_10_dialog_content = "Deixe de lado os aurorianos maléficos e heréticos como você.",
  ui_story_5084_50841302_11_dialog_content = "Sem sair da Cidade Varaki para observar os rios ou as estrelas...",
  ui_story_5084_50841302_12_dialog_content = "Sem ver como este abençoado planeta de Eoria opera sob a vigilância do Senhor...",
  ui_story_5084_50841302_13_dialog_content = "Você nunca entenderá como a estrela solitária caiu, pois isso aconteceu muitas vezes.",
  ui_story_5084_50841302_14_dialog_content = "Quando os Aurorians enfrentarem a extinção novamente, apenas o Varaki escolhido pelo Senhor pode prevenir a destruição de Eoria.",
  ui_story_5084_50841302_15_dialog_content = "A capacidade de reverter o medo do desconhecido através de maior equilíbrio é a base para os Escolhidos.",
  ui_story_5084_50841302_16_dialog_content = "David Porfirio, como um vampiro que recebeu a honra, mas falhou em compreender A Verdade, você deve devolver o poder que o Senhor lhe concedeu.",
  ui_story_5084_50841302_17_dialog_content = "Não tem nada a ver com entendimento ou a escolha do Senhor. Varakis são os únicos que os vampiros reconhecem.",
  ui_story_5084_50841302_18_dialog_content = "Porfírios começaram como descendentes dos Varakis...",
  ui_story_5084_50841302_19_dialog_content = "Mas meus antepassados perderam seus lugares devido às opressões de Varaki, impedindo-me subsequentemente de ganhar aprovação...",
  ui_story_5084_50841302_20_dialog_content = "Vários séculos depois, permanece o mesmo. Você não tem o direito de falar sobre iluminação.",
  ui_story_5084_50841302_21_dialog_content = "Você—e os Varakis—nunca vão escapar do destino dos vampiros.",
  ui_story_5084_50841302_22_dialog_content = "Haha... Hahaha...",
  ui_story_5084_50841302_23_dialog_content = "...",
  ui_story_5084_50841302_24_dialog_content = "Senhorita Varaki... Quero dizer, Senhora Victoria...",
  ui_story_5084_50841302_25_dialog_content = "Você realmente recebeu revelações do Senhor em suas viagens ao exterior?",
  ui_story_5084_50841302_26_dialog_content = "Sempre temos muitas relíquias antigas em nossa posse.",
  ui_story_5084_50841302_27_dialog_content = "Como podemos julgar o que veio dos sussurros e se somos dignos do poder concedido pelo Senhor da Verdade?",
  ui_story_5084_50841302_28_dialog_content = "A Ordem sempre foi conhecida pelos espíritos superiores dos vampiros, portanto, a capacidade de ressoar com as relíquias é uma dádiva.",
  ui_story_5084_50841302_29_dialog_content = "Mas ao longo dos anos, lutas pelo poder entre os chefes das casas e a complacência confundiram a mensagem nos relíquias passadas através das gerações.",
  ui_story_5084_50841302_30_dialog_content = "Para muitas das relíquias, só percebi que elas continham nada além de dor enlouquecedora e gritos quando estabeleci sintonia.",
  ui_story_5084_50841302_31_dialog_content = "O medo é a base para o equilíbrio entre os Aurorianos e os objetos.",
  ui_story_5084_50841302_32_dialog_content = "Todos os sucessores de Varaki andavam todas as noites com esse medo, fazendo com que seu corpo e mente se deteriorassem sob o fardo...",
  ui_story_5084_50841302_33_dialog_content = "É por isso que eu me debrucei sobre tomos e pergaminhos em busca de sabedoria e conhecimento auroriano para controlar nossos instintos inatos.",
  ui_story_5084_50841302_34_dialog_content = "Através do qual, consegui navegar pelas vozes e ao abraço do Senhor.",
  ui_story_5084_50841302_35_dialog_content = "Continuar a fazer perguntas e explorar, depois suprimir a fraqueza até que eles nos temam e se submetam, para mim, é o caminho.",
  ui_story_5084_50841302_36_dialog_content = "Estamos gratos pela percepção, Senhora Victoria.",
  ui_story_5084_50841302_37_dialog_content = "Mas devo dizer que isso não se aplica exclusivamente a vampiros.",
  ui_story_5084_50841302_38_dialog_content = "Em minha jornada, encontrei Aurorianos não vampíricos com habilidades desconhecidas para atrair objetos especiais.",
  ui_story_5084_50841302_39_dialog_content = "Pode ser apenas uma roda, um raio...",
  ui_story_5084_50841302_40_dialog_content = "Uma vinha, um pedaço de papel...",
  ui_story_5084_50841302_41_dialog_content = "Um animal de estimação, uma mala branca...",
  ui_story_5084_50841302_42_dialog_content = "Dependendo do proprietário, diferentes potenciais incríveis foram desbloqueados.",
  ui_story_5084_50841302_43_dialog_content = "Acredito que você não tenha visto sangue maleável que poderia matar Eclipsitas.",
  ui_story_5084_50841302_44_dialog_content = "Meus seguidores afirmam ter encontrado um discípulo capaz disso nas ruas antes.",
  ui_story_5084_50841302_45_dialog_content = "...",
  ui_story_5084_50841302_46_dialog_content = "Discípulos como esse permeiam o mundo. A Ordem deve se integrar às sociedades Aurorianas e propagar A Verdade, trazendo tal poder para o nosso meio.",
  ui_story_5084_50841302_47_dialog_content = "Outros que também receberam revelações existem, mas estão espalhados pelo mundo, sem perceber o que elas significam.",
  ui_story_5084_50841302_48_dialog_content = "Nós, como vampiros, devemos compilar as revelações para informar ao Senhor da Verdade que é hora de Sua chegada e conduzir os Aurorianos para o futuro.",
  ui_story_5084_50841302_49_dialog_content = "Se esse for o caso, aprovo a saída da cidade e a disseminação da Verdade entre os Aurorians.",
  ui_story_5084_50841302_50_dialog_content = "Construa seguidores e acumule influência...",
  ui_story_5084_50841302_51_dialog_content = "Mas como podemos levar a mensagem ao Senhor?",
  ui_story_5084_50841302_52_dialog_content = "Se eu te dissesse que existe um Navegador capaz de alcançar o Rio Prístino através de relíquias e até mesmo comandar essas mesmas relíquias...",
  ui_story_5084_50841302_53_dialog_content = "Você também não aguardaria ansiosamente o futuro da Ordem?",
  ui_story_5084_50841302_54_dialog_content = "Que Navegador?",
  ui_story_5084_50841302_55_dialog_content = "Ei, eu nunca disse que estava entrando na Ordem da Verdade!",
  ui_story_5084_50841302_56_dialog_content = "Passe-me o castiçal, Celestita.",
  ui_story_5084_50841302_57_dialog_content = "Hã? Mas tem tanta gente aqui...",
  ui_story_5084_50841302_58_dialog_content = "Entregue para mim.",
  ui_story_5084_50841302_59_dialog_content = "...",
  ui_story_5084_50841302_60_dialog_content = "Isto é... um Celestita, um aliado da Ordem.",
  ui_story_5084_50841302_61_dialog_content = "Uh, oi, pessoal.",
  ui_story_5084_50841302_62_dialog_content = "Ouvi falar dos Celestitas. Eles podiam pilotar Colossos e eram telepatas.",
  ui_story_5084_50841302_63_dialog_content = "Você esteve aqui todo esse tempo, Celestita?",
  ui_story_5084_50841302_64_dialog_content = "Bem, para ser preciso, estou por perto a maior parte do tempo, mas não me mostro por vários motivos.",
  ui_story_5084_50841302_65_dialog_content = "Telepático... Isso não é idêntico à habilidade do vampiro de ressoar?",
  ui_story_5084_50841302_66_dialog_content = "Não, não é o mesmo.",
  ui_story_5084_50841302_67_dialog_content = "Como mencionei, os vampiros se comunicam com relíquias através da linhagem.",
  ui_story_5084_50841302_68_dialog_content = "A telepatia dos Celestitas compartilha, na verdade, o poder possuído por vampiros de um nível superior, e esse mesmo poder também é a base para todos os Aurorians.",
  ui_story_5084_50841302_69_dialog_content = "O Rio Prístino?",
  ui_story_5084_50841302_70_dialog_content = "Oh meu! Você rastreou o Pergaminho Antigo, Senhora Victoria?",
  ui_story_5084_50841302_71_dialog_content = "Não. Ninguém tem o pergaminho ou sabe onde ele está.",
  ui_story_5084_50841302_72_dialog_content = "Mas o Rio Pristine por trás dos Pergaminhos Antigos aparentemente já foi visitado.",
  ui_story_5084_50841302_73_dialog_content = "Buscarei aquele local, então gostaria de confiar a cidade a todos vocês.",
  ui_story_5084_50841302_74_dialog_content = "Seguiremos suas palavras e o padrão que você estabeleceu.",
  ui_story_5084_50841302_75_dialog_content = "Sério? Alguém visitou o Rio Pristine?",
  ui_story_5084_50841302_76_dialog_content = "Cleves Abraham, você está ponderando se me conta a verdade sobre matar Wilhelm?",
  ui_story_5084_50841302_77_dialog_content = "...",
  ui_story_5084_50841302_78_dialog_content = "Estou aqui para pegar um objeto emprestado de você, Cleves.",
  ui_story_5084_50841302_79_dialog_content = "Faria a Caixa Preta?",
  ui_story_5084_50841302_80_dialog_content = "Sim.",
  ui_story_5084_50841302_81_dialog_content = "Você está levando a Bíblia Sangrenta?!",
  ui_story_5084_50841302_82_dialog_content = "É apenas uma questão de tempo antes do vampiro apreendê-lo da tumba.",
  ui_story_5084_50841302_83_dialog_content = "Ele não tem o direito de pegá-lo.",
  ui_story_5084_50841302_84_dialog_content = "Isso ocorre porque a sucessão de líderes Varaki deixou uma marca na mente dos governantes da casa.",
  ui_story_5084_50841302_85_dialog_content = "Mas mesmo agora, Victoria não percebeu o poder significativo que corre em suas veias.",
  ui_story_5084_50841302_86_dialog_content = "Adicione o fato de que minha história manchou a santidade dos Varakis, os governantes há muito tempo estão de olho na minha posição.",
  ui_story_5084_50841302_87_dialog_content = "Se eu não estiver mais por perto, eles certamente irão atrás de Victoria.",
  ui_story_5084_50841302_88_dialog_content = "E uma Verdadeira Ordem liderada por Porfírio certamente trará desastre ao mundo.",
  ui_story_5084_50841302_89_dialog_content = "Sobre isso, Wilhelm...",
  ui_story_5084_50841302_90_dialog_content = "Apenas quando a luz de uma lua de sangue for lançada sobre a hera na noite do Advento da Verdade é que o túmulo será aberto para os governantes da casa.",
  ui_story_5084_50841302_91_dialog_content = "Mas até lá será tarde demais. Discutimos as possibilidades em relação à Caixa Preta Faria.",
  ui_story_5084_50841302_92_dialog_content = "Talvez meu irmão tenha confiado o livro a você, seu amigo próximo, com a intenção de me deixar pegá-lo quando o momento fosse certo.",
  ui_story_5084_50841302_93_dialog_content = "...",
  ui_story_5084_50841302_94_dialog_content = "Por que a pausa grávida, Cleves?",
  ui_story_5084_50841302_95_dialog_content = "Wilhelm, supondo que a caixa possa abrir a tumba, é proibido pelo pacto comum de pegar o livro sem a presença de todos os governantes.",
  ui_story_5084_50841302_96_dialog_content = "Eu sei.",
  ui_story_5084_50841302_97_dialog_content = "E ainda assim você expressou completamente a decisão de quebrar o pacto para mim... O que você está pensando, Wilhelm?",
  ui_story_5084_50841302_98_dialog_content = "Quantos anos tem Victoria agora?",
  ui_story_5084_50841302_99_dialog_content = "Por que pergunta?",
  ui_story_5084_50841302_100_dialog_content = "Você tem cuidado dela por muitos anos. Aquele seu eu mais jovem, ambicioso e egoísta...",
  ui_story_5084_50841302_101_dialog_content = "Tornou-se um velho cuidando dos outros.",
  ui_story_5084_50841302_102_dialog_content = "Se você soubesse o quão bem Victoria e eu normalmente nos damos, provavelmente não diria isso.",
  ui_story_5084_50841302_103_dialog_content = "O que eu quero dizer é, você sabe por que eu me mudei para a Cidade Velha?",
  ui_story_5084_50841302_104_dialog_content = "Para Charon, sem dúvida.",
  ui_story_5084_50841302_105_dialog_content = "Sim, Wilhelm. A mãe de Charon e eu não queremos mais nos preocupar com a Ordem, muito menos deixar Charon se juntar a ela.",
  ui_story_5084_50841302_106_dialog_content = "Você recuou.",
  ui_story_5084_50841302_107_dialog_content = "Não, Wilhelm, eu dei um passo difícil adiante pelo bem de Charon.",
  ui_story_5084_50841302_108_dialog_content = "E se eu dissesse que você deve me dar a caixa para Charon e sua mãe ficarem longe de problemas?",
  ui_story_5084_50841302_109_dialog_content = "...",
  ui_story_5084_50841302_110_dialog_content = "A Ordem só pode se beneficiar quando a Bíblia está nas mãos de Varaki. Em todas as minhas memórias herdadas, esse é o único meio de trazer a reforma!",
  ui_story_5084_50841302_111_dialog_content = "Parece que você voltou aos seus caminhos ambiciosos.",
  ui_story_5084_50841302_112_dialog_content = "As vozes enlouquecedoras tentando corromper você não te puniram o suficiente?",
  ui_story_5084_50841302_113_dialog_content = "Isso mesmo, eu tenho ambições! Mas e daí?!",
  ui_story_5084_50841302_114_dialog_content = "Devo continuar me lamentando por ser ofuscado por um irmão talentoso e poderoso? Não! Nunca!",
  ui_story_5084_50841302_115_dialog_content = "...",
  ui_story_5084_50841302_116_dialog_content = "Desculpe, Cleves. Eu não quis dizer isso.",
  ui_story_5084_50841302_117_dialog_content = "O que eu quis dizer é que não estou fazendo isso por mim desta vez. É para Victoria.",
  ui_story_5084_50841302_118_dialog_content = "I cannot agree with that, Wilhelm...",
  ui_story_5084_50841302_119_dialog_content = "Do que você tem medo, exatamente? Não consegue ver que as coisas estão piorando?",
  ui_story_5084_50841302_120_dialog_content = "Porfirio and the house rulers have stopped following the rules after branching off the Varaki bloodline.",
  ui_story_5084_50841302_121_dialog_content = "Quão bom é para você seguir as regras sozinho?",
  ui_story_5084_50841302_122_dialog_content = "As regras para vampiros sempre foram uma algema. É um impedimento para a True Order agora, para você, para mim, para todos na cidade.",
  ui_story_5084_50841302_123_dialog_content = "Essa é a natureza dos vampiros, exceto que você é mais sortudo do que nós.",
  ui_story_5084_50841302_124_dialog_content = "Quando você decidiu se curvar ao destino também?",
  ui_story_5084_50841302_125_dialog_content = "Do not fault me for this, Wilhelm. I simply cannot deny what I know to be true...",
  ui_story_5084_50841302_126_dialog_content = "Essa chave só vai te trazer mal.",
  ui_story_5084_50841302_127_dialog_content = "Mas você também não planeja ajudar, né?",
  ui_story_5084_50841302_128_dialog_content = "...",
  ui_story_5084_50841302_129_dialog_content = "Está tudo bem, Cleves. Vou pensar em alguma coisa.",
  ui_story_5084_50841302_130_dialog_content = "Eu não dei a Caixa Preta para Wilhelm, e também não tinha a intenção de matá-lo naquele momento.",
  ui_story_5084_50841302_131_dialog_content = "Pensei que poderia apenas assistir os governantes... matá-lo na noite do Advento da Verdade.",
  ui_story_5084_50841302_132_dialog_content = "...",
  ui_story_5084_50841302_133_dialog_content = "<size=45>Aahhhh!</size>",
  ui_story_5084_50841302_134_dialog_content = "Haha, hahaha...",
  ui_story_5084_50841302_135_dialog_content = "Cleves...",
  ui_story_5084_50841302_136_dialog_content = "Desculpe, Wilhelm...",
  ui_story_5084_50841302_137_dialog_content = "Devo proporcionar a Charon uma folha em branco.",
  ui_story_5084_50841302_138_dialog_content = "Eu sei que você vai entender por cuidar de Victoria.",
  ui_story_5084_50841302_139_dialog_content = "Victoria...",
  ui_story_5084_50841302_140_dialog_content = "He...",
  ui_story_5084_50841302_141_dialog_content = "Desculpe...!",
  ui_story_5084_50841302_142_dialog_content = "Achei que você nunca apareceria, Cleves.",
  ui_story_5084_50841302_143_dialog_content = "Você achou que escondê-la com seus truques mudaria alguma coisa, Wilhelm?",
  ui_story_5084_50841302_144_dialog_content = "Doomed to a disgraceful death in your very own hometown... How I pity you, Wilhelm Varaki.",
  ui_story_5084_50841302_145_dialog_content = "...",
  ui_story_5084_50841302_146_dialog_content = "Bem, é irrelevante para o Anel de Varaki ser transmitido agora.",
  ui_story_5084_50841302_147_dialog_content = "<color=#e8d9bb>David Porfirio empurrou o canister ensanguentado atrás dele e aplicou a maior força que já havia exercido entre seus dedos.</color>",
  ui_story_5084_50841302_148_dialog_content = "<color=#e8d9bb>Ele esmagou o Anel de Varaki enquanto pó prateado e vermelho salpicava em Wilhelm.</color>",
  ui_story_5084_50841302_149_dialog_content = "What have you done? By crushing the ring, you've...",
  ui_story_5084_50841302_150_dialog_content = "It's useless to you or me now. Let the debris rest with Wilhelm in peace.",
  ui_story_5084_50841302_151_dialog_content = "From this day forth, it cannot be used to threaten us ever again.",
  ui_story_5084_50841302_152_dialog_content = "A algema que é o Grande Governante Varaki está no passado!",
  ui_story_5084_50841302_153_dialog_content = "Devo dizer, você certamente preparou um banquete delicioso para o Advento da Verdade, David!",
  ui_story_5084_50841302_154_dialog_content = "Mas Wilhelm está morto...!",
  ui_story_5084_50841302_155_dialog_content = "Sim, com a sua ajuda. Ainda devemos seguir a hierarquia ao provar o sangue Varaki.",
  ui_story_5084_50841302_156_dialog_content = "Depois de mim, é claro, meu amigo mais próximo—Cleves.",
  ui_story_5084_50841302_157_dialog_content = "Uma vez que meus caras estejam alimentados, Wilhelm é todo seu.",
  ui_story_5084_50841302_158_dialog_content = "Como vocês dois são velhos amigos, você pode dar a ele um enterro.",
  ui_story_5084_50841302_159_dialog_content = "Quer dizer, descansar eternamente em um caixão é uma de nossas tradições, afinal de contas.",
  ui_story_5084_50841302_160_dialog_content = "Mas não se esqueça de implorar a ele por perdão. Talvez ele ainda possa ouvir as palavras de um amigo que o apunhalou pelas costas.",
  ui_story_5084_50841302_161_dialog_content = "Então, você vai parar de dificultar para Charon e minha esposa agora?",
  ui_story_5084_50841302_162_dialog_content = "Claro. Mas Cleves, tem algo que eu não entendo bem... É verdade que meus caras te viram planejando se mudar?",
  ui_story_5084_50841302_163_dialog_content = "...",
  ui_story_5084_50841302_164_dialog_content = "Isso tornaria mais difícil para mim pedir mais favores a você, não seria?",
  ui_story_5084_50841302_165_dialog_content = "Você...!",
  ui_story_5084_50841302_166_dialog_content = "Hahaha!",
  ui_story_5084_50841302_167_dialog_content = "Tolo.",
  ui_story_5084_50841302_168_dialog_content = "Você tem ouvidos no chão, Corrida do Ouro. Não se esqueça de rastrear Victoria para mim.",
  ui_story_5084_50841302_169_dialog_content = "O que eu fiz... O que eu fiz?!",
  ui_story_5084_50841302_170_dialog_content = "<color=#e8d9bb>Cleves carregou o Wilhelm morto para a Tumba Varaki.</color>",
  ui_story_5084_50841302_171_dialog_content = "<color=#e8d9bb>No entanto, o guardião recusou seu pedido para enterrar Wilhelm dentro.</color>",
  ui_story_5084_50841302_172_dialog_content = "A chave universal—<color=#FFB400>Faria a Caixa Preta</color>!",
  ui_story_5084_50841302_173_dialog_content = "<color=#e8d9bb>A relíquia apareceu e rasgou uma fenda. Através da rachadura no Fluxo, Cleves entrou na cripta.</color>",
  ui_story_5084_50841302_174_dialog_content = "Este é o Túmulo Varaki, Wilhelm. Mesmo que nenhum outro lugar seja mais seguro para você, devo partir o mais rápido possível.",
  ui_story_5084_50841302_175_dialog_content = "Espero que você descanse em paz e retorne ao Senhor da Verdade como seus ancestrais fizeram.",
  ui_story_5084_50841302_176_dialog_content = "A chave só vai trazer problemas para mim.",
  ui_story_5084_50841302_177_dialog_content = "É inevitável que Porfírio descubra se eu deveria guardá-lo.",
  ui_story_5084_50841302_178_dialog_content = "Se os antepassados vissem o evento, que a agonia da traição seja minha punição.",
  ui_story_5084_50841302_179_dialog_content = "A Verdadeira Ordem... Varaki... Nós tentamos, mas não conseguimos controlar o destino deles.",
  ui_story_5084_50841302_180_dialog_content = "Wilhelm... Vampires... No final, todos nós permanecemos prisioneiros do destino, de qualquer maneira?",
  ui_story_5084_50841302_181_dialog_content = "<color=#e8d9bb>Enquanto o guardião do túmulo observava em silêncio, Cleves colocou a Caixa Negra dentro do caixão com Wilhelm.</color>",
  ui_story_5084_50841302_182_dialog_content = "<color=#e8d9bb>Nenhum deles estava ciente de que a chave universal abria arbitrariamente uma porta chamada \"Destino\".</color>",
  ui_story_5084_50841302_183_dialog_content = "Não vou tentar me defender. Eu mereço tudo isso.",
  ui_story_5084_50841302_184_dialog_content = "Pela traição, você deve se arrepender imediatamente ao Senhor da Verdade, Sr. Cleves.",
  ui_story_5084_50841302_185_dialog_content = "Não vou pedir o perdão do Senhor, pois nem consigo encarar Wilhelm.",
  ui_story_5084_50841302_186_dialog_content = "...",
  ui_story_5084_50841302_187_dialog_content = "Ninguém sabe sobre aquele lugar além de você e eu. E Wilhelm está morto.",
  ui_story_5084_50841302_188_dialog_content = "No dia em que decidi deixar a cidade de Varaki, você não estava procurando por Wilhelm. Você estava me procurando.",
  ui_story_5084_50841302_189_dialog_content = "Se você ficasse, eu confessaria tudo para você. Mas se você partisse...",
  ui_story_5084_50841302_190_dialog_content = "Você não teria dito uma palavra.",
  ui_story_5084_50841302_191_dialog_content = "Francamente, não passava um dia sem que eu sentisse a tormenta...",
  ui_story_5084_50841302_192_dialog_content = "Você pode tirar minha vida a qualquer momento que quiser. Tudo que peço é que me deixe fazer uma última coisa.",
  ui_story_5084_50841302_193_dialog_content = "...",
  ui_story_5084_50841302_194_dialog_content = "Você está bem, Sr. Cleve?",
  ui_story_5084_50841302_195_dialog_content = "Charon e minha esposa não têm nada a ver com tudo isso. Eu devo dar a eles uma ficha limpa.",
  ui_story_5084_50841302_196_dialog_content = "Mas mesmo que eu continue vivo, Charon provavelmente ainda vai me odiar com certeza...",
  ui_story_5084_50841302_197_dialog_content = "O que posso fazer? Talvez isso seja outro castigo para mim.",
  ui_story_5084_50841302_198_dialog_content = "Lembro de Charon me contando sobre seu pai. Eles realmente têm um relacionamento conturbado.",
  ui_story_5084_50841302_199_dialog_content = "...",
  ui_story_5084_50841302_200_dialog_content = "Ei, a vela está quase apagando, Victoria.",
  ui_story_5084_50841400_1_dialog_content = "Sobre essa \"Chave Universal\", Senhora Victoria...",
  ui_story_5084_50841400_2_dialog_content = "Mestre Cleves o enterrou com o Sr. Wilhelm, que agora não está em lugar nenhum, então isso é tudo que eu pude encontrar.",
  ui_story_5084_50841400_3_dialog_content = "Não é essa a Caixa Preta...?",
  ui_story_5084_50841400_4_dialog_content = "PlayerName...",
  ui_story_5084_50841400_5_dialog_content = "Oh, desculpe, esqueci que essas informações não pertencem aqui.",
  ui_story_5084_50841400_6_dialog_content = "Sei que você vai partir, então estou passando para a líder da Verdadeira Ordem, Senhora Victoria!",
  ui_story_5084_50841400_7_dialog_content = "Não, nenhum de nós pode esperar controlá-lo. Apenas deixe-o aqui.",
  ui_story_5084_50841400_8_dialog_content = "Certifique-se de que ninguém a toque, nem mesmo eu. Tudo deve seguir a vontade do Senhor.",
  ui_story_5084_50841400_9_dialog_content = "Tenho um pedido, Senhora Victoria. É possível não me fazer seu guardião?",
  ui_story_5084_50841400_10_dialog_content = "Você deveria ser o guardião dele. Quando meu pai o deu a Cleves, provavelmente ele já previa como seu destino se desdobraria.",
  ui_story_5084_50841400_11_dialog_content = "Eu não sei por quanto tempo conseguirei guardar o Túmulo Varaki.",
  ui_story_5084_50841400_12_dialog_content = "Com permissão, gostaria de abdicar da minha posição como governante da casa e ser uma videira em tempo integral que guarda o túmulo e aguarda a sua chegada.",
  ui_story_5084_50841400_13_dialog_content = "Posso lançar magia para fazer o túmulo desaparecer das mentes dos governantes, mas existe uma verdade que você mantém resoluta em seu coração?",
  ui_story_5084_50841400_14_dialog_content = "A verdade é que eu queria deixar o mundo desde o início, e essa tumba aconteceu de ser a escolha perfeita.",
  ui_story_5084_50841400_15_dialog_content = "Não tem nada a ver com quem lidera a Ordem. Claro, não estou questionando sua decisão, Senhora Victoria.",
  ui_story_5084_50841400_16_dialog_content = "Você ainda prefere guardar a tumba ao invés da liberdade?",
  ui_story_5084_50841400_17_dialog_content = "Minha família não existe mais. Estarei sozinho onde quer que eu esteja.",
  ui_story_5084_50841400_18_dialog_content = "Então, concederei a você o direito de buscar sua paz aqui.",
  ui_story_5084_50841400_19_dialog_content = "Você é o amigo mais leal dos Varakis. Você tem o direito de substituir David Porfirio e cuidar da cidade enquanto estou fora.",
  ui_story_5084_50841400_20_dialog_content = "Eu não ousaria sonhar com isso...!",
  ui_story_5084_50841400_21_dialog_content = "Mas esse é o final que você esperava. Você pode começar uma nova família e futuro.",
  ui_story_5084_50841400_22_dialog_content = "Lembro-me de você abandonando todas as associações passadas com Lumópolis, incluindo seu sobrenome.",
  ui_story_5084_50841400_23_dialog_content = "Vá em frente, escolha um novo sobrenome e deixe que seja a base de um novo começo.",
  ui_story_5084_50841400_24_dialog_content = "Eu entendo, minha senhora.",
  ui_story_5084_50841400_25_dialog_content = "Eu escolho... Dantes.",
  ui_story_5084_50841400_26_dialog_content = "A partir deste ponto, serei conhecido como Glave Dantes.",
  ui_story_5084_50841400_27_dialog_content = "(Dantes?! Ele é o antepassado de Sikare Dantes?)",
  ui_story_5084_50841400_28_dialog_content = "Já que você escolheu seu destino, vamos continuar.",
  ui_story_5084_50841400_29_dialog_content = "O seu clã sempre foi e sempre será um aliado confiável dos Varakis. A Caixa Preta vigiará a sua linhagem.",
  ui_story_5084_50841400_30_dialog_content = "Entendido. Vou me despedir agora.",
  ui_story_5084_50841400_31_dialog_content = "Ufa, parece que acabou.",
  ui_story_5084_50841400_32_dialog_content = "Terminamos com o Advento da Verdade aqui, mas há outro nos esperando de volta no Vortex.",
  ui_story_5084_50841400_33_dialog_content = "Não, isso significa três Advento da Verdade! Estou começando a sentir falta de Lenore...",
  ui_story_5084_50841400_34_dialog_content = "Ei, a vela realmente vai se apagar desta vez.",
  ui_story_5084_50841400_35_dialog_content = "...",
  ui_story_5084_50841400_36_dialog_content = "(Victoria parece estar esperando Wilhelm do jeito que ela olha para a distância...)",
  ui_story_5084_50841400_37_dialog_content = "Vamos.",
  ui_story_5084_50841400_38_dialog_content = "Você vai levar as duas bíblias com você, Senhora Victoria?",
  ui_story_5084_50841400_39_dialog_content = "Eles irão para onde devem ir no nosso caminho de volta. Vamos nos preparar.",
  ui_story_5084_50841400_40_dialog_content = "A vela apagou! Ei, você ainda está segurando a velha bíblia.",
  ui_story_5084_50841400_41_dialog_content = "Nos levou até aqui para que eu conhecesse sua nova versão, então é hora de eu devolvê-lo à mão do destino.",
  ui_story_5084_50841400_42_dialog_content = "Victoria?",
  ui_story_5084_50841400_43_dialog_content = "<color=#e8d9bb>Na escuridão que retorna, uma rachadura apareceu no torrente do tempo. Um longo e estranho fragmento podia ser vislumbrado na névoa.</color>",
  ui_story_5084_50841400_44_dialog_content = "<color=#e8d9bb>Victoria largou a bíblia que esteve com ela por muitos anos e a observou nadar na torrente.</color>",
  ui_story_5084_50841400_45_dialog_content = "Pra onde ele foi?",
  ui_story_5084_50841400_46_dialog_content = "Olhe para a torrente, e você pode ver A Verdade.",
  ui_story_5084_50841400_47_dialog_content = "Qualquer um de nós é apenas areia no rio. No final, retornaremos ao Senhor da Verdade.",
  ui_story_5084_50841400_48_dialog_content = "Vá e cumpra seu destino.",
  ui_story_5084_50841400_49_dialog_content = "<color=#e8d9bb>A bíblia fluiu \"a jusante\" e partiu os \"estranhos do futuro\".</color>",
  ui_story_5084_50841400_50_dialog_content = "<color=#e8d9bb>Ele flutuava pacificamente no Rio Prístino enquanto inúmeras imagens apareciam nas ondulações de seu curso, mostrando o passado e o futuro.</color>",
  ui_story_5084_50841400_51_dialog_content = "<color=#e8d9bb>Suas páginas se abriram sozinhas e conjuraram letras nas folhas anteriormente em branco.</color>",
  ui_story_5084_50841400_52_dialog_content = "<color=#e8d9bb>Assim, o destino foi escrito...</color>",
  ui_story_5084_50841400_53_dialog_content = "<color=#e8d9bb>O reflexo da bíblia foi lançado nas histórias e o tomo começou a receber reconhecimento. Finalmente, era parte do rio.</color>",
  ui_story_5084_50841400_54_dialog_content = "<color=#e8d9bb>\"Wilhelm pegou a Bíblia Sangrenta que veio de partes desconhecidas. Ele sentiu a presença de revelações dentro e decidiu levá-la a um Victoria adormecido.\"</color>",
  ui_story_5084_50841400_55_dialog_content = "<color=#e8d9bb>\"A jovem Victoria folheou o tomo em branco e ouviu a profecia da Verdade pela primeira vez.\"</color>",
  ui_story_5084_50841400_56_dialog_content = "<color=#e8d9bb>O livro continuou fluindo rio abaixo. O tempo não tinha nem começo nem fim no rio, mas um ciclo sem fim.</color>",
  ui_story_5084_50841400_57_dialog_content = "<color=#e8d9bb>\"Portanto, Victoria soltou a bíblia que esteve com ela por muitos anos e a observou nadar na torrente.\"</color>",
  ui_story_5084_50841400_58_dialog_content = "Todos os viajantes retornaram aos seus respectivos tempos. Eu também deveria terminar meu trabalho.",
  ui_story_5084_50841400_59_dialog_content = "Victoria do ano de 1918, você ainda está no caminho para descobrir A Verdade. Você ainda estava perdido e tudo deve ter parecido confuso para você.",
  ui_story_5084_50841400_60_dialog_content = "Está tudo bem. O tempo vai te levar até lá.",
  ui_story_5084_50841400_61_dialog_content = "Você embarcará em uma longa jornada antes de alcançar a iluminação.",
  ui_story_5084_50841400_62_dialog_content = "Então você os levará de volta a este exato ponto e nos encontraremos novamente.",
  ui_story_5084_50841400_63_dialog_content = "<color=#e8d9bb>Wilhelm entregou o Victoria adormecido de Vortex para ela e colocou a Bíblia Sangrenta em sua mão.</color>",
  ui_story_5084_50841400_64_dialog_content = "<color=#e8d9bb>Ele então se deitou dentro do caixão no qual ele veio e ponderou sobre seu passado.</color>",
  ui_story_5084_50841400_65_dialog_content = "Quando você, ainda criança, me conheceu pela primeira vez, foi porque seu irmão desejava confiar você a mim, pois estava prestes a morrer.",
  ui_story_5084_50841400_66_dialog_content = "Então eu poderia me tornar o líder?",
  ui_story_5084_50841400_67_dialog_content = "Sim, e então cuide de Victoria.",
  ui_story_5084_50841400_68_dialog_content = "<color=#e8d9bb>Victoria ficou em silêncio ao lado de seus pais, sem compreender o motivo de sua satisfação, mesmo estando à beira da morte.</color>",
  ui_story_5084_50841400_69_dialog_content = "<color=#e8d9bb>Mas Wilhelm Varaki, que suportou inúmeras humilhações, não conseguia suportar a ideia de levar o despedaçado Victoria pelo caminho fatídico dos vampiros.</color>",
  ui_story_5084_50841400_70_dialog_content = "Pare de gastar saliva. Eu não vou fazer isso.",
  ui_story_5084_50841400_71_dialog_content = "...",
  ui_story_5084_50841400_72_dialog_content = "<color=#e8d9bb>Mas no dia do funeral, Wilhelm ainda vestia o traje de um discípulo e observava seu irmão e cunhada deixarem a cidade de Varaki em caixões.</color>",
  ui_story_5084_50841400_73_dialog_content = "<color=#e8d9bb>Wilhelm permaneceu do lado de fora do Túmulo Varaki, ouvindo as \"saudações\" dos mestres para Victoria.</color>",
  ui_story_5084_50841400_74_dialog_content = "<color=#e8d9bb>As forças da tempestade e do relâmpago, que pareciam destinadas a despedaçar o mundo, refletiam as emoções de Wilhelm.</color>",
  ui_story_5084_50841400_75_dialog_content = "<color=#e8d9bb>Ele avançou para o coração do túmulo apenas para colocar o Anel de Varaki que poderia corrompê-lo diante dos mestres...</color>",
  ui_story_5084_50841400_76_dialog_content = "<color=#e8d9bb>Apenas para proteger a garota que estava prestes a embarcar na busca pela Verdade com ele.</color>",
  ui_story_5084_50841400_77_dialog_content = "<color=#e8d9bb>Não havia sido um relacionamento feliz entre eles, mas Wilhelm deve compelir Victoria a parar de resistir à Ordem e a se tornar mais forte.</color>",
  ui_story_5084_50841400_78_dialog_content = "<color=#e8d9bb>O tempo todo procurando qualquer opção para mantê-los seguros.</color>",
  ui_story_5084_50841400_79_dialog_content = "<color=#e8d9bb>Também sobre a sua própria morte...</color>",
  ui_story_5084_50841400_80_dialog_content = "Cleves...",
  ui_story_5084_50841400_81_dialog_content = "I know you'll understand from caring for Victoria.",
  ui_story_5084_50841400_82_dialog_content = "Victoria...",
  ui_story_5084_50841400_83_dialog_content = "He...",
  ui_story_5084_50841400_84_dialog_content = "(De acordo com as tradições vampíricas, a morte é talvez uma bênção.)",
  ui_story_5084_50841400_85_dialog_content = "(Mas este eu não sente mais a dor da traição de outros.)",
  ui_story_5084_50841400_86_dialog_content = "(Entendo o quão difícil é para você, mas o que vai acontecer com Victoria agora?)",
  ui_story_5084_50841400_87_dialog_content = "(Eu passei toda a Verdade que aprendi para ela?)",
  ui_story_5084_50841400_88_dialog_content = "(Ela iria me dizer que está em um caminho inabalável para A Verdade antes de partir?)",
  ui_story_5084_50841400_89_dialog_content = "(...)",
  ui_story_5084_50841400_90_dialog_content = "<color=#e8d9bb>Wilhelm nunca parou com as perguntas para A Verdade quando sua mente se voltou para um rio claro.</color>",
  ui_story_5084_50841400_91_dialog_content = "O que está acontecendo? Eu não estava na igreja...? Eu deveria estar morto agora.",
  ui_story_5084_50841400_92_dialog_content = "Onde estou?",
  ui_story_5084_50841400_93_dialog_content = "O Reino dos Mortos, ou o Templo do Senhor da Verdade?",
  ui_story_5084_50841400_94_dialog_content = "O que é este rio?",
  ui_story_5084_50841400_95_dialog_content = "<color=#e8d9bb>Wilhelm flutuava infinitamente sem se mover, mas sua mente absorvia todas as informações do mundo.</color>",
  ui_story_5084_50841400_96_dialog_content = "<color=#e8d9bb>Uma década? Um século? Quanto tempo se passou...?</color>",
  ui_story_5084_50841400_97_dialog_content = "<color=#e8d9bb>Eoria escureceu e clareou novamente, enquanto o conflito entre Aurorianos e Eclipsitas continuava.</color>",
  ui_story_5084_50841400_98_dialog_content = "<color=#e8d9bb>Mas ele passou por tudo isso.</color>",
  ui_story_5084_50841400_99_dialog_content = "É esse eu?",
  ui_story_5084_50841400_100_dialog_content = "Isso não é o desejo dela, mas é o seu destino. Coloque esta nova Bíblia Sangrenta no caixão para mim. Ela vai achar útil.",
  ui_story_5084_50841400_101_dialog_content = "Sim, Sr. Wilhelm.",
  ui_story_5084_50841400_102_dialog_content = "E quando chegar essa hora...",
  ui_story_5084_50841400_103_dialog_content = "Por que você está triste? Você pode simplesmente começar uma família e acabar com isso.",
  ui_story_5084_50841400_104_dialog_content = "Começar uma família e criar crianças? Que chato.",
  ui_story_5084_50841400_105_dialog_content = "<color=#e8d9bb>Muitas versões de Wilhelm estavam espalhadas por todos os lugares, mas empilhadas umas sobre as outras. Era puro caos até que ele viu presenças além de si mesmo.</color>",
  ui_story_5084_50841400_106_dialog_content = "Não devo levar crédito por isso. Esta é uma bênção do Senhor da Verdade.",
  ui_story_5084_50841400_107_dialog_content = "O que é isso?!",
  ui_story_5084_50841400_108_dialog_content = "O <color=#FFB400>Rio Pristino</color>, fora do tempo e do espaço. A única diferença do mundo exterior é que ele flui.",
  ui_story_5084_50841400_109_dialog_content = "Não conseguiremos controlar nossas vidas se isso continuar! Por que você nos trouxe aqui?",
  ui_story_5084_50841400_110_dialog_content = "Victoria?!",
  ui_story_5084_50841400_111_dialog_content = "Ehe, hahaha!",
  ui_story_5084_50841400_112_dialog_content = "Eu sabia que você poderia fazer isso, Victoria Varaki.",
  ui_story_5084_50841400_113_dialog_content = "E Charon também.",
  ui_story_5084_50841400_114_dialog_content = "Fizemos isso como seu ancião, Cleves.",
  ui_story_5084_50841400_115_dialog_content = "<color=#e8d9bb>À medida que as memórias desvaneciam, Wilhelm levantou-se apenas para perceber que não estava em seu caixão - mas observando e imergindo no sempre fluente Rio Prístino.</color>",
  ui_story_5084_50841400_116_dialog_content = "<color=#e8d9bb>Tudo o que ele interferiu iria envolvê-lo e levá-lo à Afirmação da Verdade.</color>",
  ui_story_5084_50841400_117_dialog_content = "<color=#e8d9bb>Então...</color>",
  ui_story_5084_50841400_118_dialog_content = "<color=#e8d9bb>O tomo largado por Victoria parou de flutuar porque encontrou uma barreira - um \"morto\" deitado no rio.</color>",
  ui_story_5084_50841400_119_dialog_content = "<color=#e8d9bb>Este corpo traído de Wilhelm, o cara que a Porta do Destino chamou, despertou no maravilhoso riacho.</color>",
  ui_story_5084_50841400_120_dialog_content = "...?!",
  ui_story_5084_50841400_121_dialog_content = "<color=#e8d9bb>O confuso Wilhelm conseguiu notar a Bíblia Sangrenta parando aos seus pés no rio.</color>",
  ui_story_5084_50841400_122_dialog_content = "<color=#e8d9bb>Como se respondesse a um chamado silencioso, ele folheou o tomo totalmente em branco e começou a ver...</color>",
  ui_story_5084_50841400_123_dialog_content = "<color=#e8d9bb>\"A Bíblia Sangrenta flutua e para ao lado dos pés mortos de Wilhelm. O jovem vampiro acorda devido a uma gota de sangue em um anel de destroços.\"</color>",
  ui_story_5084_50841400_124_dialog_content = "<color=#e8d9bb>\"O confuso Wilhelm consegue notar a Bíblia Sangrenta parando aos seus pés no rio.\"</color>",
  ui_story_5084_50841400_125_dialog_content = "O quê?",
  ui_story_5084_50841400_126_dialog_content = "<color=#e8d9bb>\"Assustado, Wilhelm tropeça para trás no rio, mergulhando na água que perturbou e contaminando suas causas e efeitos.\"</color>",
  ui_story_5084_50841400_127_dialog_content = "<color=#e8d9bb>\"Sentado no rio, Wilhelm percebe que tem algo em sua mão. Ao pegá-lo com um arrepio, ele percebe que é...\"</color>",
  ui_story_5084_50841400_128_dialog_content = "O anel ancestral de Varaki?",
  ui_story_5084_50841400_129_dialog_content = "O que tudo isso significa?",
  ui_story_5084_50841400_130_dialog_content = "<color=#e8d9bb>\"Tendo recebido o chamado, Wilhelm está destinado a vagar e levar outros à Verdade.\"</color>",
  ui_story_5084_50841400_131_dialog_content = "<color=#e8d9bb>\"Quando chegar a hora certa, o Túmulo Varaki se abrirá para Victoria. Wilhelm, Servo da Verdade, será seu guia.\"</color>",
  ui_story_5084_50841400_132_dialog_content = "<color=#e8d9bb>\"Wilhelm então se deita dentro do caixão no qual ele veio e pondera sobre seu passado.\"</color>",
  ui_story_5084_50841400_133_dialog_content = "<color=#e8d9bb>\"Quando ele perceber que seu propósito foi cumprido e Victoria está pronto, ele finalmente descansará em paz?\"</color>",
  ui_story_5084_50841400_134_dialog_content = "<color=#e8d9bb>\"Mas quando ele toca o anel, uma gota de sangue Varaki dentro dele percorre seu corpo. Ele cai em um sono profundo à medida que a sensação familiar retorna.\"</color>",
  ui_story_5084_50841400_135_dialog_content = "<color=#e8d9bb>\"Quando Wilhelm acordar novamente, ele será guiado para a encruzilhada do destino.\"</color>",
  ui_story_5084_50841400_136_dialog_content = "Onde estou...",
  ui_story_5084_50841400_137_dialog_content = "Embora a Senhora Victoria tenha me dito que a devoção me mostraria o caminho...",
  ui_story_5084_50841400_138_dialog_content = "Mas eu vou me sacrificar...",
  ui_story_5084_50841400_139_dialog_content = "I will...",
  ui_story_5084_50841400_140_dialog_content = "...",
  ui_story_5084_50841400_141_dialog_content = "... My lord?",
  ui_story_5084_50841400_142_dialog_content = "O grande Senhor da Verdade!",
  ui_story_5084_50841400_143_dialog_content = "Did you just say... Lady Victoria?",
  ui_story_5084_50841400_144_dialog_content = "<color=#e8d9bb>\"O tempo não tem nem começo nem fim no rio, mas um ciclo sem fim.\"</color>",
  ui_story_5084_50841400_145_dialog_content = "<color=#e8d9bb>\"Assim, Victoria solta a bíblia que esteve com ela por muitos anos e a observa nadar na torrente.\"</color>",
  ui_story_5084_50841400_146_dialog_content = "Você voltou.",
  ui_story_5084_50841400_147_dialog_content = "Sim. A vela sumiu.",
  ui_story_5084_50841400_148_dialog_content = "Esse tipo de poder pertencia a Faria.",
  ui_story_5084_50841400_149_dialog_content = "Feche, Faria.",
  ui_story_5084_50841400_150_dialog_content = "(Entendi... Então a Cripta Estrelada era o Túmulo Varaki naquela época.)",
  ui_story_5084_50841400_151_dialog_content = "Nos encontramos de novo, \"Chave Universal.\"",
  ui_story_5084_50841400_152_dialog_content = "Senhorita Victoria?",
  ui_story_5084_50841400_153_dialog_content = "Heh, por favor, desculpe meu murmúrio para mim mesmo.",
  ui_story_5084_50841400_154_dialog_content = "Claro.",
  ui_story_5084_50841400_155_dialog_content = "May?",
  ui_story_5084_50841400_156_dialog_content = "O que está fazendo aqui, May?",
  ui_story_5084_50841400_157_dialog_content = "Você não estava em casa depois que o pão foi feito, então imaginei que você veio ver Sikare. Eu não esperava ver a Senhorita Victoria e todos os outros aqui também.",
  ui_story_5084_50841400_158_dialog_content = "Espere, acho que ouvi alguém mencionar comida...",
  ui_story_5084_50841400_159_dialog_content = "Pão agradável e vinho... todos preparados pessoalmente por May para o Advento da Verdade!",
  ui_story_5084_50841400_160_dialog_content = "Agora que você disse isso, estou com fome.",
  ui_story_5084_50841400_161_dialog_content = "Você virá para a celebração conosco, não é, Sikare?",
  ui_story_5084_50841400_162_dialog_content = "Sim. Certamente vou responder ao convite de Victoria.",
  ui_story_5084_50841400_163_dialog_content = "Está na hora. Os membros da Ordem devem estar se reunindo na cidade, Senhora Victoria.",
  ui_story_5084_50841400_164_dialog_content = "Todos da Ordem estarão lá?",
  ui_story_5084_50841400_165_dialog_content = "Você estava relutante quando o convidamos. Está cheio de expectativa agora?",
  ui_story_5084_50841400_166_dialog_content = "Não posso dizer que vejo meus amigos da Ordem com frequência, mas é sempre bom estar na companhia deles.",
  ui_story_5084_50841400_167_dialog_content = "Bem-vindos, todos, à celebração trienal da Verdadeira Ordem.",
  ui_story_5084_50841400_168_dialog_content = "Nos três anos desde então, estamos um passo mais perto de entender Eoria, bem como o Senhor da Verdade.",
  ui_story_5084_50841400_169_dialog_content = "Além do Senhor imortal, não seguimos nenhum preceito fixo, independentemente de nossa origem.",
  ui_story_5084_50841400_170_dialog_content = "Seja nossas individualidades únicas, escapando das algemas do passado, ou cumprindo um determinado propósito...",
  ui_story_5084_50841400_171_dialog_content = "Devido à transformação contínua, estamos brilhando intensamente na jornada em direção à Verdade.",
  ui_story_5084_50841400_172_dialog_content = "A True Order que você vê agora está no caminho abençoado pela Verdade.",
  ui_story_5084_50841400_173_dialog_content = "Posso garantir que aqueles vampiros fora de Astra com laços próximos à Ordem estão prontos.",
  ui_story_5084_50841400_174_dialog_content = "E eu conduzirei todos vocês para testemunhar a chegada do Senhor da Verdade.",
  ui_story_5084_50841400_175_dialog_content = "Na Crise de Darkover, a Bíblia Sangrenta revelou uma enorme revolução a caminho.",
  ui_story_5084_50841400_176_dialog_content = "Os revolucionários que eu estava nutrindo naquela época amadureceram.",
  ui_story_5084_50841400_177_dialog_content = "O cadeado aparecerá na Zona Escura. Eu trarei a chave para o destino e reconstruirei o reino com o Senhor.",
  ui_story_5084_50841400_178_dialog_content = "Será uma jornada traiçoeira através da Zona Escura. Mais uma vez, a True Order guiará os Aurorianos através da crise como seu aliado.",
  ui_story_5084_50841400_179_dialog_content = "Agora, por favor, aproveite o banquete.",
  ui_story_5084_50841400_180_dialog_content = "Foi Ele quem me honrou e concedeu a Nutrição da Verdade a você.",
  ui_story_5084_50841400_181_dialog_content = "Você também é bem-vindo para trocar sua iluminação pessoal com os outros.",
  ui_story_5084_50841400_182_dialog_content = "Que a Verdade abençoe você.",
  ui_story_5084_50841400_183_dialog_content = "Que a Verdade abençoe você.",
  ui_story_5084_50841400_184_dialog_content = "Você tem espiado o Faust por um tempo agora, Pasolo. Tem algo errado com ele?",
  ui_story_5084_50841400_185_dialog_content = "Bem, Sr. Faust, é sobre as almas dos meus pais falecidos. A Srta. Sikare pensou que talvez você pudesse me oferecer uma nova perspectiva...",
  ui_story_5084_50841400_186_dialog_content = "Se é uma nova perspectiva que você quer, tente Nails. Ele se desenvolveu mais do que qualquer um recentemente.",
  ui_story_5084_50841400_187_dialog_content = "<color=#e8d9bb>Rumble, rumble...</color>",
  ui_story_5084_50841400_188_dialog_content = "Ajude-me a parar a coisa, PlayerName!",
  ui_story_5084_50841400_189_dialog_content = "Ah não, é muito rápido... e está rolando em direção a Nails!",
  ui_story_5084_50841400_190_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5084_50841400_191_dialog_content = "Desculpe, Sr. Nails! Hunting Stone não te machucou, não é?",
  ui_story_5084_50841400_192_dialog_content = "Não, Senhorita Pact. Se você deseja me fazer sentir dor, pode me espetar com espinhos aqui.",
  ui_story_5084_50841400_193_dialog_content = "Sr. Nails! Você não prometeu que não se machucaria esta noite? Isso tem algo a ver com sua nova roupa?",
  ui_story_5084_50841400_194_dialog_content = "Sr. Nails, o Sr. Faust me disse que você poderia me dar uma nova perspectiva sobre almas.",
  ui_story_5084_50841400_195_dialog_content = "Ah, perspectiva... Meu mentor realmente me ofereceu alguma.",
  ui_story_5084_50841400_196_dialog_content = "Acredito que a alma é a concentração do espírito de alguém. Enquanto o espírito permanecer, alguém nunca realmente se foi.",
  ui_story_5084_50841400_197_dialog_content = "Eu vejo... Então, será que vou conseguir ver o falecido novamente?",
  ui_story_5084_50841400_198_dialog_content = "Talvez Victoria tenha a resposta para isso.",
  ui_story_5084_50841400_199_dialog_content = "Ei, faz muito tempo e posso sentir a aura sagrada me atingindo.",
  ui_story_5084_50841400_200_dialog_content = "Como vai, Sr. Telamont.",
  ui_story_5084_50841400_201_dialog_content = "Você pegou algo no seu tempo com a Senhora Victoria?",
  ui_story_5084_50841400_202_dialog_content = "Foi uma honra para mim conhecer um mentor importante. Foi ele quem me levou à minha transformação sob o Senhor.",
  ui_story_5084_50841400_203_dialog_content = "Eu não achava que os ascetas poderiam vir. Seu mentor está aqui agora?",
  ui_story_5084_50841400_204_dialog_content = "Tenho vergonha de admitir que eu não sei...",
  ui_story_5084_50841400_205_dialog_content = "Senhora Victoria, Sr. Nails disse, \"Enquanto o espírito permanecer, nunca se está verdadeiramente ausente.\"",
  ui_story_5084_50841400_206_dialog_content = "Isso significa que meus pais mortos estiveram comigo todo esse tempo?",
  ui_story_5084_50841400_207_dialog_content = "Os Aurorianos nasceram da luz da fé. Seu poder espiritual veio de um rio alto.",
  ui_story_5084_50841400_208_dialog_content = "Você deveria rezar para que alguns dos espíritos de seus pais retornassem lá.",
  ui_story_5084_50841400_209_dialog_content = "Eu deveria rezar por eles...",
  ui_story_5084_50841400_210_dialog_content = "Obrigado pela resposta, Senhora Victoria. Vou refletir um pouco mais sobre isso...",
  ui_story_5084_50841400_211_dialog_content = "<color=#e8d9bb>Victoria ficou emocionado ao ver o quão forte a Ordem se tornou.</color>",
  ui_story_5084_50841400_212_dialog_content = "<color=#e8d9bb>Foi o resultado do passado de Wilhelm e seu eu presente eliminando as barreiras para o jovem Victoria seguir em frente.</color>",
  ui_story_5084_50841400_213_dialog_content = "<color=#e8d9bb>A orientação que receberam poderia vir de alguém do passado ou do futuro, tentando ao máximo transmitir sua intenção no fluxo do tempo e do espaço.</color>",
  ui_story_5084_50841400_214_dialog_content = "<color=#e8d9bb>Victoria viu inúmeros viajantes no Rio do Destino, cada um representando a coragem de buscar A Verdade.</color>",
  ui_story_5084_50841400_215_dialog_content = "<color=#e8d9bb>Tudo seria visto por alguém à deriva no fluxo do tempo.</color>",
  ui_story_5084_50841400_216_dialog_content = "<color=#e8d9bb>As correntes alternariam conforme escrito no tomo, mas Victoria não tinha desejo de virar a página tão rapidamente.</color>",
  ui_story_5084_50841400_217_dialog_content = "Isso significa que você acredita em reclusão tanto quanto eu?",
  ui_story_5084_50841400_218_dialog_content = "Embora eu possa entender por que eles não compareceriam a nenhuma celebração, é sempre assim com os reclusos.",
  ui_story_5084_50841400_219_dialog_content = "Os reclusos têm sua própria organização?",
  ui_story_5084_50841400_220_dialog_content = "Não exatamente, mas diz-se que a seita foi fundada por um misterioso discípulo masculino na Cidade Varaki por volta de 1915.",
  ui_story_5084_50841400_221_dialog_content = "A senhora Victoria nunca te contou?",
  ui_story_5084_50841400_222_dialog_content = "Em comparação com a sua presença nas cidades aurorianas, eu só conheci um punhado de reclusos auto-proclamados na natureza.",
  ui_story_5084_50841400_223_dialog_content = "O que você costuma fazer?",
  ui_story_5084_50841400_224_dialog_content = "Procure espaços vazios ou explore cantos escondidos.",
  ui_story_5084_50841400_225_dialog_content = "Then what?",
  ui_story_5084_50841400_226_dialog_content = "Fique lá e não faça nada.",
  ui_story_5084_50841400_227_dialog_content = "Essa chamada reclusão me soa como não querer aprender com os livros...",
  ui_story_5084_50841400_228_dialog_content = "Provavelmente isso é porque não havia nenhum livro que um mestre recluso não tivesse lido.",
  ui_story_5084_50841400_229_dialog_content = "Mas por que tenho a sensação de que, no seu caso, você tem os livros mas escolheu não lê-los...",
  ui_story_5084_50841400_230_dialog_content = "Ele deve ser uma grande figura! May Posso perguntar o nome dele?",
  ui_story_5084_50841400_231_dialog_content = "Ninguém sabe o nome dele, mas eu o vi.",
  ui_story_5084_50841400_232_dialog_content = "Esbelto, com um certo ar de nobreza tradicional...",
  ui_story_5084_50841400_233_dialog_content = "Porque ele costuma usar uma cartola preta, uma capa preta avermelhada e um cavalo preto.",
  ui_story_5084_50841400_234_dialog_content = "...?",
  ui_story_5084_50841400_235_dialog_content = "Ele é inescrutável e viaja muito. Alguns afirmaram que ele esperava uma chance de encontrar um velho amigo.",
  ui_story_5084_50841400_236_dialog_content = "Poderia ser meu mentor?",
  ui_story_5084_50841400_237_dialog_content = "Quem?",
  ui_story_5084_50841400_238_dialog_content = "O velho amigo que ele gostaria de encontrar...",
  ui_story_5084_50841400_239_dialog_content = "<color=#e8d9bb>\"Quando todas as coisas tiverem terminado, venha me encontrar aqui,\" foi o que ele disse.</color>",
  ui_story_5084_50841400_240_dialog_content = "<color=#e8d9bb>Victoria ainda estava perto da janela enquanto ela via através do tempo e ficava fixada nas figuras que perseguiam a Verdade.</color>",
  ui_story_5084_50841400_241_dialog_content = "<color=#e8d9bb>Como as estrelas no céu noturno, algumas delas eram brilhantes, outras fracas, mas cada uma delas interpretava a Verdade à sua maneira.</color>",
  ui_story_5084_50841400_242_dialog_content = "<color=#e8d9bb>Victoria entendeu que buscar a Verdade é como perseguir estrelas distantes e exigiu discernimento dos olhos da mente.</color>",
  ui_story_5084_50841400_243_dialog_content = "<color=#e8d9bb>Mas ele era apenas o guia que os conduzia adiante.</color>",
  ui_story_5084_50841400_244_dialog_content = "<color=#e8d9bb>Fora da janela, ele suspirou. Ele passou a ver cada membro da Verdadeira Ordem como sua criança.</color>",
  ui_story_5084_50841400_245_dialog_content = "<color=#e8d9bb>Ele sabia que, independentemente de quão árduo fosse o caminho para eles, Victoria sempre forneceria luz na hora mais escura.</color>",
  ui_story_5084_50841400_246_dialog_content = "<color=#e8d9bb>Mas só ele sabia que a mulher ao lado da janela também era uma buscadora solitária.</color>",
  ui_story_5084_50841400_247_dialog_content = "<color=#e8d9bb>Victoria fechou os olhos e deixou seu coração ecoar pela noite.</color>",
  ui_story_5084_50841400_248_dialog_content = "<color=#e8d9bb>Ela entendeu que existem diferentes caminhos para a Verdade, seja na solidão ou numa Ordem barulhenta.</color>",
  ui_story_5084_50841400_249_dialog_content = "<color=#e8d9bb>\"A Verdade é uma busca interminável,\" ele murmurou.</color>",
  ui_story_5084_50841400_250_dialog_content = "<color=#e8d9bb>\"E eu vou vigiar você e orientá-lo em sua jornada.\"</color>"
}
return config
